"use client";

import { useState, useEffect, useCallback } from "react";
import { useAuth } from "@/lib/AuthContext";
import {
  getAdminApprovals,
  approveOrgAdmin,
  rejectOrgAdmin,
  getApprovedOrgAdmins,
} from "@/lib/api";
import LoadingSpinner from "@/components/LoadingSpinner";
import { Check, X, ChevronDown, ChevronUp } from "lucide-react";

interface ApprovalRequest {
  id: number;
  username: string;
  email: string;
  first_name: string;
  last_name: string;
  phone_number: string;
  approval_status: "PENDING" | "APPROVED" | "REJECTED";
  organization_name: string;
  organization_type: string;
  rejection_reason?: string;
  approval_requested_at?: string;
  approval_decided_at?: string;
  approval_decided_by_username?: string;
}

interface ConfirmationDialog {
  isOpen: boolean;
  type: "approve" | "reject" | null;
  userId: number | null;
  userName: string;
}

export default function ApprovalsPage() {
  const { user } = useAuth();
  const [activeTab, setActiveTab] = useState<"pending" | "approved">("pending");
  const [pendingRequests, setPendingRequests] = useState<ApprovalRequest[]>([]);
  const [approvedRequests, setApprovedRequests] = useState<ApprovalRequest[]>(
    [],
  );
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [rejectingId, setRejectingId] = useState<number | null>(null);
  const [rejectionReason, setRejectionReason] = useState("");
  const [expandedCardId, setExpandedCardId] = useState<number | null>(null);
  const [confirmDialog, setConfirmDialog] = useState<ConfirmationDialog>({
    isOpen: false,
    type: null,
    userId: null,
    userName: "",
  });

  const sortByNewest = (requests: ApprovalRequest[]): ApprovalRequest[] => {
    return [...requests].sort((a, b) => {
      const dateA = a.approval_decided_at || a.approval_requested_at || "";
      const dateB = b.approval_decided_at || b.approval_requested_at || "";
      return new Date(dateB).getTime() - new Date(dateA).getTime();
    });
  };

  const loadAllApprovals = useCallback(async () => {
    try {
      setLoading(true);
      setError("");
      const [pending, approved] = await Promise.all([
        getAdminApprovals(),
        getApprovedOrgAdmins(),
      ]);
      setPendingRequests(sortByNewest(pending));
      setApprovedRequests(sortByNewest(approved));
    } catch (err: unknown) {
      const error = err as Error;
      setError("Failed to load approval requests");
      console.error(error);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadAllApprovals();
  }, [loadAllApprovals]);

  const handleApprove = async (id: number) => {
    const request = pendingRequests.find((r) => r.id === id);
    if (!request) return;

    setConfirmDialog({
      isOpen: true,
      type: "approve",
      userId: id,
      userName: `${request.first_name} ${request.last_name}`,
    });
  };

  const handleApproveConfirm = async () => {
    if (!confirmDialog.userId) return;

    try {
      const result = await approveOrgAdmin(confirmDialog.userId);
      setPendingRequests(
        pendingRequests.filter((r) => r.id !== confirmDialog.userId),
      );
      setApprovedRequests([...approvedRequests, result.user]);
      setConfirmDialog({
        isOpen: false,
        type: null,
        userId: null,
        userName: "",
      });
      alert("Admin approved successfully!");
    } catch (err: any) {
      setError(err.message || "Failed to approve");
      setConfirmDialog({
        isOpen: false,
        type: null,
        userId: null,
        userName: "",
      });
    }
  };

  const handleReject = async (id: number) => {
    const request = pendingRequests.find((r) => r.id === id);
    if (!request) return;

    setRejectingId(id);
  };

  const handleRejectConfirm = async () => {
    if (!rejectionReason.trim()) {
      setError("Please provide a rejection reason");
      return;
    }

    const request = pendingRequests.find((r) => r.id === rejectingId);
    if (!request) return;

    setConfirmDialog({
      isOpen: true,
      type: "reject",
      userId: rejectingId,
      userName: `${request.first_name} ${request.last_name}`,
    });
  };

  const handleRejectConfirmationAccept = async () => {
    if (!confirmDialog.userId) return;

    try {
      const result = await rejectOrgAdmin(
        confirmDialog.userId,
        rejectionReason,
      );
      setPendingRequests(
        pendingRequests.filter((r) => r.id !== confirmDialog.userId),
      );
      setRejectingId(null);
      setRejectionReason("");
      setConfirmDialog({
        isOpen: false,
        type: null,
        userId: null,
        userName: "",
      });
      alert("Request rejected successfully!");
    } catch (err: any) {
      setError(err.message || "Failed to reject");
      setConfirmDialog({
        isOpen: false,
        type: null,
        userId: null,
        userName: "",
      });
      setRejectingId(null);
      setRejectionReason("");
    }
  };

  const handleConfirmCancel = () => {
    setConfirmDialog({ isOpen: false, type: null, userId: null, userName: "" });
  };

  if (!user || user.role !== "ADMIN") {
    return (
      <div className="text-center py-12">
        <p className="text-red-600">
          Access denied. Only system admins can view this page.
        </p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 py-8 px-4 sm:px-6 lg:px-8">
      <div className="max-w-7xl mx-auto">
        <h1 className="text-3xl font-bold text-gray-900">
          Organization Admin Approvals
        </h1>
        <p className="text-gray-500 mt-1 mb-3">
          Review and approve organization admins
        </p>

        {error && (
          <div className="mb-6 bg-red-50 border border-red-200 text-red-800 px-4 py-3 rounded">
            {error}
          </div>
        )}

        {/* Tab Navigation */}
        <div className="mb-6 border-b border-gray-200">
          <div className="flex space-x-8">
            <button
              onClick={() => setActiveTab("pending")}
              className={`px-1 py-4 font-medium text-sm border-b-2 transition ${
                activeTab === "pending"
                  ? "border-blue-500 text-blue-600"
                  : "border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300"
              }`}
            >
              Pending ({pendingRequests.length})
            </button>
            <button
              onClick={() => setActiveTab("approved")}
              className={`px-1 py-4 font-medium text-sm border-b-2 transition ${
                activeTab === "approved"
                  ? "border-blue-500 text-blue-600"
                  : "border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300"
              }`}
            >
              Approved ({approvedRequests.length})
            </button>
          </div>
        </div>

        {loading ? (
          <div className="flex justify-center py-12">
            <LoadingSpinner />
          </div>
        ) : (
          <>
            {/* Pending Requests Tab */}
            {activeTab === "pending" && (
              <div>
                {pendingRequests.length === 0 ? (
                  <div className="text-center py-12 bg-white rounded-lg">
                    <p className="text-gray-600">
                      No pending approval requests
                    </p>
                  </div>
                ) : (
                  <div className="space-y-4">
                    {pendingRequests.map((req) => (
                      <RequestCard
                        key={req.id}
                        req={req}
                        isPending={true}
                        isExpanded={expandedCardId === req.id}
                        onToggleExpand={() =>
                          setExpandedCardId(
                            expandedCardId === req.id ? null : req.id,
                          )
                        }
                        rejectingId={rejectingId}
                        rejectionReason={rejectionReason}
                        onApprove={handleApprove}
                        onRejectStart={() => setRejectingId(req.id)}
                        onRejectCancel={() => {
                          setRejectingId(null);
                          setRejectionReason("");
                        }}
                        onRejectSubmit={handleRejectConfirm}
                        onReasonChange={(reason) => setRejectionReason(reason)}
                      />
                    ))}
                  </div>
                )}
              </div>
            )}

            {/* Approved Requests Tab */}
            {activeTab === "approved" && (
              <div>
                {approvedRequests.length === 0 ? (
                  <div className="text-center py-12 bg-white rounded-lg">
                    <p className="text-gray-600">No approved admin requests</p>
                  </div>
                ) : (
                  <div className="space-y-4">
                    {approvedRequests.map((req) => (
                      <RequestCard
                        key={req.id}
                        req={req}
                        isPending={false}
                        isExpanded={expandedCardId === req.id}
                        onToggleExpand={() =>
                          setExpandedCardId(
                            expandedCardId === req.id ? null : req.id,
                          )
                        }
                      />
                    ))}
                  </div>
                )}
              </div>
            )}
          </>
        )}

        {/* Confirmation Modal */}
        {confirmDialog.isOpen && (
          <div className="fixed inset-0 bg-black/30 backdrop-blur-md flex items-center justify-center z-50">
            <div className="bg-white rounded-lg shadow-2xl p-8 max-w-md mx-4 transform transition-all">
              <h2 className="text-xl font-bold text-gray-900 mb-4">
                {confirmDialog.type === "approve"
                  ? "Confirm Approval"
                  : "Confirm Rejection"}
              </h2>
              <p className="text-gray-700 mb-8 text-base leading-relaxed">
                {confirmDialog.type === "approve"
                  ? `Do you want to approve ${confirmDialog.userName} as an Organization Administrator?`
                  : `Do you want to reject ${confirmDialog.userName}'s application?`}
              </p>
              <div className="flex gap-3">
                <button
                  onClick={() => {
                    if (confirmDialog.type === "approve") {
                      handleApproveConfirm();
                    } else {
                      handleRejectConfirmationAccept();
                    }
                  }}
                  className={`flex-1 px-6 py-3 text-white font-semibold rounded-lg transition transform hover:scale-105 ${
                    confirmDialog.type === "approve"
                      ? "bg-green-600 hover:bg-green-700"
                      : "bg-red-600 hover:bg-red-700"
                  }`}
                >
                  Yes, {confirmDialog.type === "approve" ? "Approve" : "Reject"}
                </button>
                <button
                  onClick={handleConfirmCancel}
                  className="flex-1 px-6 py-3 bg-gray-200 text-gray-800 font-semibold rounded-lg hover:bg-gray-300 transition transform hover:scale-105"
                >
                  Cancel
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

// Request Card Component
interface RequestCardProps {
  req: ApprovalRequest;
  isPending: boolean;
  isExpanded?: boolean;
  onToggleExpand?: () => void;
  rejectingId?: number | null;
  rejectionReason?: string;
  onApprove?: (id: number) => void;
  onRejectStart?: () => void;
  onRejectCancel?: () => void;
  onRejectSubmit?: () => void;
  onReasonChange?: (reason: string) => void;
  showReason?: boolean;
}

function RequestCard({
  req,
  isPending,
  isExpanded = true,
  onToggleExpand,
  rejectingId,
  rejectionReason,
  onApprove,
  onRejectStart,
  onRejectCancel,
  onRejectSubmit,
  onReasonChange,
  showReason = false,
}: RequestCardProps) {
  return (
    <div className="bg-white rounded-lg shadow p-6">
      <div className="flex items-start justify-between mb-4">
        <div className="flex-1">
          <h3 className="text-lg font-semibold text-gray-900">
            {req.first_name} {req.last_name}
          </h3>
          <p className="text-gray-600">{req.email}</p>
          <p className="text-sm text-gray-500 mt-1">@{req.username}</p>
        </div>
        <div className="flex items-center gap-3">
          <span
            className={`px-3 py-1 rounded-full text-sm font-semibold ${
              req.approval_status === "PENDING"
                ? "bg-yellow-100 text-yellow-800"
                : req.approval_status === "APPROVED"
                  ? "bg-green-100 text-green-800"
                  : "bg-red-100 text-red-800"
            }`}
          >
            {req.approval_status}
          </span>
          <button
            onClick={onToggleExpand}
            className="text-gray-500 hover:text-gray-700 transition"
            title={isExpanded ? "Minimize" : "Expand"}
          >
            {isExpanded ? <ChevronUp size={24} /> : <ChevronDown size={24} />}
          </button>
        </div>
      </div>

      {isExpanded && (
        <>
          <div className="grid grid-cols-2 gap-4 mb-6 pb-6 border-b border-gray-200">
            <div>
              <label className="text-sm font-medium text-gray-600">
                Organization Name
              </label>
              <p className="text-gray-900">{req.organization_name}</p>
            </div>
            <div>
              <label className="text-sm font-medium text-gray-600">
                Organization Type
              </label>
              <p className="text-gray-900">{req.organization_type}</p>
            </div>
            <div>
              <label className="text-sm font-medium text-gray-600">Phone</label>
              <p className="text-gray-900">{req.phone_number || "N/A"}</p>
            </div>
            {req.approval_requested_at && (
              <div>
                <label className="text-sm font-medium text-gray-600">
                  Requested On
                </label>
                <p className="text-gray-900">
                  {new Date(req.approval_requested_at).toLocaleDateString(
                    "en-US",
                    {
                      year: "numeric",
                      month: "short",
                      day: "numeric",
                      hour: "2-digit",
                      minute: "2-digit",
                    },
                  )}
                </p>
              </div>
            )}
            {req.approval_decided_at && (
              <div>
                <label className="text-sm font-medium text-gray-600">
                  Decided On
                </label>
                <p className="text-gray-900">
                  {new Date(req.approval_decided_at).toLocaleDateString(
                    "en-US",
                    {
                      year: "numeric",
                      month: "short",
                      day: "numeric",
                      hour: "2-digit",
                      minute: "2-digit",
                    },
                  )}
                </p>
              </div>
            )}
            {req.approval_decided_by_username && (
              <div>
                <label className="text-sm font-medium text-gray-600">
                  Decided By
                </label>
                <p className="text-gray-900">System Admin</p>
              </div>
            )}
          </div>

          {isPending && rejectingId !== req.id ? (
            <div className="flex gap-3">
              <button
                onClick={() => onApprove && onApprove(req.id)}
                className="flex-1 flex items-center justify-center gap-2 px-4 py-2 bg-green-600 text-white rounded hover:bg-green-700 transition"
              >
                <Check size={18} />
                Approve
              </button>
              <button
                onClick={() => onRejectStart && onRejectStart()}
                className="flex-1 flex items-center justify-center gap-2 px-4 py-2 bg-red-600 text-white rounded hover:bg-red-700 transition"
              >
                <X size={18} />
                Reject
              </button>
            </div>
          ) : isPending && rejectingId === req.id ? (
            <div className="space-y-3">
              <textarea
                value={rejectionReason}
                onChange={(e) =>
                  onReasonChange && onReasonChange(e.target.value)
                }
                placeholder="Reason for rejection..."
                rows={3}
                className="w-full px-3 py-2 border border-gray-300 rounded focus:ring-2 focus:ring-red-500"
              />
              <div className="flex gap-3">
                <button
                  onClick={() => onRejectSubmit && onRejectSubmit()}
                  className="flex-1 px-4 py-2 bg-red-600 text-white rounded hover:bg-red-700 transition"
                >
                  Confirm Rejection
                </button>
                <button
                  onClick={() => onRejectCancel && onRejectCancel()}
                  className="flex-1 px-4 py-2 bg-gray-300 text-gray-700 rounded hover:bg-gray-400 transition"
                >
                  Cancel
                </button>
              </div>
            </div>
          ) : null}

          {showReason &&
            req.approval_status === "REJECTED" &&
            req.rejection_reason && (
              <div className="bg-red-50 border border-red-200 p-3 rounded">
                <p className="text-sm text-red-800">
                  <strong>Rejection Reason:</strong> {req.rejection_reason}
                </p>
              </div>
            )}
        </>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useAuth } from "@/lib/AuthContext";
import {
  Donation,
  getDonations,
  getOrganizations,
  confirmDonation,
  cancelDonation,
} from "@/lib/api";
import LoadingSpinner from "@/components/LoadingSpinner";
import { CheckCircle2, XCircle, Clock, Gift } from "lucide-react";
import { useRouter } from "next/navigation";

export default function DonationsPage() {
  const router = useRouter();
  const { user, loading: authLoading } = useAuth();
  const [donations, setDonations] = useState<Donation[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");
  const [filter, setFilter] = useState<string>("PENDING");
  const [confirming, setConfirming] = useState<number | null>(null);
  const [cancelling, setCancelling] = useState<number | null>(null);
  const [needsMap, setNeedsMap] = useState<Map<number, any>>(new Map());
  const [organization, setOrganization] = useState<any>(null);
  const [confirmDialog, setConfirmDialog] = useState<{
    isOpen: boolean;
    type: "confirm" | "cancel" | null;
    donationId: number | null;
    donationDetails: any | null;
  }>({
    isOpen: false,
    type: null,
    donationId: null,
    donationDetails: null,
  });
  const [viewDialog, setViewDialog] = useState<any>(null);

  useEffect(() => {
    if (!authLoading) {
      if (user?.role !== "ORG_ADMIN") {
        router.push("/");
      }
    }
  }, [user, authLoading, router]);

  const fetchDonations = async () => {
    if (!user || user.role !== "ORG_ADMIN") return;

    try {
      setError("");
      const data = await getDonations();
      // Sort donations by most recent completely
      const sortedData = [...data].sort(
        (a, b) =>
          new Date(b.created_at).getTime() - new Date(a.created_at).getTime(),
      );
      setDonations(sortedData);
    } catch (err: unknown) {
      setError(
        err instanceof Error ? err.message : "Failed to fetch donations",
      );
      console.error("Error fetching donations:", err);
    }
  };

  useEffect(() => {
    const fetchData = async () => {
      if (!user) return;
      if (user.role !== "ORG_ADMIN") return;

      try {
        setIsLoading(true);
        setError("");

        // Get all donations
        const allDonations = await getDonations();

        // ORG_ADMIN logic
        const orgs = await getOrganizations();
        if (orgs.length > 0) {
          setOrganization(orgs[0]);

          const nMap = new Map<number, any>();
          orgs[0].sections?.forEach((section: any) => {
            section.needs?.forEach((need: any) => {
              nMap.set(need.id, need);
            });
          });
          setNeedsMap(nMap);

          const orgNeedIds = new Set<number>();
          orgs[0].sections?.forEach((section: any) => {
            section.needs?.forEach((need: any) => {
              orgNeedIds.add(need.id);
            });
          });

          const filteredDonations = allDonations.filter((d) =>
            orgNeedIds.has(d.need_item),
          );
          setDonations(filteredDonations);
        }
      } catch (err: any) {
        setError(err.message || "Failed to fetch donations");
        console.error("Error fetching data:", err);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, [user]);

  const handleConfirm = async (donationId: number) => {
    const donation = donations.find((d) => d.id === donationId);
    setConfirmDialog({
      isOpen: true,
      type: "confirm",
      donationId,
      donationDetails: donation,
    });
  };

  const handleConfirmApprove = async () => {
    if (!confirmDialog.donationId) return;

    setConfirming(confirmDialog.donationId);
    try {
      await confirmDonation(confirmDialog.donationId);
      setConfirmDialog({
        isOpen: false,
        type: null,
        donationId: null,
        donationDetails: null,
      });
      await fetchDonations();
    } catch (err: any) {
      setError(
        err.detail || err.message || err.status || "Failed to confirm donation",
      );
    } finally {
      setConfirming(null);
    }
  };

  const handleCancel = async (donationId: number) => {
    const donation = donations.find((d) => d.id === donationId);
    setConfirmDialog({
      isOpen: true,
      type: "cancel",
      donationId,
      donationDetails: donation,
    });
  };

  const handleCancelApprove = async () => {
    if (!confirmDialog.donationId) return;

    setCancelling(confirmDialog.donationId);
    try {
      await cancelDonation(confirmDialog.donationId);
      setConfirmDialog({
        isOpen: false,
        type: null,
        donationId: null,
        donationDetails: null,
      });
      await fetchDonations();
    } catch (err: any) {
      setError(
        err.detail || err.message || err.status || "Failed to cancel donation",
      );
    } finally {
      setCancelling(null);
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case "CONFIRMED":
        return <CheckCircle2 className="text-green-600" size={20} />;
      case "CANCELLED":
        return <XCircle className="text-red-600" size={20} />;
      case "FULFILLED":
        return <Gift className="text-purple-600" size={20} />;
      default:
        return <Clock className="text-yellow-600" size={20} />;
    }
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "CONFIRMED":
        return "bg-green-100 text-green-800";
      case "CANCELLED":
        return "bg-red-100 text-red-800";
      case "FULFILLED":
        return "bg-purple-100 text-purple-800";
      default:
        return "bg-yellow-100 text-yellow-800";
    }
  };

  // Group fulfilled donations by need item
  const groupDonationsByNeedItem = (
    donations: Donation[],
  ): Record<number, Donation[]> => {
    return donations.reduce(
      (groups, donation) => {
        const needId = donation.need_item;
        if (!groups[needId]) {
          groups[needId] = [];
        }
        groups[needId].push(donation);
        return groups;
      },
      {} as Record<number, Donation[]>,
    );
  };

  const filteredDonations = (() => {
    let result = [];
    if (filter === "ALL") result = donations;
    else if (filter === "CONFIRMED")
      result = donations.filter(
        (d) => d.status === "CONFIRMED" || d.status === "FULFILLED",
      );
    else result = donations.filter((d) => d.status === filter);

    // Ensure the array is always sorted newest-first
    return result.sort(
      (a, b) =>
        new Date(b.created_at).getTime() - new Date(a.created_at).getTime(),
    );
  })();

  // For FULFILLED filter, group by need item
  const groupedFulfilledDonations =
    filter === "FULFILLED"
      ? groupDonationsByNeedItem(
          donations.filter((d) => d.status === "FULFILLED"),
        )
      : {};

  if (authLoading || isLoading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <LoadingSpinner />
      </div>
    );
  }

  if (user?.role !== "ORG_ADMIN") {
    return (
      <div className="min-h-screen bg-gray-50 py-12 px-4">
        <div className="max-w-4xl mx-auto">
          <div className="bg-white rounded-lg shadow p-6 text-center">
            <p className="text-gray-600">
              You do not have permission to access this page.
            </p>
          </div>
        </div>
      </div>
    );
  }

  const ViewDialog = () => {
    if (!viewDialog) return null;

    const donation = viewDialog;
    const needName = needsMap.get(donation.need_item)?.name || "Unknown Need";

    return (
      <div className="fixed inset-0 bg-black/40 flex items-center justify-center z-50 px-4">
        <div className="bg-white rounded-lg shadow-xl max-w-lg w-full p-6 animate-in">
          <div className="flex justify-between items-center mb-6 border-b pb-4">
            <h3 className="text-xl font-bold text-gray-900">
              Donation Details
            </h3>
            <button
              onClick={() => setViewDialog(null)}
              className="text-gray-400 hover:text-gray-600"
              aria-label="Close donation details"
              title="Close"
            >
              <XCircle size={24} />
            </button>
          </div>

          <div className="space-y-4 text-sm">
            <div className="grid grid-cols-3 border-b border-gray-100 pb-2">
              <span className="text-gray-500 font-medium">Need Item</span>
              <span className="col-span-2 text-gray-900">{needName}</span>
            </div>

            <div className="grid grid-cols-3 border-b border-gray-100 pb-2">
              <span className="text-gray-500 font-medium">Quantity</span>
              <span className="col-span-2 text-gray-900">
                {donation.quantity} {donation.units || "UNIT"}
              </span>
            </div>

            <div className="grid grid-cols-3 border-b border-gray-100 pb-2">
              <span className="text-gray-500 font-medium">Donor Type</span>
              <span className="col-span-2 text-gray-900 capitalize">
                {donation.donor_type === "private"
                  ? "Private Donor"
                  : "Government"}
              </span>
            </div>

            {donation.donor_type === "private" ? (
              <>
                <div className="grid grid-cols-3 border-b border-gray-100 pb-2">
                  <span className="text-gray-500 font-medium">Donor Name</span>
                  <span className="col-span-2 text-gray-900">
                    {donation.donor_name || "N/A"}
                  </span>
                </div>

                <div className="grid grid-cols-3 border-b border-gray-100 pb-2">
                  <span className="text-gray-500 font-medium">
                    Contact Person
                  </span>
                  <span className="col-span-2 text-gray-900">
                    {donation.donor_contact || "N/A"}
                  </span>
                </div>

                <div className="grid grid-cols-3 border-b border-gray-100 pb-2">
                  <span className="text-gray-500 font-medium">
                    Contact Number
                  </span>
                  <span className="col-span-2 text-gray-900">
                    {donation.donor_phone || "N/A"}
                  </span>
                </div>

                <div className="grid grid-cols-3 border-b border-gray-100 pb-2">
                  <span className="text-gray-500 font-medium">Email</span>
                  <span className="col-span-2 text-gray-900">
                    {donation.donor_email || "N/A"}
                  </span>
                </div>

                <div className="grid grid-cols-3 border-b border-gray-100 pb-2">
                  <span className="text-gray-500 font-medium">
                    Organization
                  </span>
                  <span className="col-span-2 text-gray-900">
                    {donation.donor_organization || "N/A"}
                  </span>
                </div>

                <div className="grid grid-cols-3 border-b border-gray-100 pb-2">
                  <span className="text-gray-500 font-medium">Address</span>
                  <span className="col-span-2 text-gray-900 truncate">
                    {donation.donor_address || "N/A"}
                  </span>
                </div>
              </>
            ) : (
              <>
                <div className="grid grid-cols-3 border-b border-gray-100 pb-2">
                  <span className="text-gray-500 font-medium">Department</span>
                  <span className="col-span-2 text-gray-900">
                    {donation.government_department || "N/A"}
                  </span>
                </div>

                <div className="grid grid-cols-3 border-b border-gray-100 pb-2">
                  <span className="text-gray-500 font-medium">Program</span>
                  <span className="col-span-2 text-gray-900">
                    {donation.government_program || "N/A"}
                  </span>
                </div>

                <div className="grid grid-cols-3 border-b border-gray-100 pb-2">
                  <span className="text-gray-500 font-medium">
                    Officer Name
                  </span>
                  <span className="col-span-2 text-gray-900">
                    {donation.government_officer_name || "N/A"}
                  </span>
                </div>

                <div className="grid grid-cols-3 border-b border-gray-100 pb-2">
                  <span className="text-gray-500 font-medium">Designation</span>
                  <span className="col-span-2 text-gray-900">
                    {donation.government_officer_designation || "N/A"}
                  </span>
                </div>

                <div className="grid grid-cols-3 border-b border-gray-100 pb-2">
                  <span className="text-gray-500 font-medium">
                    Contact Number
                  </span>
                  <span className="col-span-2 text-gray-900">
                    {donation.government_officer_contact || "N/A"}
                  </span>
                </div>
              </>
            )}

            <div className="grid grid-cols-3 border-b border-gray-100 pb-2">
              <span className="text-gray-500 font-medium">Message</span>
              <span className="col-span-2 text-gray-900">
                {donation.message || "N/A"}
              </span>
            </div>

            <div className="grid grid-cols-3 border-b border-gray-100 pb-2">
              <span className="text-gray-500 font-medium">
                Estimated Delivery
              </span>
              <span className="col-span-2 text-gray-900">
                {donation.estimated_delivery_date
                  ? new Date(
                      donation.estimated_delivery_date,
                    ).toLocaleDateString()
                  : "N/A"}
              </span>
            </div>
          </div>

          <div className="mt-8 flex justify-end">
            <button
              onClick={() => setViewDialog(null)}
              className="px-6 py-2 bg-gray-200 text-gray-800 rounded-lg hover:bg-gray-300 font-medium transition"
            >
              Close
            </button>
          </div>
        </div>
      </div>
    );
  };

  // Confirmation Dialog Modal
  const ConfirmationDialog = () => {
    if (!confirmDialog.isOpen || !confirmDialog.donationDetails) return null;

    const donation = confirmDialog.donationDetails;
    const isConfirm = confirmDialog.type === "confirm";

    return (
      <div className="fixed inset-0 bg-black/40 flex items-center justify-center z-50 px-4">
        <div className="bg-white rounded-lg shadow-xl max-w-md w-full p-6 animate-in">
          <div className="flex items-center justify-center mb-4">
            <div
              className={`w-12 h-12 rounded-full flex items-center justify-center ${
                isConfirm ? "bg-green-100" : "bg-red-100"
              }`}
            >
              {isConfirm ? (
                <CheckCircle2 className="text-green-600" size={24} />
              ) : (
                <XCircle className="text-red-600" size={24} />
              )}
            </div>
          </div>

          <h3 className="text-xl font-bold text-center text-gray-900 mb-2">
            {isConfirm ? "Confirm Donation?" : "Cancel Donation?"}
          </h3>

          <p className="text-gray-600 text-center mb-4 text-sm">
            {isConfirm
              ? "Are you sure you want to confirm this donation?"
              : "Are you sure you want to cancel this donation?"}
          </p>

          <div className="bg-gray-50 rounded-lg p-4 mb-6 space-y-2">
            <div className="flex justify-between text-sm">
              <span className="text-gray-600">Need Item:</span>
              <span className="text-gray-900 font-medium">
                {donation.need_item_detail?.name ||
                  `Need ${donation.need_item}`}
              </span>
            </div>
            <div className="flex justify-between text-sm">
              <span className="text-gray-600">Quantity:</span>
              <span className="text-gray-900 font-medium">
                {donation.quantity} {donation.need_item_detail?.unit || "units"}
              </span>
            </div>
            <div className="flex justify-between text-sm">
              <span className="text-gray-600">Donor:</span>
              <span className="text-gray-900 font-medium">
                {donation.donor_type === "private"
                  ? donation.donor_name
                  : donation.government_department}
              </span>
            </div>
          </div>

          <div className="flex gap-3">
            <button
              onClick={() =>
                setConfirmDialog({
                  isOpen: false,
                  type: null,
                  donationId: null,
                  donationDetails: null,
                })
              }
              className="flex-1 px-4 py-2 bg-gray-200 text-gray-800 rounded-lg hover:bg-gray-300 font-medium transition"
              disabled={confirming !== null || cancelling !== null}
            >
              Back
            </button>
            <button
              onClick={isConfirm ? handleConfirmApprove : handleCancelApprove}
              className={`flex-1 px-4 py-2 text-white rounded-lg font-medium transition ${
                isConfirm
                  ? "bg-green-600 hover:bg-green-700 disabled:bg-green-400"
                  : "bg-red-600 hover:bg-red-700 disabled:bg-red-400"
              }`}
              disabled={confirming !== null || cancelling !== null}
            >
              {confirming !== null || cancelling !== null
                ? isConfirm
                  ? "Confirming..."
                  : "Cancelling..."
                : isConfirm
                  ? "Confirm"
                  : "Cancel"}
            </button>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-gray-50 py-12 px-4">
      <div className="max-w-6xl mx-auto">
        <div className="mb-8">
          <h1 className="text-4xl font-bold text-gray-900">
            Donation Management
          </h1>
          <p className="text-gray-600 mt-2">
            Review and confirm donations from donors
          </p>
        </div>

        {error && (
          <div className="mb-6 bg-red-50 border border-red-200 text-red-800 px-4 py-3 rounded-lg flex items-center justify-between">
            {error}
            <button
              onClick={() => setError("")}
              className="text-red-600 hover:text-red-800"
            >
              ✕
            </button>
          </div>
        )}

        <div className="mb-6 flex gap-2 border-b border-gray-200">
          {["PENDING", "CONFIRMED", "FULFILLED", "CANCELLED", "ALL"].map(
            (status) => {
              let count = 0;
              if (status === "ALL") {
                count = donations.length;
              } else if (status === "CONFIRMED") {
                count = donations.filter(
                  (d) => d.status === "CONFIRMED" || d.status === "FULFILLED",
                ).length;
              } else if (status === "FULFILLED") {
                // Count unique need items for FULFILLED tab
                const fulfilledDonations = donations.filter(
                  (d) => d.status === "FULFILLED",
                );
                const uniqueNeeds = new Set(
                  fulfilledDonations.map((d) => d.need_item),
                );
                count = uniqueNeeds.size;
              } else {
                count = donations.filter((d) => d.status === status).length;
              }

              return (
                <button
                  key={status}
                  onClick={() => setFilter(status)}
                  className={`px-4 py-3 font-medium border-b-2 transition ${
                    filter === status
                      ? "text-blue-600 border-blue-600"
                      : "text-gray-600 border-transparent hover:text-gray-900"
                  }`}
                >
                  {status}
                  {status !== "ALL" && (
                    <span className="ml-2 text-sm">({count})</span>
                  )}
                </button>
              );
            },
          )}
        </div>

        <div className="bg-white rounded-lg shadow overflow-hidden">
          {filteredDonations.length === 0 ? (
            <div className="p-8 text-center text-gray-500">
              No donations found for this filter
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="bg-gray-50 border-b border-gray-200">
                  <tr>
                    <th className="px-6 py-3 text-left text-sm font-semibold text-gray-900">
                      Status
                    </th>
                    <th className="px-6 py-3 text-left text-sm font-semibold text-gray-900">
                      Need Item
                    </th>
                    <th className="px-6 py-3 text-left text-sm font-semibold text-gray-900">
                      Quantity
                    </th>
                    <th className="px-6 py-3 text-left text-sm font-semibold text-gray-900">
                      Donor Type
                    </th>
                    <th className="px-6 py-3 text-left text-sm font-semibold text-gray-900">
                      Donor Info
                    </th>
                    <th className="px-6 py-3 text-left text-sm font-semibold text-gray-900">
                      Requested Date
                    </th>
                    <th className="px-6 py-3 text-left text-sm font-semibold text-gray-900">
                      Actions
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-200">
                  {filter === "FULFILLED"
                    ? // For FULFILLED donations, group by need item and show all donors
                      Object.entries(groupedFulfilledDonations)
                        .sort(
                          ([, a], [, b]) =>
                            new Date(b[0].created_at).getTime() -
                            new Date(a[0].created_at).getTime(),
                        )
                        .map(([needId, needDonations]) => {
                          const firstDonation = needDonations[0];
                          const totalQuantity = needDonations.reduce(
                            (sum, d) => sum + d.quantity,
                            0,
                          );
                          return (
                            <tr
                              key={needId}
                              className="hover:bg-gray-50 transition"
                            >
                              <td className="px-6 py-4">
                                <div className="flex items-center gap-2">
                                  {getStatusIcon("FULFILLED")}
                                  <span
                                    className={`px-3 py-1 rounded-full text-sm font-medium ${getStatusBadge("FULFILLED")}`}
                                  >
                                    FULFILLED
                                  </span>
                                </div>
                              </td>
                              <td className="px-6 py-4 text-sm">
                                <div className="font-medium text-gray-900">
                                  {firstDonation.need_item_detail?.name ||
                                    `Need ${firstDonation.need_item}`}
                                </div>
                              </td>
                              <td className="px-6 py-4 text-sm text-gray-600">
                                <div className="space-y-2">
                                  {needDonations.map((donation, idx) => (
                                    <div
                                      key={idx}
                                      className="flex items-center py-1"
                                    >
                                      {donation.quantity}{" "}
                                      {donation.need_item_detail?.unit ||
                                        "units"}
                                    </div>
                                  ))}
                                </div>
                              </td>
                              <td className="px-6 py-4 text-sm">
                                <div className="space-y-2">
                                  {needDonations.map((donation, idx) => (
                                    <div
                                      key={idx}
                                      className="flex items-center py-1"
                                    >
                                      <span
                                        className={`px-2 py-0.5 rounded-full text-[10px] font-medium ${donation.donor_type === "private" ? "bg-blue-100 text-blue-800" : "bg-green-100 text-green-800"}`}
                                      >
                                        {donation.donor_type === "private"
                                          ? "Private"
                                          : "Government"}
                                      </span>
                                    </div>
                                  ))}
                                </div>
                              </td>
                              <td className="px-6 py-4 text-sm">
                                <div className="space-y-2">
                                  {needDonations.map((donation, idx) => (
                                    <div key={idx} className="py-1">
                                      <div className="text-gray-900 font-medium text-xs">
                                        {donation.donor_type === "private"
                                          ? donation.donor_name
                                          : donation.government_department}
                                      </div>
                                      {donation.donor_type === "private" && (
                                        <div className="text-gray-500 text-[10px]">
                                          {donation.donor_email}
                                        </div>
                                      )}
                                    </div>
                                  ))}
                                </div>
                              </td>
                              <td className="px-6 py-4 text-sm text-gray-600">
                                <div className="space-y-2">
                                  {needDonations.map((donation, idx) => (
                                    <div
                                      key={idx}
                                      className="py-1 flex items-center whitespace-nowrap text-xs"
                                    >
                                      {new Date(
                                        donation.created_at,
                                      ).toLocaleDateString()}
                                    </div>
                                  ))}
                                </div>
                              </td>
                              <td className="px-6 py-4 text-sm">
                                <span className="text-gray-500 text-xs">
                                  No actions
                                </span>
                              </td>
                            </tr>
                          );
                        })
                    : // For other statuses, show one row per donation
                      filteredDonations.map((donation) => {
                        const displayStatus =
                          filter === "CONFIRMED"
                            ? "CONFIRMED"
                            : donation.status;
                        return (
                          <tr
                            key={donation.id}
                            className="hover:bg-gray-50 transition"
                          >
                            <td className="px-6 py-4">
                              <div className="flex items-center gap-2">
                                {getStatusIcon(displayStatus)}
                                <span
                                  className={`px-3 py-1 rounded-full text-sm font-medium ${getStatusBadge(displayStatus)}`}
                                >
                                  {displayStatus}
                                </span>
                              </div>
                            </td>
                            <td className="px-6 py-4 text-sm">
                              <div className="font-medium text-gray-900">
                                {donation.need_item_detail?.name ||
                                  `Need ${donation.need_item}`}
                              </div>
                            </td>
                            <td className="px-6 py-4 text-sm text-gray-600">
                              {donation.quantity}{" "}
                              {donation.need_item_detail?.unit || "units"}
                            </td>
                            <td className="px-6 py-4 text-sm">
                              <span
                                className={`px-3 py-1 rounded-full text-xs font-medium ${donation.donor_type === "private" ? "bg-blue-100 text-blue-800" : "bg-green-100 text-green-800"}`}
                              >
                                {donation.donor_type}
                              </span>
                            </td>
                            <td className="px-6 py-4 text-sm">
                              <div className="text-gray-900 font-medium">
                                {donation.donor_type === "private"
                                  ? donation.donor_name
                                  : donation.government_department}
                              </div>
                              {donation.donor_type === "private" && (
                                <div className="text-gray-600 text-xs">
                                  {donation.donor_email}
                                </div>
                              )}
                            </td>
                            <td className="px-6 py-4 text-sm text-gray-600">
                              {new Date(
                                donation.created_at,
                              ).toLocaleDateString()}
                            </td>
                            <td className="px-6 py-4 text-sm">
                              <div className="flex gap-2">
                                {" "}
                                <button
                                  onClick={() => setViewDialog(donation)}
                                  className="px-3 py-1 bg-blue-600 text-white rounded hover:bg-blue-700 text-xs font-medium transition"
                                >
                                  View
                                </button>{" "}
                                {donation.status === "PENDING" && (
                                  <>
                                    <button
                                      onClick={() => handleConfirm(donation.id)}
                                      disabled={confirming === donation.id}
                                      className="px-3 py-1 bg-green-600 text-white rounded hover:bg-green-700 disabled:opacity-50 text-xs font-medium transition"
                                    >
                                      {confirming === donation.id
                                        ? "Confirming..."
                                        : "Confirm"}
                                    </button>
                                    <button
                                      onClick={() => handleCancel(donation.id)}
                                      disabled={cancelling === donation.id}
                                      className="px-3 py-1 bg-red-600 text-white rounded hover:bg-red-700 disabled:opacity-50 text-xs font-medium transition"
                                    >
                                      {cancelling === donation.id
                                        ? "Cancelling..."
                                        : "Cancel"}
                                    </button>
                                  </>
                                )}
                              </div>
                            </td>
                          </tr>
                        );
                      })}
                </tbody>
              </table>
            </div>
          )}
        </div>

        <div className="grid grid-cols-4 gap-6 mt-8">
          {["PENDING", "CONFIRMED", "FULFILLED", "CANCELLED"].map((status) => {
            let count = 0;
            let totalQuantity = 0;

            if (status === "CONFIRMED") {
              const confirmedAndFulfilled = donations.filter(
                (d) => d.status === "CONFIRMED" || d.status === "FULFILLED",
              );
              count = confirmedAndFulfilled.length;
              totalQuantity = confirmedAndFulfilled.reduce(
                (sum, d) => sum + d.quantity,
                0,
              );
            } else if (status === "FULFILLED") {
              const fulfilledDonations = donations.filter(
                (d) => d.status === "FULFILLED",
              );
              const uniqueNeeds = new Set(
                fulfilledDonations.map((d) => d.need_item),
              );
              count = uniqueNeeds.size;
              totalQuantity = fulfilledDonations.reduce(
                (sum, d) => sum + d.quantity,
                0,
              );
            } else {
              const standardDonations = donations.filter(
                (d) => d.status === status,
              );
              count = standardDonations.length;
              totalQuantity = standardDonations.reduce(
                (sum, d) => sum + d.quantity,
                0,
              );
            }

            return (
              <div key={status} className="bg-white rounded-lg shadow p-6">
                <div className="text-gray-600 text-sm font-medium">
                  {status}
                </div>
                <div className="text-3xl font-bold text-gray-900 mt-2">
                  {count}
                </div>
                <div className="text-gray-600 text-sm mt-2">
                  Total: {totalQuantity} units
                </div>
              </div>
            );
          })}
        </div>
      </div>

      <ConfirmationDialog />
      <ViewDialog />
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useAuth } from "@/lib/AuthContext";
import {
  Organization,
  getOrganizations,
  NeedItem,
  getNeeds,
  Donation,
  getDonations,
  Section,
  getSections,
} from "@/lib/api";
import LoadingSpinner from "@/components/LoadingSpinner";
import {
  Building2,
  Layers,
  ClipboardList,
  AlertTriangle,
  Search,
  DollarSign,
  Users,
  FileText,
  BarChart3,
  ChevronRight,
  ArrowRight,
} from "lucide-react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import Image from "next/image";

export default function AdminDashboard() {
  const router = useRouter();
  const { user, loading: authLoading } = useAuth();

  const [stats, setStats] = useState({
    organizations: 0,
    sections: 0,
    totalNeeds: 0,
    criticalNeeds: 0,
  });
  const [criticalNeeds, setCriticalNeeds] = useState<NeedItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    if (!authLoading) {
      if (user?.role === "ADMIN") {
        // Continue rendering admin page
      } else if (user?.role === "ORG_ADMIN") {
        // Redirect to org-admin
        router.push("/org-admin");
      } else {
        // Redirect non-admin users to home
        router.push("/");
      }
    }
  }, [user, authLoading, router]);

  useEffect(() => {
    const fetchDashboardData = async () => {
      if (!user || user.role !== "ADMIN") return;

      try {
        setIsLoading(true);
        setError("");

        const [orgs, sections, allNeeds] = await Promise.all([
          getOrganizations(),
          getSections(),
          getNeeds(),
        ]);

        const critical = allNeeds.filter((n) => n.priority === "CRITICAL");

        setStats({
          organizations: orgs.length,
          sections: sections.length,
          totalNeeds: allNeeds.length,
          criticalNeeds: critical.length,
        });

        setCriticalNeeds(critical.slice(0, 3)); // Show top 3 critical
      } catch (err: unknown) {
        setError(
          err instanceof Error ? err.message : "Failed to fetch dashboard data",
        );
        console.error("Dashboard error:", err);
      } finally {
        setIsLoading(false);
      }
    };

    fetchDashboardData();
  }, [user]);

  if (authLoading || isLoading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <LoadingSpinner />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50/50 pb-20">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-10">
        {/* Header Area */}
        <div className="mb-10 flex flex-col md:flex-row md:items-center justify-between gap-6">
          <div>
            <h1 className="text-3xl font-bold text-slate-900 tracking-tight">
              Admin Dashboard
            </h1>
            <p className="text-slate-500 mt-1">
              Operational overview and system management
            </p>
          </div>
          <div className="flex items-center gap-3">
            <div className="relative group">
              <Search
                className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-500 transition-colors"
                size={18}
              />
              <input
                type="text"
                placeholder="Search resources..."
                className="pl-10 pr-4 py-2.5 bg-white border border-slate-200 rounded-xl text-sm focus:outline-none focus:ring-4 focus:ring-blue-500/10 w-64 transition-all"
              />
            </div>
            <button
              className="p-2.5 bg-white border border-slate-200 rounded-xl hover:bg-slate-50 transition-colors text-slate-600"
              title="Manage Users"
              aria-label="Manage Users"
            >
              <Users size={20} />
            </button>
          </div>
        </div>

        {/* Quick Overview Stats */}
        <div className="mb-12">
          <h2 className="text-lg font-bold text-slate-900 mb-6 flex items-center gap-2">
            Quick Overview
          </h2>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            <StatCard
              label="Organizations"
              value={stats.organizations}
              subtext="Active organizations"
              icon={<Building2 className="text-blue-600" size={20} />}
              iconBg="bg-blue-50"
            />
            <StatCard
              label="Sections"
              value={stats.sections}
              subtext="Departments tracked"
              icon={<Layers className="text-purple-600" size={20} />}
              iconBg="bg-purple-50"
            />
            <StatCard
              label="Total Needs"
              value={stats.totalNeeds}
              subtext="Items registered"
              icon={<ClipboardList className="text-emerald-600" size={20} />}
              iconBg="bg-emerald-50"
            />
            <StatCard
              label="Critical Needs"
              value={stats.criticalNeeds}
              subtext="Urgent attention required"
              icon={<AlertTriangle className="text-rose-600" size={20} />}
              iconBg="bg-rose-50"
              isWarning={stats.criticalNeeds > 0}
            />
          </div>
        </div>

        <div className="grid lg:grid-cols-12 gap-8 mb-12">
          {/* Critical Needs Column */}
          <div className="lg:col-span-8 space-y-6">
            <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm">
              <div className="p-6 border-b border-slate-100 flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-rose-50 rounded-xl flex items-center justify-center">
                    <AlertTriangle className="text-rose-600" size={20} />
                  </div>
                  <div>
                    <h3 className="font-bold text-slate-900">
                      Critical Needs Requiring Attention
                    </h3>
                    <p className="text-xs text-slate-500 font-medium">
                      {stats.criticalNeeds} urgent items • Immediate assistance
                      needed
                    </p>
                  </div>
                </div>
                <Link
                  href="/needs"
                  className="text-xs font-bold text-blue-600 hover:text-blue-700 flex items-center gap-1 group"
                >
                  View All ({stats.totalNeeds}){" "}
                  <ArrowRight
                    size={14}
                    className="group-hover:translate-x-0.5 transition-transform"
                  />
                </Link>
              </div>
              <div className="p-6">
                {criticalNeeds.length === 0 ? (
                  <div className="py-10 text-center">
                    <p className="text-slate-400">No critical needs reported</p>
                  </div>
                ) : (
                  <div className="space-y-4">
                    {criticalNeeds.map((need) => (
                      <CriticalNeedRow key={need.id} need={need} />
                    ))}
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* Side Info Column - Matches the "Impact Overview" style from your previous version */}
          <div className="lg:col-span-4">
            <div className="bg-gradient-to-br from-slate-900 to-slate-800 rounded-2xl p-8 text-white relative overflow-hidden h-full shadow-xl">
              <div className="absolute top-0 right-0 w-32 h-32 bg-blue-500/10 blur-3xl rounded-full -mr-16 -mt-16"></div>
              <div className="relative z-10">
                <span className="inline-block px-3 py-1 bg-white/10 rounded-full text-[10px] font-bold tracking-widest uppercase mb-6">
                  System Status
                </span>
                <h3 className="text-2xl font-bold mb-4">
                  Network Activity Overview
                </h3>
                <p className="text-slate-300 text-sm leading-relaxed mb-8">
                  Monitoring platform transactions, donor engagement, and
                  hospital fulfillment rates across 9 provinces.
                </p>

                <div className="space-y-6">
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-white/10 rounded-xl flex items-center justify-center">
                      <Users className="text-blue-400" size={20} />
                    </div>
                    <div>
                      <p className="text-slate-400 text-xs font-medium uppercase tracking-wider">
                        Donors Active
                      </p>
                      <p className="text-xl font-bold">4,500+</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-white/10 rounded-xl flex items-center justify-center">
                      <ClipboardList className="text-emerald-400" size={20} />
                    </div>
                    <div>
                      <p className="text-slate-400 text-xs font-medium uppercase tracking-wider">
                        Successful Deliveries
                      </p>
                      <p className="text-xl font-bold">98%</p>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Admin Control Center Tiles */}
        <div className="bg-slate-950 rounded-3xl p-10 shadow-2xl relative overflow-hidden">
          <div className="absolute inset-0 bg-dots opacity-20 pointer-events-none"></div>
          <div className="relative z-10">
            <div className="mb-10">
              <span className="inline-block px-3 py-1 bg-white/10 rounded-full text-[10px] font-bold tracking-widest uppercase text-blue-300 mb-4">
                Admin Control Center
              </span>
              <h2 className="text-3xl font-bold text-white tracking-tight">
                Operational overview for administrators
              </h2>
              <p className="text-slate-400 mt-2 max-w-2xl">
                Monitor the platform, review urgent needs, and jump directly to
                the most important administrative workflows.
              </p>
            </div>

            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-4">
              <ControlTile
                label="Manage Organizations"
                desc="Create, update, and monitor organizations across the network."
                icon={<Building2 size={20} />}
                href="/organizations"
                color="indigo"
              />
              <ControlTile
                label="Review Critical Needs"
                desc="Focus on urgent items and ensure faster platform response."
                icon={<AlertTriangle size={20} />}
                href="/needs?priority=CRITICAL"
                color="rose"
              />
              <ControlTile
                label="Document Uploads"
                desc="Manage proof of delivery and supporting files."
                icon={<FileText size={20} />}
                href="/documents"
                color="emerald"
              />
              <ControlTile
                label="Impact Analytics"
                desc="Track donation outcomes and platform performance."
                icon={<BarChart3 size={20} />}
                href="/impact"
                color="amber"
              />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

function StatCard({
  label,
  value,
  subtext,
  icon,
  iconBg,
  isWarning,
}: {
  label: string;
  value: number;
  subtext: string;
  icon: any;
  iconBg: string;
  isWarning?: boolean;
}) {
  return (
    <div className="bg-white rounded-2xl p-6 border border-slate-200 shadow-sm hover:shadow-md transition-all group">
      <div className="flex items-center justify-between mb-4">
        <div
          className={`w-12 h-12 ${iconBg} rounded-xl flex items-center justify-center group-hover:scale-110 transition-transform`}
        >
          {icon}
        </div>
        {isWarning && (
          <span className="flex h-3 w-3 relative">
            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-rose-400 opacity-75"></span>
            <span className="relative inline-flex rounded-full h-3 w-3 bg-rose-500"></span>
          </span>
        )}
      </div>
      <div>
        <div className="text-gray-500 text-xs font-bold uppercase tracking-widest">
          {label}
        </div>
        <div className="text-3xl font-black text-slate-900 mt-1">{value}</div>
        <div className="text-slate-400 text-[11px] font-medium mt-2">
          {subtext}
        </div>
      </div>
    </div>
  );
}

function CriticalNeedRow({ need }: { need: NeedItem }) {
  const percent = Math.round(
    (need.quantity_received / need.quantity_required) * 100,
  );

  return (
    <div className="p-4 bg-slate-50/50 rounded-xl border border-slate-100 hover:border-slate-200 transition-colors">
      <div className="flex items-center justify-between mb-3">
        <div>
          <h4 className="font-bold text-slate-900 text-sm">{need.name}</h4>
          <p className="text-xs text-slate-500 font-medium">
            {need.section_detail?.organization_name}
          </p>
        </div>
        <span className="px-2 py-1 bg-rose-100 text-rose-700 rounded text-[10px] font-bold uppercase tracking-wider border border-rose-200">
          Critical
        </span>
      </div>

      <div className="space-y-2">
        <div className="flex justify-between items-center">
          <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
            Progress
          </span>
          <span className="text-[10px] font-bold text-slate-700">
            {percent}%
          </span>
        </div>
        <div className="h-2 bg-slate-200 rounded-full overflow-hidden">
          <style
            dangerouslySetInnerHTML={{
              __html: `.progress-${need.id} { width: ${percent}%; }`,
            }}
          />
          <div
            className={`h-full bg-rose-500 rounded-full transition-all duration-1000 progress-${need.id}`}
          />
        </div>
        <div className="flex justify-between items-center pt-1">
          <span className="text-xs font-medium text-slate-600">
            Received:{" "}
            <span className="text-emerald-600 font-bold">
              {need.quantity_received} Units
            </span>
          </span>
          <span className="text-xs font-medium text-slate-600">
            Needed:{" "}
            <span className="text-rose-600 font-bold">
              {need.quantity_required - need.quantity_received} Units
            </span>
          </span>
        </div>
      </div>
    </div>
  );
}

function ControlTile({
  label,
  desc,
  icon,
  href,
  color,
}: {
  label: string;
  desc: string;
  icon: any;
  href: string;
  color: string;
}) {
  const colorMap: any = {
    blue: "bg-blue-500/10 text-blue-400 border-blue-500/20 hover:bg-blue-500/20",
    indigo:
      "bg-indigo-500/10 text-indigo-400 border-indigo-500/20 hover:bg-indigo-500/20",
    rose: "bg-rose-500/10 text-rose-400 border-rose-500/20 hover:bg-rose-500/20",
    emerald:
      "bg-emerald-500/10 text-emerald-400 border-emerald-500/20 hover:bg-emerald-500/20",
    amber:
      "bg-amber-500/10 text-amber-400 border-amber-500/20 hover:bg-amber-500/20",
  };

  return (
    <Link
      href={href}
      className={`p-6 rounded-2xl border transition-all hover:-translate-y-1 ${colorMap[color]}`}
    >
      <div className="w-10 h-10 bg-white/5 rounded-xl flex items-center justify-center mb-4">
        {icon}
      </div>
      <h4 className="font-bold text-white text-sm mb-2">{label}</h4>
      <p className="text-[11px] text-slate-400 leading-relaxed font-medium">
        {desc}
      </p>
    </Link>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import { Donation, NeedItem, Organization, getDonations, getNeeds, getOrganizations } from "@/lib/api";
import { PageLoading } from "@/components/LoadingSpinner";

type MonthlyImpact = {
  label: string;
  value: number;
};

type DistrictImpact = {
  district: string;
  value: number;
};

type StoryCard = {
  title: string;
  body: string;
  progress: number;
};

export default function ImpactPage() {
  const [organizations, setOrganizations] = useState<Organization[]>([]);
  const [needs, setNeeds] = useState<NeedItem[]>([]);
  const [donations, setDonations] = useState<Donation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [warning, setWarning] = useState<string | null>(null);

  useEffect(() => {
    async function loadImpactData() {
      setLoading(true);
      setError(null);
      setWarning(null);

      // Check if user is authenticated for donation data
      const isAuthenticated = !!localStorage.getItem("accessToken");

      const promises: [Promise<any>, Promise<any>, Promise<any> | null] = [
        getOrganizations(),
        getNeeds(),
        isAuthenticated ? getDonations() : null
      ];

      const [orgResult, needsResult, donationResult] = await Promise.allSettled(promises);

      const organizationsLoaded = orgResult.status === "fulfilled";
      const needsLoaded = needsResult.status === "fulfilled";

      if (organizationsLoaded) {
        setOrganizations(orgResult.value);
      } else {
        setOrganizations([]);
      }

      if (needsLoaded) {
        setNeeds(needsResult.value);
      } else {
        setNeeds([]);
      }

      if (donationResult && donationResult.status === "fulfilled") {
        setDonations(donationResult.value || []);
      } else {
        setDonations([]);
        if (!isAuthenticated) {
          setWarning("Sign in to see your personalized donation history. Showing global impact data.");
        } else if (donationResult && donationResult.status === "rejected") {
          setWarning("Donation history could not be loaded for this account. Showing impact based on available data.");
        }
      }

      if (!organizationsLoaded && !needsLoaded) {
        const orgError = orgResult.status === "rejected" ? String(orgResult.reason) : "";
        const needError = needsResult.status === "rejected" ? String(needsResult.reason) : "";
        setError(orgError || needError || "Failed to load impact analytics");
      }

      setLoading(false);
    }

    loadImpactData();
  }, []);

  const metrics = useMemo(() => {
    const successfulDonations = donations.filter(
      (d) => d.status === "CONFIRMED" || d.status === "FULFILLED",
    );

    const uniqueDonors = new Set(
      successfulDonations
        .map((d) =>
          d.donor_type === "private"
            ? d.donor_name?.trim()
            : d.government_department?.trim(),
        )
        .filter(Boolean),
    );

    const totalRequired = needs.reduce((sum, n) => sum + n.quantity_required, 0);
    const totalReceived = needs.reduce((sum, n) => sum + n.quantity_received, 0);
    const fulfilledNeedsCount = needs.filter(
      (n) => n.quantity_required > 0 && n.quantity_received >= n.quantity_required,
    ).length;

    const needMap = new Map<number, NeedItem>();
    for (const need of needs) {
      needMap.set(need.id, need);
    }

    const districtByNeed = new Map<number, string>();
    for (const org of organizations) {
      for (const section of org.sections || []) {
        for (const need of section.needs || []) {
          districtByNeed.set(need.id, org.district || "Unknown");
        }
      }
    }

    const districtTotals = new Map<string, number>();
    for (const donation of successfulDonations) {
      const district = districtByNeed.get(donation.need_item) || "Unknown";
      districtTotals.set(district, (districtTotals.get(district) || 0) + donation.quantity);
    }

    const districtImpact: DistrictImpact[] = Array.from(districtTotals.entries())
      .map(([district, value]) => ({ district, value }))
      .sort((a, b) => b.value - a.value)
      .slice(0, 6);

    const monthTotals = new Map<string, number>();
    const monthLabels: string[] = [];
    const now = new Date();
    for (let i = 5; i >= 0; i -= 1) {
      const date = new Date(now.getFullYear(), now.getMonth() - i, 1);
      const key = `${date.getFullYear()}-${date.getMonth()}`;
      monthLabels.push(key);
      monthTotals.set(key, 0);
    }

    for (const donation of successfulDonations) {
      const date = new Date(donation.created_at);
      const key = `${date.getFullYear()}-${date.getMonth()}`;
      if (monthTotals.has(key)) {
        monthTotals.set(key, (monthTotals.get(key) || 0) + donation.quantity);
      }
    }

    const monthlyImpact: MonthlyImpact[] = monthLabels.map((key) => {
      const [year, month] = key.split("-").map(Number);
      const labelDate = new Date(year, month, 1);
      return {
        label: labelDate.toLocaleString("en", { month: "short" }),
        value: monthTotals.get(key) || 0,
      };
    });

    const topNeeds = needs
      .filter((n) => n.quantity_required > 0)
      .map((n) => ({
        name: n.name,
        progress: Math.min(100, Math.round((n.quantity_received / n.quantity_required) * 100)),
      }))
      .sort((a, b) => b.progress - a.progress)
      .slice(0, 3);

    const stories: StoryCard[] = topNeeds.map((item, index) => ({
      title: `Success Story ${index + 1}`,
      body: `${item.name} reached ${item.progress}% coverage through community and institutional donations.`,
      progress: item.progress,
    }));

    if (stories.length === 0) {
      stories.push({
        title: "Building Momentum",
        body: "The platform is collecting the first wave of support and preparing measurable success stories.",
        progress: 0,
      });
    }

    return {
      totalOrganizations: organizations.length,
      totalDonations: donations.length,
      totalSuccessfulDonations: successfulDonations.length,
      uniqueDonors: uniqueDonors.size,
      totalReceived,
      totalRequired,
      fulfilledNeedsCount,
      totalNeedsCount: needs.length,
      fulfillmentRate: needs.length > 0 ? Math.round((fulfilledNeedsCount / needs.length) * 100) : 0,
      coverageRate: totalRequired > 0 ? Math.round((totalReceived / totalRequired) * 100) : 0,
      monthlyImpact,
      districtImpact,
      stories,
      latestSuccessfulDonations: successfulDonations
        .slice()
        .sort(
          (a, b) =>
            new Date(b.created_at).getTime() - new Date(a.created_at).getTime(),
        )
        .slice(0, 5)
        .map((d) => ({
          id: d.id,
          donor:
            d.donor_type === "private"
              ? d.donor_name || "Private Donor"
              : d.government_department || "Government Department",
          quantity: d.quantity,
          needName: needMap.get(d.need_item)?.name || "Need Item",
          date: new Date(d.created_at).toLocaleDateString(),
        })),
    };
  }, [donations, needs, organizations]);

  if (loading) return <PageLoading />;

  if (error) {
    return (
      <div className="min-h-screen bg-slate-50 px-4 py-12">
        <div className="mx-auto max-w-3xl rounded-2xl border border-red-200 bg-red-50 p-8 text-center">
          <h1 className="mb-2 text-2xl font-bold text-red-800">Unable to Load Impact Page</h1>
          <p className="text-red-700">{error}</p>
          <button
            onClick={() => window.location.reload()}
            className="mt-6 rounded-lg bg-red-600 px-5 py-2 text-sm font-semibold text-white hover:bg-red-700"
          >
            Retry
          </button>
        </div>
      </div>
    );
  }

  const maxMonthlyValue = Math.max(...metrics.monthlyImpact.map((m) => m.value), 1);
  const maxDistrictValue = Math.max(...metrics.districtImpact.map((d) => d.value), 1);

  return (
    <div className="min-h-screen bg-linear-to-br from-cyan-50 via-white to-emerald-50">
      <div className="relative overflow-hidden border-b border-cyan-100 bg-linear-to-r from-cyan-700 via-sky-700 to-emerald-700">
        <div className="absolute -top-20 right-0 h-72 w-72 rounded-full bg-white/10 blur-3xl" />
        <div className="absolute -bottom-16 left-0 h-72 w-72 rounded-full bg-emerald-200/20 blur-3xl" />

        <div className="relative mx-auto max-w-7xl px-4 py-14 sm:px-6 lg:px-8">
          <p className="mb-3 inline-flex rounded-full border border-white/30 bg-white/20 px-4 py-1 text-sm font-semibold text-white backdrop-blur-sm">
            Impact Analytics
          </p>
          <h1 className="max-w-3xl text-4xl font-bold text-white sm:text-5xl">
            How This Platform Transforms Donations Into Real Outcomes
          </h1>
          <p className="mt-4 max-w-2xl text-base text-cyan-50 sm:text-lg">
            Track contribution momentum, district-level support, and delivery progress from donors to organizations.
          </p>
          <div className="mt-8 flex flex-wrap gap-3">
            <Link
              href="/needs"
              className="rounded-lg bg-white px-5 py-3 text-sm font-semibold text-cyan-700 shadow-lg transition hover:-translate-y-0.5 hover:shadow-xl"
            >
              Donate to Active Needs
            </Link>
            <Link
              href="/organizations"
              className="rounded-lg border border-white/40 bg-white/10 px-5 py-3 text-sm font-semibold text-white backdrop-blur-sm transition hover:bg-white/20"
            >
              Explore Organizations
            </Link>
          </div>
        </div>
      </div>

      <div className="mx-auto max-w-7xl px-4 py-10 sm:px-6 lg:px-8">
        {warning && (
          <div className="mb-6 rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-800">
            {warning}
          </div>
        )}

        <section className="grid grid-cols-1 gap-5 sm:grid-cols-2 xl:grid-cols-4">
          <article className="rounded-2xl border border-cyan-100 bg-white/90 p-6 shadow-sm">
            <p className="text-sm font-medium text-gray-500">Total Donations</p>
            <p className="mt-2 text-3xl font-bold text-gray-900">{metrics.totalDonations.toLocaleString()}</p>
            <p className="mt-2 text-sm text-emerald-700">{metrics.totalSuccessfulDonations.toLocaleString()} confirmed or fulfilled</p>
          </article>

          <article className="rounded-2xl border border-emerald-100 bg-white/90 p-6 shadow-sm">
            <p className="text-sm font-medium text-gray-500">Supplies Delivered</p>
            <p className="mt-2 text-3xl font-bold text-gray-900">{metrics.totalReceived.toLocaleString()}</p>
            <p className="mt-2 text-sm text-gray-600">of {metrics.totalRequired.toLocaleString()} requested units</p>
          </article>

          <article className="rounded-2xl border border-amber-100 bg-white/90 p-6 shadow-sm">
            <p className="text-sm font-medium text-gray-500">Needs Fulfillment Rate</p>
            <p className="mt-2 text-3xl font-bold text-gray-900">{metrics.fulfillmentRate}%</p>
            <p className="mt-2 text-sm text-gray-600">{metrics.fulfilledNeedsCount} of {metrics.totalNeedsCount} needs fully covered</p>
          </article>

          <article className="rounded-2xl border border-sky-100 bg-white/90 p-6 shadow-sm">
            <p className="text-sm font-medium text-gray-500">Active Donors</p>
            <p className="mt-2 text-3xl font-bold text-gray-900">{metrics.uniqueDonors.toLocaleString()}</p>
            <p className="mt-2 text-sm text-gray-600">supporting {metrics.totalOrganizations.toLocaleString()} organizations</p>
          </article>
        </section>

        <section className="mt-8 grid grid-cols-1 gap-6 lg:grid-cols-2">
          <article className="rounded-2xl border border-blue-100 bg-white/90 p-6 shadow-sm">
            <div className="mb-5 flex items-center justify-between">
              <h2 className="text-xl font-bold text-gray-900">Donation Trend (Last 6 Months)</h2>
              <span className="rounded-md bg-blue-50 px-2.5 py-1 text-xs font-semibold text-blue-700">
                Units
              </span>
            </div>
            <div className="grid grid-cols-6 items-end gap-3">
              {metrics.monthlyImpact.map((month) => {
                const height = Math.max(10, Math.round((month.value / maxMonthlyValue) * 160));
                return (
                  <div key={month.label} className="flex flex-col items-center">
                    <div className="mb-2 text-xs font-semibold text-gray-500">{month.value}</div>
                    <div
                      className="w-full rounded-t-md bg-linear-to-t from-blue-500 to-cyan-400"
                      style={{ height: `${height}px` }}
                    />
                    <div className="mt-2 text-xs font-medium text-gray-600">{month.label}</div>
                  </div>
                );
              })}
            </div>
          </article>

          <article className="rounded-2xl border border-emerald-100 bg-white/90 p-6 shadow-sm">
            <div className="mb-5 flex items-center justify-between">
              <h2 className="text-xl font-bold text-gray-900">Regional Distribution</h2>
              <span className="rounded-md bg-emerald-50 px-2.5 py-1 text-xs font-semibold text-emerald-700">
                Top Districts
              </span>
            </div>

            {metrics.districtImpact.length === 0 ? (
              <p className="rounded-lg border border-dashed border-gray-200 bg-gray-50 p-6 text-center text-sm text-gray-500">
                District-level impact will appear as confirmed donations increase.
              </p>
            ) : (
              <div className="space-y-4">
                {metrics.districtImpact.map((item) => {
                  const width = Math.max(5, Math.round((item.value / maxDistrictValue) * 100));
                  return (
                    <div key={item.district}>
                      <div className="mb-1 flex items-center justify-between text-sm">
                        <span className="font-semibold text-gray-700">{item.district}</span>
                        <span className="text-gray-500">{item.value.toLocaleString()} units</span>
                      </div>
                      <div className="h-2.5 overflow-hidden rounded-full bg-gray-100">
                        <div
                          className="h-full rounded-full bg-linear-to-r from-emerald-500 to-cyan-500"
                          style={{ width: `${width}%` }}
                        />
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </article>
        </section>

        <section className="mt-8 grid grid-cols-1 gap-6 xl:grid-cols-5">
          <article className="rounded-2xl border border-amber-100 bg-white/90 p-6 shadow-sm xl:col-span-3">
            <h2 className="text-xl font-bold text-gray-900">Impact Stories</h2>
            <p className="mt-1 text-sm text-gray-500">A snapshot of needs that received strong donor support.</p>
            <div className="mt-5 grid grid-cols-1 gap-4 md:grid-cols-3">
              {metrics.stories.map((story) => (
                <div key={story.title} className="rounded-xl border border-amber-100 bg-linear-to-b from-amber-50/70 to-white p-4">
                  <h3 className="font-semibold text-gray-900">{story.title}</h3>
                  <p className="mt-2 min-h-16 text-sm leading-relaxed text-gray-600">{story.body}</p>
                  <div className="mt-3 h-2 overflow-hidden rounded-full bg-amber-100">
                    <div
                      className="h-full rounded-full bg-linear-to-r from-amber-500 to-orange-500"
                      style={{ width: `${story.progress}%` }}
                    />
                  </div>
                  <p className="mt-2 text-xs font-semibold text-amber-700">{story.progress}% coverage</p>
                </div>
              ))}
            </div>
          </article>

          <article className="rounded-2xl border border-slate-200 bg-white/90 p-6 shadow-sm xl:col-span-2">
            <h2 className="text-xl font-bold text-gray-900">Recent Successful Donations</h2>
            <p className="mt-1 text-sm text-gray-500">Latest confirmed and fulfilled contributions.</p>

            <div className="mt-5 space-y-3">
              {metrics.latestSuccessfulDonations.length === 0 && (
                <p className="rounded-lg border border-dashed border-gray-200 bg-gray-50 p-5 text-sm text-gray-500">
                  No successful donations yet. Check back once organizations confirm deliveries.
                </p>
              )}

              {metrics.latestSuccessfulDonations.map((entry) => (
                <div key={entry.id} className="rounded-lg border border-gray-100 p-3">
                  <div className="flex items-center justify-between gap-3">
                    <p className="text-sm font-semibold text-gray-900">{entry.donor}</p>
                    <span className="rounded bg-emerald-100 px-2 py-0.5 text-xs font-semibold text-emerald-700">
                      {entry.quantity} units
                    </span>
                  </div>
                  <p className="mt-1 text-sm text-gray-600">{entry.needName}</p>
                  <p className="mt-1 text-xs text-gray-500">{entry.date}</p>
                </div>
              ))}
            </div>
          </article>
        </section>

        <section className="mt-8 rounded-2xl border border-cyan-100 bg-linear-to-r from-cyan-600 to-emerald-600 p-7 text-white shadow-lg">
          <div className="flex flex-col items-start justify-between gap-6 md:flex-row md:items-center">
            <div>
              <h2 className="text-2xl font-bold">Grow Platform Impact Even Faster</h2>
              <p className="mt-2 max-w-2xl text-cyan-50">
                Current needs coverage is at {metrics.coverageRate}%. More donors and faster confirmations will help close the remaining gap.
              </p>
            </div>
            <div className="flex flex-wrap gap-3">
              <Link href="/needs" className="rounded-lg bg-white px-5 py-2.5 text-sm font-semibold text-cyan-700 hover:bg-cyan-50">
                Support a Need
              </Link>
              <Link href="/login?tab=register" className="rounded-lg border border-white/40 bg-white/10 px-5 py-2.5 text-sm font-semibold text-white hover:bg-white/20">
                Join as Donor
              </Link>
            </div>
          </div>
        </section>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import { useSearchParams } from "next/navigation";
import { useAuth } from "@/lib/AuthContext";
import { registerOrgAdmin } from "@/lib/api";

export default function LoginContent() {
  const searchParams = useSearchParams();
  const [activeTab, setActiveTab] = useState<
    "login" | "register" | "org-admin"
  >("login");
  const [loading, setLoading] = useState(false);
  const { login, register } = useAuth();
  const [error, setError] = useState<string | null>(null);

  // Common form states
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");

  // Register specific states
  const [email, setEmail] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [phoneNumber, setPhoneNumber] = useState("");

  // Org Admin specific states
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [selectedOrgName, setSelectedOrgName] = useState("");
  const [selectedOrgType, setSelectedOrgType] = useState("");

  // Organization type options
  const ORG_TYPE_OPTIONS = [
    { value: "HOSPITAL", label: "Hospital" },
    { value: "CLINIC", label: "Clinic" },
    { value: "SCHOOL", label: "School" },
    { value: "NGO", label: "NGO" },
    { value: "CHARITY", label: "Charity" },
    { value: "GOVERNMENT", label: "Government" },
    { value: "OTHER", label: "Other" },
  ];

  // Password visibility toggles
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  useEffect(() => {
    const tab = (searchParams.get("tab") as any) || "login";
    setActiveTab(tab);
    setError(null);
  }, [searchParams]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setLoading(true);

    try {
      if (activeTab === "login") {
        await login(username, password);
      } else if (activeTab === "register") {
        if (password !== confirmPassword) {
          throw new Error("Passwords do not match");
        }
        await register({
          username,
          email,
          password,
          password2: confirmPassword,
          phone_number: phoneNumber,
        });
      } else if (activeTab === "org-admin") {
        if (password !== confirmPassword) {
          throw new Error("Passwords do not match");
        }
        if (!selectedOrgName.trim()) {
          throw new Error("Please select an organization");
        }
        if (!selectedOrgType.trim()) {
          throw new Error("Please select an organization type");
        }
        if (!firstName.trim() || !lastName.trim()) {
          throw new Error("Please enter your first and last name");
        }

        await registerOrgAdmin({
          username,
          email,
          password,
          password2: confirmPassword,
          phone_number: phoneNumber,
          first_name: firstName,
          last_name: lastName,
          organization_name: selectedOrgName,
          organization_type: selectedOrgType,
        });
        alert(
          "Registration submitted! Awaiting system administrator approval.",
        );
        setUsername("");
        setEmail("");
        setPassword("");
        setConfirmPassword("");
        setPhoneNumber("");
        setFirstName("");
        setLastName("");
        setSelectedOrgName("");
        setSelectedOrgType("");
        setActiveTab("login");
      }
    } catch (err: any) {
      setError(err.message || "An error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleTabChange = (tab: "login" | "register" | "org-admin") => {
    setActiveTab(tab);
    setError(null);
    // Reset form fields when switching tabs
    setUsername("");
    setEmail("");
    setPassword("");
    setConfirmPassword("");
    setPhoneNumber("");
    setFirstName("");
    setLastName("");
    setSelectedOrgName("");
    setSelectedOrgType("");
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col justify-center py-12 sm:px-6 lg:px-8">
      <div className="sm:mx-auto sm:w-full sm:max-w-md">
        <div className="flex justify-center">
          <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center shadow-lg">
            <svg
              className="w-8 h-8 text-white"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"
              />
            </svg>
          </div>
        </div>
        <h2 className="mt-6 text-center text-3xl font-extrabold text-gray-900">
          {activeTab === "login" && "Welcome back"}
          {activeTab === "register" && "Join as a Donor"}
          {activeTab === "org-admin" && "Register as Organization Admin"}
        </h2>
        <p className="mt-2 text-center text-sm text-gray-600">
          {activeTab === "login" && "Sign in to your account"}
          {activeTab === "register" &&
            "Create a donor account to see what needs helping"}
          {activeTab === "org-admin" &&
            "Register your organization and manage its needs"}
        </p>
      </div>

      <div className="mt-8 sm:mx-auto sm:w-full sm:max-w-md">
        <div className="bg-white py-8 px-4 shadow sm:rounded-lg sm:px-10 border border-gray-100">
          {/* Tab Selector */}
          <div className="flex border-b border-gray-200 mb-6">
            {(["login", "register", "org-admin"] as const).map((tab) => (
              <button
                key={tab}
                onClick={() => handleTabChange(tab)}
                className={`flex-1 py-2 px-3 text-sm font-medium border-b-2 transition-colors ${
                  activeTab === tab
                    ? "border-blue-600 text-blue-600"
                    : "border-transparent text-gray-600 hover:text-gray-900"
                }`}
              >
                {tab === "login" && "Sign In"}
                {tab === "register" && "Donor"}
                {tab === "org-admin" && "Org Admin"}
              </button>
            ))}
          </div>

          <form className="space-y-6" onSubmit={handleSubmit}>
            {/* Error Message */}
            {error && (
              <div className="rounded-md bg-red-50 p-4">
                <div className="flex">
                  <div className="flex-shrink-0">
                    <svg
                      className="h-5 w-5 text-red-400"
                      viewBox="0 0 20 20"
                      fill="currentColor"
                    >
                      <path
                        fillRule="evenodd"
                        d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z"
                        clipRule="evenodd"
                      />
                    </svg>
                  </div>
                  <div className="ml-3">
                    <h3 className="text-sm font-medium text-red-800">Error</h3>
                    <div className="mt-2 text-sm text-red-700">
                      <p>{error}</p>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* Username */}
            <div>
              <label
                htmlFor="username"
                className="block text-sm font-medium text-gray-700"
              >
                Username
              </label>
              <div className="mt-1 relative rounded-md shadow-sm">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <svg
                    className="h-5 w-5 text-gray-400"
                    xmlns="http://www.w3.org/2000/svg"
                    viewBox="0 0 20 20"
                    fill="currentColor"
                  >
                    <path
                      fillRule="evenodd"
                      d="M10 9a3 3 0 100-6 3 3 0 000 6zm-7 9a7 7 0 1114 0H3z"
                      clipRule="evenodd"
                    />
                  </svg>
                </div>
                <input
                  id="username"
                  name="username"
                  type="text"
                  required
                  className="block w-full pl-10 sm:text-sm border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500 p-2 border"
                  placeholder="johndoe"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                />
              </div>
            </div>

            {/* Email - for register and org-admin tabs */}
            {(activeTab === "register" || activeTab === "org-admin") && (
              <div>
                <label
                  htmlFor="email"
                  className="block text-sm font-medium text-gray-700"
                >
                  Email Address
                </label>
                <div className="mt-1 relative rounded-md shadow-sm">
                  <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <svg
                      className="h-5 w-5 text-gray-400"
                      viewBox="0 0 20 20"
                      fill="currentColor"
                    >
                      <path d="M2.003 5.884L10 9.882l7.997-3.998A2 2 0 0016 4H4a2 2 0 00-1.997 1.884z" />
                      <path d="M18 8.118l-8 4-8-4V14a2 2 0 002 2h12a2 2 0 002-2V8.118z" />
                    </svg>
                  </div>
                  <input
                    id="email"
                    name="email"
                    type="email"
                    required
                    className="block w-full pl-10 sm:text-sm border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500 p-2 border"
                    placeholder="you@example.com"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                  />
                </div>
              </div>
            )}

            {/* Phone - for register and org-admin tabs */}
            {(activeTab === "register" || activeTab === "org-admin") && (
              <div>
                <label
                  htmlFor="phone"
                  className="block text-sm font-medium text-gray-700"
                >
                  Phone Number
                </label>
                <div className="mt-1 relative rounded-md shadow-sm">
                  <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <svg
                      className="h-5 w-5 text-gray-400"
                      viewBox="0 0 20 20"
                      fill="currentColor"
                    >
                      <path d="M2 3a1 1 0 011-1h2.153a1 1 0 01.986.836l.74 4.435a1 1 0 01-.54 1.06l-1.548.773a11.037 11.037 0 006.105 6.105l.774-1.548a1 1 0 011.059-.54l4.435.74a1 1 0 01.836.986V17a1 1 0 01-1 1h-2C7.82 18 2 12.18 2 5V3z" />
                    </svg>
                  </div>
                  <input
                    id="phone"
                    name="phone"
                    type="tel"
                    required
                    className="block w-full pl-10 sm:text-sm border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500 p-2 border"
                    placeholder="+94 77 123 4567"
                    value={phoneNumber}
                    onChange={(e) => setPhoneNumber(e.target.value)}
                  />
                </div>
              </div>
            )}

            {/* First Name - org-admin only */}
            {(activeTab === "register" || activeTab === "org-admin") && (
              <div>
                <label
                  htmlFor="firstName"
                  className="block text-sm font-medium text-gray-700"
                >
                  First Name
                </label>
                <input
                  id="firstName"
                  name="firstName"
                  type="text"
                  required
                  className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500 sm:text-sm"
                  placeholder="John"
                  value={firstName}
                  onChange={(e) => setFirstName(e.target.value)}
                />
              </div>
            )}

            {/* Last Name - org-admin only */}
            {(activeTab === "register" || activeTab === "org-admin") && (
              <div>
                <label
                  htmlFor="lastName"
                  className="block text-sm font-medium text-gray-700"
                >
                  Last Name
                </label>
                <input
                  id="lastName"
                  name="lastName"
                  type="text"
                  required
                  className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500 sm:text-sm"
                  placeholder="Doe"
                  value={lastName}
                  onChange={(e) => setLastName(e.target.value)}
                />
              </div>
            )}

            {/* Organization & Organization Type - org-admin only */}
            {activeTab === "org-admin" && (
              <>
                <div>
                  <label
                    htmlFor="organization"
                    className="block text-sm font-medium text-gray-700"
                  >
                    Organization Name
                  </label>
                  <input
                    id="organization"
                    name="organization"
                    type="text"
                    required
                    className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500 sm:text-sm"
                    placeholder="Type the name of your organization"
                    value={selectedOrgName}
                    onChange={(e) => setSelectedOrgName(e.target.value)}
                  />
                </div>

                {/* Organization Type - independent dropdown */}
                <div>
                  <label
                    htmlFor="orgType"
                    className="block text-sm font-medium text-gray-700"
                  >
                    Organization Type
                  </label>
                  <select
                    id="orgType"
                    name="orgType"
                    required
                    className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500 sm:text-sm"
                    value={selectedOrgType}
                    onChange={(e) => setSelectedOrgType(e.target.value)}
                  >
                    <option value="">-- Select organization type --</option>
                    {ORG_TYPE_OPTIONS.map((option) => (
                      <option key={option.value} value={option.value}>
                        {option.label}
                      </option>
                    ))}
                  </select>
                </div>
              </>
            )}

            {/* Password */}
            <div>
              <label
                htmlFor="password"
                className="block text-sm font-medium text-gray-700"
              >
                Password
              </label>
              <div className="mt-1 relative rounded-md shadow-sm">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <svg
                    className="h-5 w-5 text-gray-400"
                    viewBox="0 0 20 20"
                    fill="currentColor"
                  >
                    <path
                      fillRule="evenodd"
                      d="M5 9V7a5 5 0 0110 0v2a2 2 0 012 2v5a2 2 0 01-2 2H5a2 2 0 01-2-2v-5a2 2 0 012-2zm8-2v2H7V7a3 3 0 016 0z"
                      clipRule="evenodd"
                    />
                  </svg>
                </div>
                <input
                  id="password"
                  name="password"
                  type={showPassword ? "text" : "password"}
                  required
                  className="block w-full pl-10 pr-10 sm:text-sm border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500 p-2 border"
                  placeholder="••••••••"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute inset-y-0 right-0 pr-3 flex items-center text-gray-400 hover:text-gray-600"
                  tabIndex={-1}
                >
                  {showPassword ? (
                    <svg
                      className="h-5 w-5"
                      viewBox="0 0 20 20"
                      fill="currentColor"
                    >
                      <path d="M10 12a2 2 0 100-4 2 2 0 000 4z" />
                      <path
                        fillRule="evenodd"
                        d="M.458 10C1.732 5.943 5.522 3 10 3s8.268 2.943 9.542 7c-1.274 4.057-5.064 7-9.542 7S1.732 14.057.458 10zM14 10a4 4 0 11-8 0 4 4 0 018 0z"
                        clipRule="evenodd"
                      />
                    </svg>
                  ) : (
                    <svg
                      className="h-5 w-5"
                      viewBox="0 0 20 20"
                      fill="currentColor"
                    >
                      <path
                        fillRule="evenodd"
                        d="M3.707 2.293a1 1 0 00-1.414 1.414l14 14a1 1 0 001.414-1.414l-1.473-1.473A10.014 10.014 0 0019.542 10C18.268 5.943 14.478 3 10 3a9.958 9.958 0 00-4.512 1.074l-1.78-1.781zm4.261 4.26l1.514 1.515a2.003 2.003 0 012.45 2.45l1.514 1.514a4 4 0 00-5.478-5.478z"
                        clipRule="evenodd"
                      />
                      <path d="M12.454 16.697L9.75 13.992a4 4 0 01-3.742-3.741L2.335 6.578A9.98 9.98 0 00.458 10c1.274 4.057 5.065 7 9.542 7 .847 0 1.669-.105 2.454-.303z" />
                    </svg>
                  )}
                </button>
              </div>
            </div>

            {/* Confirm Password - for register and org-admin tabs */}
            {(activeTab === "register" || activeTab === "org-admin") && (
              <div>
                <label
                  htmlFor="confirmPassword"
                  className="block text-sm font-medium text-gray-700"
                >
                  Confirm Password
                </label>
                <div className="mt-1 relative rounded-md shadow-sm">
                  <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <svg
                      className="h-5 w-5 text-gray-400"
                      viewBox="0 0 20 20"
                      fill="currentColor"
                    >
                      <path
                        fillRule="evenodd"
                        d="M5 9V7a5 5 0 0110 0v2a2 2 0 012 2v5a2 2 0 01-2 2H5a2 2 0 01-2-2v-5a2 2 0 012-2zm8-2v2H7V7a3 3 0 016 0z"
                        clipRule="evenodd"
                      />
                    </svg>
                  </div>
                  <input
                    id="confirmPassword"
                    name="confirmPassword"
                    type={showConfirmPassword ? "text" : "password"}
                    required
                    className="block w-full pl-10 pr-10 sm:text-sm border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500 p-2 border"
                    placeholder="••••••••"
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                  />
                  <button
                    type="button"
                    onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                    className="absolute inset-y-0 right-0 pr-3 flex items-center text-gray-400 hover:text-gray-600"
                    tabIndex={-1}
                  >
                    {showConfirmPassword ? (
                      <svg
                        className="h-5 w-5"
                        viewBox="0 0 20 20"
                        fill="currentColor"
                      >
                        <path d="M10 12a2 2 0 100-4 2 2 0 000 4z" />
                        <path
                          fillRule="evenodd"
                          d="M.458 10C1.732 5.943 5.522 3 10 3s8.268 2.943 9.542 7c-1.274 4.057-5.064 7-9.542 7S1.732 14.057.458 10zM14 10a4 4 0 11-8 0 4 4 0 018 0z"
                          clipRule="evenodd"
                        />
                      </svg>
                    ) : (
                      <svg
                        className="h-5 w-5"
                        viewBox="0 0 20 20"
                        fill="currentColor"
                      >
                        <path
                          fillRule="evenodd"
                          d="M3.707 2.293a1 1 0 00-1.414 1.414l14 14a1 1 0 001.414-1.414l-1.473-1.473A10.014 10.014 0 0019.542 10C18.268 5.943 14.478 3 10 3a9.958 9.958 0 00-4.512 1.074l-1.78-1.781zm4.261 4.26l1.514 1.515a2.003 2.003 0 012.45 2.45l1.514 1.514a4 4 0 00-5.478-5.478z"
                          clipRule="evenodd"
                        />
                        <path d="M12.454 16.697L9.75 13.992a4 4 0 01-3.742-3.741L2.335 6.578A9.98 9.98 0 00.458 10c1.274 4.057 5.065 7 9.542 7 .847 0 1.669-.105 2.454-.303z" />
                      </svg>
                    )}
                  </button>
                </div>
              </div>
            )}

            {/* Remember me - login tab only */}
            {activeTab === "login" && (
              <div className="flex items-center justify-between">
                <div className="flex items-center">
                  <input
                    id="remember-me"
                    name="remember-me"
                    type="checkbox"
                    className="h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300 rounded"
                  />
                  <label
                    htmlFor="remember-me"
                    className="ml-2 block text-sm text-gray-900"
                  >
                    Remember me
                  </label>
                </div>

                <div className="text-sm">
                  <Link
                    href="/forgot-password"
                    className="font-medium text-blue-600 hover:text-blue-500"
                  >
                    Forgot your password?
                  </Link>
                </div>
              </div>
            )}

            {/* Submit Button */}
            <div>
              <button
                type="submit"
                disabled={loading}
                className="w-full flex justify-center py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:opacity-50 transition-colors"
              >
                {loading
                  ? "Processing..."
                  : activeTab === "login"
                    ? "Sign In"
                    : "Register"}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useSearchParams } from "next/navigation";
import { NeedItem, getNeeds, priorityLabels } from "@/lib/api";
import { useAuth } from "@/lib/AuthContext";
import NeedCard from "@/components/NeedCard";
import PriorityFilter from "@/components/PriorityFilter";
import { PageLoading } from "@/components/LoadingSpinner";

export default function NeedsContent() {
  const { user } = useAuth();
  const searchParams = useSearchParams();
  const [needs, setNeeds] = useState<NeedItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [priorityFilter, setPriorityFilter] = useState<string | null>(
    searchParams.get("priority"),
  );
  const [sortBy, setSortBy] = useState<"priority" | "date" | "progress">(
    "priority",
  );

  const fetchNeeds = async () => {
    try {
      const data = await getNeeds(priorityFilter || undefined, true);
      setNeeds(data);
    } catch (error) {
      console.error("Failed to fetch needs:", error);
    }
  };

  useEffect(() => {
    async function fetchNeedsWithLoader() {
      setLoading(true);
      await fetchNeeds();
      setLoading(false);
    }
    fetchNeedsWithLoader();
  }, [priorityFilter]);

  // Sort needs
  const sortedNeeds = [...needs].sort((a, b) => {
    if (sortBy === "priority") {
      const priorityOrder = { CRITICAL: 0, ESSENTIAL: 1, NICE: 2 };
      return priorityOrder[a.priority] - priorityOrder[b.priority];
    }
    if (sortBy === "date") {
      return (
        new Date(b.created_at).getTime() - new Date(a.created_at).getTime()
      );
    }
    if (sortBy === "progress") {
      const progressA =
        a.quantity_required > 0 ? a.quantity_received / a.quantity_required : 0;
      const progressB =
        b.quantity_required > 0 ? b.quantity_received / b.quantity_required : 0;
      return progressA - progressB; // Show least fulfilled first
    }
    return 0;
  });

  // Stats
  const stats = {
    total: needs.length,
    critical: needs.filter((n) => n.priority === "CRITICAL").length,
    essential: needs.filter((n) => n.priority === "ESSENTIAL").length,
    nice: needs.filter((n) => n.priority === "NICE").length,
    fulfilled: needs.filter((n) => n.quantity_received >= n.quantity_required)
      .length,
  };

  if (loading) return <PageLoading />;

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      {/* Header */}
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-gray-900">All Needs</h1>
        <p className="text-gray-500 mt-1">
          {user?.role === "ORG_ADMIN"
            ? "View and manage all registered needs of the organization"
            : "View all registered needs across organizations"}
        </p>
      </div>

      {/* Stats Bar */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 mb-6">
        <div className="flex flex-wrap gap-6">
          <div className="flex items-center gap-2">
            <div className="w-3 h-3 bg-gray-400 rounded-full"></div>
            <span className="text-sm text-gray-600">
              Total: <strong>{stats.total}</strong>
            </span>
          </div>
          <div className="flex items-center gap-2">
            <div className="w-3 h-3 bg-red-500 rounded-full"></div>
            <span className="text-sm text-gray-600">
              Critical: <strong>{stats.critical}</strong>
            </span>
          </div>
          <div className="flex items-center gap-2">
            <div className="w-3 h-3 bg-yellow-500 rounded-full"></div>
            <span className="text-sm text-gray-600">
              Essential: <strong>{stats.essential}</strong>
            </span>
          </div>
          <div className="flex items-center gap-2">
            <div className="w-3 h-3 bg-green-500 rounded-full"></div>
            <span className="text-sm text-gray-600">
              Nice to Have: <strong>{stats.nice}</strong>
            </span>
          </div>
          <div className="flex items-center gap-2">
            <div className="w-3 h-3 bg-blue-500 rounded-full"></div>
            <span className="text-sm text-gray-600">
              Fulfilled: <strong>{stats.fulfilled}</strong>
            </span>
          </div>
        </div>
      </div>

      {/* Filters */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-6">
        <PriorityFilter
          selected={priorityFilter}
          onChange={setPriorityFilter}
        />

        <div className="flex items-center gap-2">
          <label htmlFor="sort-select" className="text-sm text-gray-600">
            Sort by:
          </label>
          <select
            id="sort-select"
            value={sortBy}
            onChange={(e) =>
              setSortBy(e.target.value as "priority" | "date" | "progress")
            }
            className="px-3 py-2 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white text-gray-900"
          >
            <option value="priority">Priority</option>
            <option value="date">Most Recent</option>
            <option value="progress">Least Fulfilled</option>
          </select>
        </div>
      </div>

      {/* Results */}
      {priorityFilter && (
        <div className="mb-4 flex items-center gap-2">
          <span className="text-sm text-gray-600">
            Showing {sortedNeeds.length}{" "}
            {priorityLabels[priorityFilter as keyof typeof priorityLabels]}{" "}
            needs
          </span>
          <button
            onClick={() => setPriorityFilter(null)}
            className="text-sm text-blue-600 hover:text-blue-700"
          >
            Clear filter
          </button>
        </div>
      )}

      {/* Needs Grid */}
      {sortedNeeds.length > 0 ? (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {sortedNeeds.map((need) => (
            <NeedCard
              key={need.id}
              need={need}
              showSection
              organizationName={need.section_detail?.organization_name}
            />
          ))}
        </div>
      ) : (
        <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-12 text-center">
          <svg
            className="w-16 h-16 text-gray-300 mx-auto mb-4"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2"
            />
          </svg>
          <h2 className="text-lg font-semibold text-gray-900">
            No needs found
          </h2>
          <p className="text-gray-600 mt-2">
            {user?.role === "ORG_ADMIN"
              ? "There are currently no registered needs matching your criteria."
              : "There are currently no registered needs matching criteria of organizations."}
          </p>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useAuth } from "@/lib/AuthContext";
import { 
  Organization, getOrganizations, 
  NeedItem, getNeeds,
  Donation, getDonations
} from "@/lib/api";
import LoadingSpinner from "@/components/LoadingSpinner";
import StatsCard from "@/components/StatsCard";
import AnalyticsView from "@/components/AnalyticsView";
import GraphsView from "@/components/GraphsView";
import { 
  Building2, 
  Layers, 
  ClipboardList, 
  AlertTriangle, 
  DollarSign,
  FileText,
  BarChart3,
  ArrowRight,
  PieChart
} from "lucide-react";
import { useRouter } from "next/navigation";
import Link from "next/link";

export default function OrgAdminDashboard() {
  const router = useRouter();
  const { user, loading: authLoading } = useAuth();

  const [organization, setOrganization] = useState<Organization | null>(null);
  const [stats, setStats] = useState({
    sections: 0,
    totalNeeds: 0,
    criticalNeeds: 0,
    donations: 0
  });
  const [analytics, setAnalytics] = useState({
    fulfillmentRate: 0,
    donationRate: 0,
    sectionMetrics: [] as any[],
    monthlyData: [] as any[],
    yearlyData: [] as any[]
  });
  const [criticalNeeds, setCriticalNeeds] = useState<NeedItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    if (!authLoading && user?.role !== "ORG_ADMIN") {
      router.push("/");
    }
  }, [user, authLoading, router]);

  useEffect(() => {
    const fetchDashboardData = async () => {
      if (!user || user.role !== "ORG_ADMIN") return;

      try {
        setIsLoading(true);
        setError("");

        const orgs = await getOrganizations();
        if (orgs.length === 0) {
          setIsLoading(false);
          return;
        }

        const myOrg = orgs[0];
        setOrganization(myOrg);

        const allNeeds = await getNeeds();
        const myNeeds = allNeeds.filter(n => n.section_detail?.organization === myOrg.id);
        const critical = myNeeds.filter(n => n.priority === "CRITICAL");

        const allDonations = await getDonations();
        const myDonations = allDonations.filter(d => d.need_item_detail?.id && myNeeds.some(n => n.id === d.need_item));

        // Analytics Calculations
        const totalRequired = myNeeds.reduce((sum, n) => sum + n.quantity_required, 0);
        const totalReceived = myNeeds.reduce((sum, n) => sum + n.quantity_received, 0);
        const fulfillmentRate = totalRequired > 0 ? Math.round((totalReceived / totalRequired) * 100) : 0;

        const needsWithDonations = myNeeds.filter(n => myDonations.some(d => d.need_item === n.id)).length;
        const donationRate = myNeeds.length > 0 ? Math.round((needsWithDonations / myNeeds.length) * 100) : 0;

        // Section Metrics
        const sectionMetrics = (myOrg.sections || []).map(section => {
          const sectionNeeds = myNeeds.filter(n => n.section === section.id);
          const received = sectionNeeds.reduce((sum, n) => sum + n.quantity_received, 0);
          const required = sectionNeeds.reduce((sum, n) => sum + n.quantity_required, 0);
          const percentage = required > 0 ? Math.round((received / required) * 100) : 0;

          return {
            label: section.name,
            value: received,
            total: required,
            percentage,
            status: percentage > 80 ? "success" : percentage < 30 ? "critical" : "warning"
          };
        });

        // Time-based data for Graphs
        const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
        const currentMonth = new Date().getMonth();
        const last6Months = [];
        for (let i = 5; i >= 0; i--) {
            const m = (currentMonth - i + 12) % 12;
            last6Months.push(months[m]);
        }

        const monthlyData = last6Months.map(month => {
            // Mocking historical data based on current donations for demonstration
            // In a real app, this would be grouped by donation.created_at
            const count = myDonations.length > 0 ? Math.floor(Math.random() * myDonations.length) + 1 : 0;
            return { name: month, donations: count, fulfillment: Math.floor(Math.random() * 100) };
        });

        const yearlyData = [
            { name: '2023', donations: Math.floor(myDonations.length * 0.8), fulfillment: 65 },
            { name: '2024', donations: myDonations.length, fulfillment: fulfillmentRate },
            { name: '2025', donations: Math.floor(myDonations.length * 1.2), fulfillment: 0 },
        ];

        setStats({
          sections: myOrg.sections?.length || 0,
          totalNeeds: myNeeds.length,
          criticalNeeds: critical.length,
          donations: myDonations.length
        });

        setAnalytics({
          fulfillmentRate,
          donationRate,
          sectionMetrics,
          monthlyData,
          yearlyData
        });

        setCriticalNeeds(critical.slice(0, 3));
      } catch (err: unknown) {
        setError(err instanceof Error ? err.message : "Failed to fetch dashboard data");
      } finally {
        setIsLoading(false);
      }
    };

    fetchDashboardData();
  }, [user]);

  if (authLoading || isLoading) return <div className="flex items-center justify-center min-h-screen"><LoadingSpinner /></div>;

  if (!organization) {
    return (
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-20 text-center">
        <Building2 className="text-blue-600 mx-auto mb-6" size={40} />
        <h1 className="text-3xl font-bold mb-4">No Organization Assigned</h1>
        <Link href="/organizations/new" className="px-6 py-3 bg-blue-600 text-white rounded-xl font-bold">Register Your Organization</Link>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50/50 pb-20">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-10">

        {/* Header */}
        <div className="mb-10 flex flex-col md:flex-row md:items-center justify-between gap-6">
          <div>
            <div className="flex items-center gap-2 mb-1">
              <span className="px-2 py-0.5 bg-blue-600 text-white text-[10px] font-bold uppercase rounded">Org Admin</span>
              <span className="text-slate-400 text-sm">— {organization.name}</span>
            </div>
            <h1 className="text-3xl font-bold text-slate-900 tracking-tight">Organization Dashboard</h1>
            <p className="text-slate-500 mt-1">Manage your organization's needs and monitor impact</p>
          </div>
          <div className="flex items-center gap-3">
             <Link href="/documents" className="px-4 py-2.5 bg-blue-600 text-white rounded-xl text-sm font-bold flex items-center gap-2 shadow-lg shadow-blue-600/20"><FileText size={18} />Upload Document</Link>
          </div>
        </div>

        {/* Stats */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 mb-12">
            <StatsCard title="Sections" value={stats.sections} subtitle="Internal departments" icon={<Layers size={20} />} color="purple" />
            <StatsCard title="Total Needs" value={stats.totalNeeds} subtitle="Items registered" icon={<ClipboardList size={20} />} color="green" />
            <StatsCard title="Critical Needs" value={stats.criticalNeeds} subtitle="Urgent items" icon={<AlertTriangle size={20} />} color="red" />
            <StatsCard title="Donations" value={stats.donations} subtitle="Total contributions" icon={<DollarSign size={20} />} color="blue" />
        </div>

        {/* Analytics & Graphs */}
        <div id="analytics-section" className="mb-12">
          <div className="flex items-center justify-between mb-8">
            <div>
              <h2 className="text-2xl font-black text-slate-900">Organization Analytics</h2>
              <p className="text-slate-500 text-sm">Visualizing donation trends and fulfillment impact</p>
            </div>
            <div className="bg-white px-4 py-2 rounded-xl border border-slate-200 flex items-center gap-2 shadow-sm">
                <BarChart3 className="text-blue-600" size={18} />
                <span className="text-sm font-bold text-slate-700">Full Report</span>
            </div>
          </div>

          <AnalyticsView 
            fulfillmentRate={analytics.fulfillmentRate}
            donationRate={analytics.donationRate}
            sectionMetrics={analytics.sectionMetrics}
          />

          <GraphsView 
            monthlyData={analytics.monthlyData}
            yearlyData={analytics.yearlyData}
          />
        </div>

        {/* Management Center */}
        <div className="bg-slate-950 rounded-3xl p-10 shadow-2xl relative overflow-hidden mb-12">
          <div className="relative z-10">
            <div className="mb-10">
              <span className="inline-block px-3 py-1 bg-white/10 rounded-full text-[10px] font-bold tracking-widest uppercase text-blue-300 mb-4">Management Center</span>
              <h2 className="text-3xl font-bold text-white tracking-tight">Manage your organization</h2>
            </div>

            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-4">
              <ControlTile label="Manage Needs" desc="Update or add needs." icon={<ClipboardList size={20} />} href="/organizations" color="blue" />
              <ControlTile label="AI Upload" desc="Extract needs from lists." icon={<FileText size={20} />} href="/documents" color="indigo" />
              <ControlTile label="Track Donations" desc="See all pledges." icon={<DollarSign size={20} />} href="/admin/donations" color="emerald" />
              <ControlTile label="View Analytics" desc="Detailed graphs & trends." icon={<PieChart size={20} />} href="#analytics-section" color="rose" />
              <ControlTile label="Org Profile" desc="Update hospital info." icon={<Building2 size={20} />} href="/organizations" color="amber" />
            </div>
          </div>
        </div>

        <div className="grid lg:grid-cols-12 gap-8">
            <div className="lg:col-span-8">
                <div className="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm">
                    <h3 className="font-bold text-slate-900 mb-6">Recent Critical Needs</h3>
                    <div className="space-y-4">
                        {criticalNeeds.map(need => (
                            <div key={need.id} className="p-4 bg-slate-50 rounded-xl border border-slate-100 flex justify-between items-center">
                                <div>
                                    <p className="font-bold text-slate-900">{need.name}</p>
                                    <p className="text-xs text-slate-500">{need.section_detail?.name}</p>
                                </div>
                                <div className="text-right">
                                    <p className="text-sm font-bold text-rose-600">{need.quantity_required - need.quantity_received} left</p>
                                    <div className="w-24 h-1.5 bg-slate-200 rounded-full mt-1 overflow-hidden">
                                        <div className="h-full bg-rose-500" style={{ width: `${Math.round((need.quantity_received/need.quantity_required)*100)}%` }} />
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
            <div className="lg:col-span-4">
                <div className="bg-gradient-to-br from-slate-900 to-slate-800 rounded-2xl p-8 text-white h-full shadow-xl">
                    <h3 className="text-xl font-bold mb-6 text-blue-400">Monthly Snapshot</h3>
                    <div className="space-y-8">
                        <div>
                            <p className="text-slate-400 text-xs font-bold uppercase tracking-wider mb-2">Total Received</p>
                            <p className="text-3xl font-black">{analytics.fulfillmentRate}% <span className="text-xs text-emerald-400 font-bold ml-2">↑ 12%</span></p>
                        </div>
                        <div>
                            <p className="text-slate-400 text-xs font-bold uppercase tracking-wider mb-2">New Donors</p>
                            <p className="text-3xl font-black">{stats.donations} <span className="text-xs text-blue-400 font-bold ml-2">Active</span></p>
                        </div>
                    </div>
                </div>
            </div>
        </div>

      </div>
    </div>
  );
}

function ControlTile({ label, desc, icon, href, color }: { label: string, desc: string, icon: any, href: string, color: string }) {
  const colorMap: any = {
    blue: "bg-blue-500/10 text-blue-400 border-blue-500/20 hover:bg-blue-500/20",
    indigo: "bg-indigo-500/10 text-indigo-400 border-indigo-500/20 hover:bg-indigo-500/20",
    rose: "bg-rose-500/10 text-rose-400 border-rose-500/20 hover:bg-rose-500/20",
    emerald: "bg-emerald-500/10 text-emerald-400 border-emerald-500/20 hover:bg-emerald-500/20",
    amber: "bg-amber-500/10 text-amber-400 border-amber-500/20 hover:bg-amber-500/20"
  };
  return (
    <Link href={href} className={`p-6 rounded-2xl border transition-all hover:-translate-y-1 ${colorMap[color]}`}>
      <div className="w-10 h-10 bg-white/5 rounded-xl flex items-center justify-center mb-4">{icon}</div>
      <h4 className="font-bold text-white text-sm mb-2">{label}</h4>
      <p className="text-[11px] text-slate-400 leading-relaxed font-medium">{desc}</p>
    </Link>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useParams } from "next/navigation";
import Link from "next/link";
import { Organization, getOrganization, createSection } from "@/lib/api";
import SectionAccordion from "@/components/SectionAccordion";
import { PageLoading } from "@/components/LoadingSpinner";
import { useAuth } from "@/lib/AuthContext";

const orgTypeConfig: Record<string, { label: string; gradient: string }> = {
  HOSPITAL: { label: "Hospital", gradient: "from-blue-600 to-blue-900" },
  CLINIC: { label: "Clinic", gradient: "from-cyan-600 to-cyan-900" },
  SCHOOL: { label: "School", gradient: "from-violet-600 to-violet-900" },
  NGO: { label: "NGO", gradient: "from-emerald-600 to-emerald-900" },
  CHARITY: { label: "Charity", gradient: "from-rose-600 to-rose-900" },
  GOVERNMENT: { label: "Government", gradient: "from-slate-600 to-slate-900" },
  OTHER: { label: "Organization", gradient: "from-gray-600 to-gray-900" },
};

export default function OrganizationDetailPage() {
  const { user } = useAuth();
  const isAdmin = user?.role === "ADMIN" || user?.role === "ORG_ADMIN";
  const isOrgAdmin = user?.role === "ORG_ADMIN";
  const params = useParams();
  const [organization, setOrganization] = useState<Organization | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Add Section modal state
  const [showAddSection, setShowAddSection] = useState(false);
  const [sectionName, setSectionName] = useState("");
  const [sectionHead, setSectionHead] = useState("");
  const [sectionSaving, setSectionSaving] = useState(false);
  const [sectionError, setSectionError] = useState<string | null>(null);

  async function fetchOrganization() {
    try {
      const id = Number(params.id);
      const org = await getOrganization(id);
      setOrganization(org);
    } catch (err) {
      setError(
        err instanceof Error ? err.message : "Failed to load organization",
      );
    }
  }

  useEffect(() => {
    if (params.id) {
      async function load() {
        setLoading(true);
        await fetchOrganization();
        setLoading(false);
      }
      load();
    }
  }, [params.id]);

  const handleAddSection = async (e: React.FormEvent) => {
    e.preventDefault();
    setSectionSaving(true);
    setSectionError(null);
    try {
      await createSection({
        name: sectionName,
        head_of_section: sectionHead,
        organization: Number(params.id),
      });
      // Refresh org data to show new section
      await fetchOrganization();
      setShowAddSection(false);
      setSectionName("");
      setSectionHead("");
    } catch (err) {
      setSectionError(
        err instanceof Error ? err.message : "Failed to create section",
      );
    } finally {
      setSectionSaving(false);
    }
  };

  if (loading) return <PageLoading />;

  if (error || !organization) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-8">
        <div className="bg-red-50 border border-red-200 rounded-lg p-6 text-center">
          <h3 className="text-lg font-medium text-red-800 mb-2">
            Organization Not Found
          </h3>
          <p className="text-red-600 mb-4">
            {error || "The requested organization does not exist"}
          </p>
          <Link href="/" className="text-blue-600 hover:text-blue-700">
            ← Back to Home
          </Link>
        </div>
      </div>
    );
  }

  const totalNeeds =
    organization.sections?.reduce(
      (acc, section) => acc + (section.needs?.length || 0),
      0,
    ) || 0;

  const typeConfig = orgTypeConfig[organization.org_type || "OTHER"];

  // Filter sections for ADMIN users to only show sections created by ORG_ADMINs
  const filteredSections =
    user?.role === "ADMIN"
      ? organization.sections?.filter(
          (section) => section.created_by_role === "ORG_ADMIN",
        ) || []
      : organization.sections || [];

  // Filter out fulfilled needs from sections for public display
  const sectionsWithUnfulfilledNeeds =
    filteredSections?.map((section) => ({
      ...section,
      needs:
        section.needs?.filter(
          (need) => need.quantity_received < need.quantity_required,
        ) || [],
    })) || [];

  const filteredTotalNeeds =
    sectionsWithUnfulfilledNeeds?.reduce(
      (acc, section) => acc + (section.needs?.length || 0),
      0,
    ) || 0;

  const filteredCriticalNeeds =
    sectionsWithUnfulfilledNeeds?.reduce(
      (acc, section) =>
        acc +
        (section.needs?.filter((n) => n.priority === "CRITICAL").length || 0),
      0,
    ) || 0;

  // Calculate fulfilled needs from original filtered sections (before unfulfilled filter)
  const filteredFulfilledNeeds =
    filteredSections?.reduce(
      (acc, section) =>
        acc +
        (section.needs?.filter(
          (n) => n.quantity_received >= n.quantity_required,
        ).length || 0),
      0,
    ) || 0;

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      {/* Hero Banner */}
      <div
        className={`rounded-2xl overflow-hidden mb-6 bg-gradient-to-br ${typeConfig.gradient}`}
      >
        <div className="px-6 pt-6 pb-0 text-white">
          {/* Top row: back + edit */}
          <div className="flex items-center justify-between mb-5">
            <Link
              href="/"
              className="text-white/60 hover:text-white text-sm flex items-center gap-1 transition-colors"
            >
              <svg
                className="w-4 h-4"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M15 19l-7-7 7-7"
                />
              </svg>
              Back to Home
            </Link>
            {isOrgAdmin && (
              <Link
                href={`/organizations/${organization.id}/edit`}
                className="flex items-center gap-1.5 px-3 py-1.5 bg-white/20 hover:bg-white/30 rounded-lg text-sm font-medium transition-colors"
              >
                <svg
                  className="w-3.5 h-3.5"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"
                  />
                </svg>
                Edit Info
              </Link>
            )}
          </div>

          {/* Type badge */}
          <span className="inline-block px-3 py-1 bg-white/20 rounded-full text-xs font-semibold text-white mb-3">
            {typeConfig.label}
          </span>

          {/* Name */}
          <h1 className="text-3xl font-bold text-white mb-2 leading-tight">
            {organization.name}
          </h1>

          {/* Description */}
          {organization.description ? (
            <p className="text-white/80 text-base max-w-2xl leading-relaxed mb-5">
              {organization.description}
            </p>
          ) : isOrgAdmin ? (
            <p className="text-white/50 italic text-sm mb-5">
              No description yet.{" "}
              <Link
                href={`/organizations/${organization.id}/edit`}
                className="underline hover:text-white"
              >
                Add one →
              </Link>
            </p>
          ) : (
            <div className="mb-5" />
          )}

          {/* Contact info chips */}
          <div className="flex flex-wrap gap-2 mb-6">
            {organization.district && (
              <span className="flex items-center gap-1.5 bg-white/15 px-3 py-1.5 rounded-full text-xs text-white/90">
                <svg
                  className="w-3.5 h-3.5"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z"
                  />
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M15 11a3 3 0 11-6 0 3 3 0 016 0z"
                  />
                </svg>
                {organization.district}
                {organization.address ? `, ${organization.address}` : ""}
              </span>
            )}
            {organization.phone && (
              <span className="flex items-center gap-1.5 bg-white/15 px-3 py-1.5 rounded-full text-xs text-white/90">
                <svg
                  className="w-3.5 h-3.5"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z"
                  />
                </svg>
                {organization.phone}
              </span>
            )}
            {organization.email_contact && (
              <a
                href={`mailto:${organization.email_contact}`}
                className="flex items-center gap-1.5 bg-white/15 hover:bg-white/25 px-3 py-1.5 rounded-full text-xs text-white/90 transition-colors"
              >
                <svg
                  className="w-3.5 h-3.5"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"
                  />
                </svg>
                {organization.email_contact}
              </a>
            )}
            {organization.website && (
              <a
                href={organization.website}
                target="_blank"
                rel="noopener noreferrer"
                className="flex items-center gap-1.5 bg-white/15 hover:bg-white/25 px-3 py-1.5 rounded-full text-xs text-white/90 transition-colors"
              >
                <svg
                  className="w-3.5 h-3.5"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M21 12a9 9 0 01-9 9m9-9a9 9 0 00-9-9m9 9H3m9 9a9 9 0 01-9-9m9 9c1.657 0 3-4.03 3-9s-1.343-9-3-9m0 18c-1.657 0-3-4.03-3-9s1.343-9 3-9m-9 9a9 9 0 019-9"
                  />
                </svg>
                {organization.website}
              </a>
            )}
            {organization.established_year && (
              <span className="flex items-center gap-1.5 bg-white/15 px-3 py-1.5 rounded-full text-xs text-white/90">
                <svg
                  className="w-3.5 h-3.5"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"
                  />
                </svg>
                Established {organization.established_year}
              </span>
            )}
          </div>
        </div>

        {/* Stats strip */}
        <div className="bg-black/20 px-6 py-4 grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="text-center">
            <p className="text-2xl font-bold text-white">
              {filteredSections?.length || 0}
            </p>
            <p className="text-xs text-white/60 mt-0.5">Sections</p>
          </div>
          <div className="text-center">
            <p className="text-2xl font-bold text-white">
              {filteredTotalNeeds}
            </p>
            <p className="text-xs text-white/60 mt-0.5">Total Needs</p>
          </div>
          <div className="text-center">
            <p className="text-2xl font-bold text-red-300">
              {filteredCriticalNeeds}
            </p>
            <p className="text-xs text-white/60 mt-0.5">Critical</p>
          </div>
          <div className="text-center">
            <p className="text-2xl font-bold text-green-300">
              {filteredFulfilledNeeds}
            </p>
            <p className="text-xs text-white/60 mt-0.5">Fulfilled</p>
          </div>
        </div>
      </div>

      {/* Sections */}
      <div>
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-xl font-bold text-gray-900">Sections & Needs</h2>
          {isOrgAdmin && (
            <button
              onClick={() => setShowAddSection(true)}
              className="inline-flex items-center gap-2 px-4 py-2 text-sm font-medium text-blue-600 bg-blue-50 rounded-lg hover:bg-blue-100 transition-colors"
            >
              <svg
                className="w-4 h-4"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M12 4v16m8-8H4"
                />
              </svg>
              Add Section
            </button>
          )}
        </div>

        {filteredSections && filteredSections.length > 0 ? (
          <div className="space-y-4">
            {sectionsWithUnfulfilledNeeds.map((section, index) => (
              <SectionAccordion
                key={section.id}
                section={section}
                organizationName={organization.name}
                defaultOpen={index === 0}
              />
            ))}
          </div>
        ) : (
          <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-12 text-center">
            <svg
              className="w-16 h-16 text-gray-300 mx-auto mb-4"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10"
              />
            </svg>
            <h3 className="text-lg font-medium text-gray-900 mb-2">
              No Sections Yet
            </h3>
            <p className="text-gray-500 mb-4">
              No sections have been added to this organization yet
            </p>
            {isOrgAdmin && (
              <button
                onClick={() => setShowAddSection(true)}
                className="inline-flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
              >
                Add First Section
              </button>
            )}
          </div>
        )}
      </div>

      {/* Add Section Modal */}
      {showAddSection && (
        <div className="fixed inset-0 z-50 overflow-y-auto">
          <div className="flex min-h-full items-center justify-center p-4">
            {/* Backdrop */}
            <div
              className="fixed inset-0 bg-black/30 transition-opacity"
              onClick={() => {
                setShowAddSection(false);
                setSectionError(null);
              }}
            />

            {/* Modal */}
            <div className="relative bg-white rounded-xl shadow-xl w-full max-w-md p-6">
              <h3 className="text-lg font-semibold text-gray-900 mb-4">
                Add New Section
              </h3>

              <form onSubmit={handleAddSection} className="space-y-4">
                <div>
                  <label
                    htmlFor="sectionName"
                    className="block text-sm font-medium text-gray-700 mb-1"
                  >
                    Section Name <span className="text-red-500">*</span>
                  </label>
                  <input
                    id="sectionName"
                    type="text"
                    required
                    placeholder="e.g. OPD, Kitchen, Maternity Ward"
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm"
                    value={sectionName}
                    onChange={(e) => setSectionName(e.target.value)}
                  />
                </div>

                <div>
                  <label
                    htmlFor="sectionHead"
                    className="block text-sm font-medium text-gray-700 mb-1"
                  >
                    Head of Section
                  </label>
                  <input
                    id="sectionHead"
                    type="text"
                    placeholder="e.g. Dr. Silva"
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm"
                    value={sectionHead}
                    onChange={(e) => setSectionHead(e.target.value)}
                  />
                </div>

                {sectionError && (
                  <div className="rounded-md bg-red-50 p-3">
                    <p className="text-sm text-red-700">{sectionError}</p>
                  </div>
                )}

                <div className="flex justify-end gap-3 pt-2">
                  <button
                    type="button"
                    onClick={() => {
                      setShowAddSection(false);
                      setSectionError(null);
                    }}
                    className="px-4 py-2 text-sm font-medium text-gray-700 bg-gray-100 rounded-lg hover:bg-gray-200 transition-colors"
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    disabled={sectionSaving}
                    className="px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded-lg hover:bg-blue-700 disabled:opacity-50 transition-colors"
                  >
                    {sectionSaving ? "Creating..." : "Create Section"}
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useCallback, useEffect, useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import {
  Organization,
  getOrganizations,
  deleteOrganization,
  NeedItem,
  Section,
  deleteNeed,
  deleteSection,
} from "@/lib/api";
import { PageLoading } from "@/components/LoadingSpinner";
import { useAdminGuard } from "@/lib/useAuthGuard";
import { useAuth } from "@/lib/AuthContext";
import SectionAccordion from "@/components/SectionAccordion";
import AddSectionModal from "@/components/AddSectionModal";
import ManualNeedEntryForm from "@/components/ManualNeedEntryForm";
import EditNeedModal from "@/components/EditNeedModal";
import EditSectionModal from "@/components/EditSectionModal";

export default function OrganizationsPage() {
  const router = useRouter();
  const { authorized, isLoading: authLoading } = useAdminGuard();
  const { user } = useAuth();
  const isAdmin = authorized;
  const [organizations, setOrganizations] = useState<Organization[]>([]);
  const [organization, setOrganization] = useState<Organization | null>(null);
  const [selectedOrgId, setSelectedOrgId] = useState<number | null>(null);
  const [loading, setLoading] = useState(true);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [showAddSection, setShowAddSection] = useState(false);
  const [addNeedForSection, setAddNeedForSection] = useState<{
    orgId: number;
    sectionId: number;
  } | null>(null);
  const [editNeed, setEditNeed] = useState<NeedItem | null>(null);
  const [deleteNeedConfirm, setDeleteNeedConfirm] = useState<NeedItem | null>(
    null,
  );
  const [deletingNeed, setDeletingNeed] = useState(false);
  const [editSection, setEditSection] = useState<Section | null>(null);
  const [isOrgExpanded, setIsOrgExpanded] = useState(true);
  const [deleteSectionConfirm, setDeleteSectionConfirm] =
    useState<Section | null>(null);
  const [deletingSection, setDeletingSection] = useState(false);
  const [editSectionConfirm, setEditSectionConfirm] = useState<Section | null>(
    null,
  );

  const fetchOrganizations = useCallback(async () => {
    try {
      const orgs = await getOrganizations();
      setOrganizations(orgs);

      // If ADMIN, show all organizations; if ORG_ADMIN, show only their organization
      if (user?.role === "ADMIN") {
        // ADMIN sees all organizations
        if (orgs.length > 0) {
          const firstOrgId = orgs[0].id;
          setSelectedOrgId(firstOrgId);
          setOrganization(orgs[0]);
        }
      } else if (user?.role === "ORG_ADMIN") {
        // ORG_ADMIN sees only their organization
        if (orgs.length > 0) {
          setOrganization(orgs[0]);
          setSelectedOrgId(orgs[0].id);
        }
      }
    } catch (err) {
      setOrganizations([]);
      setOrganization(null);
    }
  }, [user?.role]);

  useEffect(() => {
    const loadData = async () => {
      if (!authorized) return;
      setLoading(true);
      await fetchOrganizations();
      setLoading(false);
    };
    loadData();
  }, [authorized, fetchOrganizations]);

  const findNeedById = (needId: number): NeedItem | null => {
    if (!organization?.sections) return null;
    for (const section of organization.sections) {
      const found = section.needs?.find((n) => n.id === needId);
      if (found) return found;
    }
    return null;
  };

  async function handleDeleteNeed(needId: number) {
    setDeletingNeed(true);
    try {
      await deleteNeed(needId);
      setDeleteNeedConfirm(null);
      setLoading(true);
      await fetchOrganizations();
      setLoading(false);
    } catch {
      alert("Failed to delete need. Please try again.");
    } finally {
      setDeletingNeed(false);
    }
  }

  async function handleDeleteSection(sectionId: number) {
    const section = organization?.sections?.find((s) => s.id === sectionId);
    if (section) {
      setDeleteSectionConfirm(section);
    }
  }

  async function confirmDeleteSection() {
    if (!deleteSectionConfirm) return;
    setDeletingSection(true);
    try {
      await deleteSection(deleteSectionConfirm.id);
      setDeleteSectionConfirm(null);
      setLoading(true);
      await fetchOrganizations();
      setLoading(false);
    } catch {
      alert("Failed to delete section. Please try again.");
      setDeletingSection(false);
    }
  }

  async function confirmEditSection() {
    if (!editSectionConfirm) return;
    setEditSection(editSectionConfirm);
    setEditSectionConfirm(null);
  }

  const handleSwitchOrganization = (orgId: number) => {
    setSelectedOrgId(orgId);
    const selected = organizations.find((o) => o.id === orgId);
    setOrganization(selected || null);
  };

  const handleDelete = async () => {
    if (!organization) return;
    setDeleting(true);
    try {
      await deleteOrganization(organization.id);
      setOrganization(null);
      setShowDeleteConfirm(false);
    } catch (err) {
      console.error("Failed to delete organization:", err);
    } finally {
      setDeleting(false);
    }
  };

  // Filter out fulfilled needs from sections for display
  const sectionsWithUnfulfilledNeeds =
    organization?.sections?.map((section) => ({
      ...section,
      needs:
        section.needs?.filter(
          (need) => need.quantity_received < need.quantity_required,
        ) || [],
    })) || [];

  if (authLoading || !authorized || loading) return <PageLoading />;

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-8">
        <div className="flex-1">
          <h1 className="text-3xl font-bold text-gray-900">
            {user?.role === "ADMIN" ? "Organizations" : "Organization"}
          </h1>
          <p className="text-gray-500 mt-1">
            {user?.role === "ADMIN"
              ? `View all organizations (Total: ${organizations.length})`
              : "View and manage the organization"}
          </p>

          {/* Organization Selector for ADMIN */}
          {user?.role === "ADMIN" && organizations.length > 1 && (
            <div className="mt-4 max-w-xs">
              <label
                htmlFor="org-selector"
                className="block text-sm font-medium text-gray-700 mb-2"
              >
                Select Organization:
              </label>
              <select
                id="org-selector"
                value={selectedOrgId || ""}
                onChange={(e) =>
                  handleSwitchOrganization(Number(e.target.value))
                }
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              >
                {organizations.map((org) => (
                  <option key={org.id} value={org.id}>
                    {org.name}
                  </option>
                ))}
              </select>
            </div>
          )}
        </div>

        {/* Action Buttons */}
        {organization && user?.role === "ORG_ADMIN" && (
          <div className="flex items-center gap-3">
            <Link
              href={`/organizations/${organization.id}/edit`}
              className="inline-flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
            >
              <svg
                className="w-4 h-4"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"
                />
              </svg>
              Edit Organization
            </Link>
            <button
              onClick={() => setShowDeleteConfirm(true)}
              className="inline-flex items-center gap-2 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors"
            >
              <svg
                className="w-4 h-4"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"
                />
              </svg>
              Delete Organization
            </button>
          </div>
        )}
      </div>

      {/* Content */}
      {organization ? (
        <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-8 transition-all">
          {/* Header with Icon and Basic Info */}
          <div className="flex items-start gap-4 mb-6 justify-between">
            <div className="flex items-start gap-4 flex-1">
              <div className="w-14 h-14 bg-blue-100 rounded-xl flex items-center justify-center flex-shrink-0">
                <svg
                  className="w-7 h-7 text-blue-600"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"
                  />
                </svg>
              </div>
              <div className="flex-1">
                <h2 className="text-2xl font-bold text-gray-900 mb-2">
                  {organization.name}
                </h2>
                <div className="flex flex-wrap gap-3">
                  {organization.org_type && (
                    <span className="inline-flex items-center gap-1 px-3 py-1 bg-blue-50 text-blue-700 text-sm rounded-full">
                      {organization.org_type}
                    </span>
                  )}
                  {organization.established_year && (
                    <span className="text-sm text-gray-500">
                      Est: {organization.established_year}
                    </span>
                  )}
                </div>
              </div>
            </div>
            {user?.role === "ADMIN" && (
              <button
                onClick={() => setIsOrgExpanded(!isOrgExpanded)}
                className="p-2 hover:bg-gray-100 rounded-lg transition-colors flex-shrink-0"
                title={isOrgExpanded ? "Minimize" : "Expand"}
              >
                <svg
                  className={`w-5 h-5 text-gray-600 transition-transform ${
                    isOrgExpanded ? "rotate-180" : ""
                  }`}
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M19 14l-7 7m0 0l-7-7"
                  />
                </svg>
              </button>
            )}
          </div>

          {/* Core Information Grid - Collapsible */}
          {isOrgExpanded && (
            <>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6 pb-6 border-b border-gray-100">
                {/* Registration & Location */}
                <div>
                  <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-2">
                    Registration
                  </h3>
                  <p className="text-gray-900 font-medium">
                    {organization.registration_number}
                  </p>
                </div>
                <div>
                  <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-2">
                    District
                  </h3>
                  <p className="text-gray-900 font-medium">
                    {organization.district}
                  </p>
                </div>

                {/* Address */}
                {organization.address && (
                  <div className="md:col-span-2">
                    <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-2">
                      Address
                    </h3>
                    <p className="text-gray-900">{organization.address}</p>
                  </div>
                )}
              </div>

              {/* Contact Information Grid */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6 pb-6 border-b border-gray-100">
                {organization.phone && (
                  <div>
                    <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-2">
                      Phone
                    </h3>
                    <a
                      href={`tel:${organization.phone}`}
                      onClick={(e) => e.stopPropagation()}
                      className="text-blue-600 hover:text-blue-700 font-medium"
                    >
                      {organization.phone}
                    </a>
                  </div>
                )}
                {organization.email_contact && (
                  <div>
                    <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-2">
                      Email
                    </h3>
                    <a
                      href={`mailto:${organization.email_contact}`}
                      onClick={(e) => e.stopPropagation()}
                      className="text-blue-600 hover:text-blue-700 font-medium"
                    >
                      {organization.email_contact}
                    </a>
                  </div>
                )}
                {organization.website && (
                  <div>
                    <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-2">
                      Website
                    </h3>
                    <a
                      href={organization.website}
                      target="_blank"
                      rel="noopener noreferrer"
                      onClick={(e) => e.stopPropagation()}
                      className="text-blue-600 hover:text-blue-700 font-medium truncate"
                    >
                      {organization.website}
                    </a>
                  </div>
                )}
              </div>

              {/* Description */}
              {organization.description && (
                <div className="mb-6 pb-6 border-b border-gray-100">
                  <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-2">
                    About
                  </h3>
                  <p className="text-gray-700 leading-relaxed text-sm">
                    {organization.description}
                  </p>
                </div>
              )}

              {/* Statistics */}
              <div className="grid grid-cols-3 gap-4">
                <div className="text-center p-3 bg-gray-50 rounded-lg">
                  <p className="text-2xl font-bold text-gray-900">
                    {organization.sections?.length || 0}
                  </p>
                  <p className="text-xs text-gray-500">Sections</p>
                </div>
                <div className="text-center p-3 bg-gray-50 rounded-lg">
                  <p className="text-2xl font-bold text-gray-900">
                    {sectionsWithUnfulfilledNeeds?.reduce(
                      (a, s) => a + (s.needs?.length || 0),
                      0,
                    ) || 0}
                  </p>
                  <p className="text-xs text-gray-500">Total Needs</p>
                </div>
                <div className="text-center p-3 bg-red-50 rounded-lg">
                  <p className="text-2xl font-bold text-red-600">
                    {sectionsWithUnfulfilledNeeds?.reduce(
                      (a, s) =>
                        a +
                        (s.needs?.filter((n) => n.priority === "CRITICAL")
                          .length || 0),
                      0,
                    ) || 0}
                  </p>
                  <p className="text-xs text-gray-500">Critical</p>
                </div>
              </div>
            </>
          )}

          {/* Sections & Needs */}
          <div className="mt-8 pt-8 border-t border-gray-100">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-bold text-gray-900">
                Sections & Needs
              </h2>
              {user?.role === "ORG_ADMIN" && (
                <button
                  onClick={() => setShowAddSection(true)}
                  className="inline-flex items-center gap-2 px-4 py-2 text-sm font-medium text-blue-600 bg-blue-50 rounded-lg hover:bg-blue-100 transition-colors"
                >
                  <svg
                    className="w-4 h-4"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M12 4v16m8-8H4"
                    />
                  </svg>
                  Add Section
                </button>
              )}
            </div>

            {organization.sections && organization.sections.length > 0 ? (
              <div className="space-y-4">
                {sectionsWithUnfulfilledNeeds.map((section, index) => (
                  <SectionAccordion
                    key={section.id}
                    section={section}
                    defaultOpen={index === 0}
                    onAddNeed={
                      user?.role === "ORG_ADMIN"
                        ? () =>
                            setAddNeedForSection({
                              orgId: organization.id,
                              sectionId: section.id,
                            })
                        : undefined
                    }
                    onEditNeed={
                      user?.role === "ORG_ADMIN"
                        ? (needId) => {
                            const n = findNeedById(needId);
                            if (n) setEditNeed(n);
                          }
                        : undefined
                    }
                    onDeleteNeed={
                      user?.role === "ORG_ADMIN"
                        ? (needId) => {
                            const n = findNeedById(needId);
                            if (n) setDeleteNeedConfirm(n);
                          }
                        : undefined
                    }
                    onEditSection={
                      user?.role === "ORG_ADMIN"
                        ? () => setEditSectionConfirm(section)
                        : undefined
                    }
                    onDeleteSection={
                      user?.role === "ORG_ADMIN"
                        ? async () => {
                            setDeleteSectionConfirm(section);
                          }
                        : undefined
                    }
                  />
                ))}
              </div>
            ) : (
              <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-12 text-center">
                <svg
                  className="w-16 h-16 text-gray-300 mx-auto mb-4"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10"
                  />
                </svg>
                <h3 className="text-lg font-medium text-gray-900 mb-2">
                  No Sections Yet
                </h3>
                {(user?.role === "ADMIN" || user?.role === "ORG_ADMIN") && (
                  <p className="text-gray-500">
                    No sections have been added to this organization yet
                  </p>
                )}
              </div>
            )}
          </div>
        </div>
      ) : user?.role === "ORG_ADMIN" ? (
        <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-16 text-center">
          <div className="w-16 h-16 bg-gray-100 rounded-xl flex items-center justify-center mx-auto mb-4">
            <svg
              className="w-8 h-8 text-gray-400"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"
              />
            </svg>
          </div>
          <h3 className="text-lg font-medium text-gray-900 mb-2">
            No Organization Yet
          </h3>
          <p className="text-gray-500 mb-6">
            No organization has been registered in the system.
          </p>
          <Link
            href="/organizations/new"
            className="inline-flex items-center gap-2 px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
          >
            <svg
              className="w-4 h-4"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M12 4v16m8-8H4"
              />
            </svg>
            Add Organization
          </Link>
        </div>
      ) : (
        <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-16 text-center">
          <div className="w-16 h-16 bg-gray-100 rounded-xl flex items-center justify-center mx-auto mb-4">
            <svg
              className="w-8 h-8 text-gray-400"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"
              />
            </svg>
          </div>
          <h3 className="text-lg font-medium text-gray-900 mb-2">
            Organizations
          </h3>
          <p className="text-gray-500">View all organizations in the system.</p>
        </div>
      )}

      {/* Add Section Modal */}
      {showAddSection && organization && (
        <AddSectionModal
          organizationId={organization.id}
          onClose={() => setShowAddSection(false)}
          onSuccess={() => {
            setShowAddSection(false);
            setLoading(true);
            fetchOrganizations();
          }}
        />
      )}

      {/* Manual Need Entry Form (for adding needs) */}
      {addNeedForSection && organization && (
        <ManualNeedEntryForm
          initialOrgId={organization.id}
          initialSectionId={addNeedForSection.sectionId}
          onClose={() => setAddNeedForSection(null)}
          onSuccess={() => {
            setAddNeedForSection(null);
            setLoading(true);
            fetchOrganizations();
          }}
        />
      )}

      {/* Edit Need Modal */}
      {editNeed && (
        <EditNeedModal
          need={editNeed}
          onClose={() => setEditNeed(null)}
          onSuccess={() => {
            setEditNeed(null);
            setLoading(true);
            fetchOrganizations();
          }}
        />
      )}

      {/* Delete Need Confirmation */}
      {deleteNeedConfirm && (
        <div className="fixed inset-0 z-50 overflow-y-auto">
          <div className="flex min-h-full items-center justify-center p-4">
            <div
              className="fixed inset-0 bg-black/30"
              onClick={() => setDeleteNeedConfirm(null)}
            />
            <div className="relative bg-white rounded-xl shadow-xl w-full max-w-md p-6">
              <h3 className="text-lg font-semibold text-gray-900 mb-2">
                Delete Need
              </h3>
              <p className="text-gray-600 mb-6">
                Are you sure you want to delete "
                <strong>{deleteNeedConfirm.name}</strong>"?
              </p>
              <div className="flex justify-end gap-3">
                <button
                  onClick={() => setDeleteNeedConfirm(null)}
                  className="px-4 py-2 text-sm font-medium text-gray-700 bg-gray-100 rounded-lg hover:bg-gray-200 transition-colors"
                >
                  Cancel
                </button>
                <button
                  onClick={() => handleDeleteNeed(deleteNeedConfirm.id)}
                  disabled={deletingNeed}
                  className="px-4 py-2 text-sm font-medium text-white bg-red-600 rounded-lg hover:bg-red-700 disabled:opacity-50 transition-colors"
                >
                  {deletingNeed ? "Deleting..." : "Delete"}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Edit Section Modal */}
      {editSection && organization && (
        <EditSectionModal
          section={editSection}
          onClose={() => setEditSection(null)}
          onSuccess={() => {
            setEditSection(null);
            setLoading(true);
            fetchOrganizations();
          }}
        />
      )}

      {/* Delete Confirmation Modal */}
      {showDeleteConfirm && (
        <div className="fixed inset-0 z-50 overflow-y-auto">
          <div className="flex min-h-full items-center justify-center p-4">
            <div
              className="fixed inset-0 bg-black/30"
              onClick={() => setShowDeleteConfirm(false)}
            />
            <div className="relative bg-white rounded-xl shadow-xl w-full max-w-md p-6">
              <div className="flex items-center gap-3 mb-4">
                <div className="w-10 h-10 bg-red-100 rounded-full flex items-center justify-center flex-shrink-0">
                  <svg
                    className="w-5 h-5 text-red-600"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"
                    />
                  </svg>
                </div>
                <div>
                  <h3 className="text-lg font-semibold text-gray-900">
                    Delete Organization
                  </h3>
                  <p className="text-sm text-gray-500">
                    This action cannot be undone
                  </p>
                </div>
              </div>
              <p className="text-gray-700 mb-6">
                Are you sure you want to delete{" "}
                <strong>{organization?.name}</strong>? All sections and needs
                will be permanently removed.
              </p>
              <div className="flex justify-end gap-3">
                <button
                  onClick={() => setShowDeleteConfirm(false)}
                  className="px-4 py-2 text-sm font-medium text-gray-700 bg-gray-100 rounded-lg hover:bg-gray-200 transition-colors"
                >
                  Cancel
                </button>
                <button
                  onClick={handleDelete}
                  disabled={deleting}
                  className="px-4 py-2 text-sm font-medium text-white bg-red-600 rounded-lg hover:bg-red-700 disabled:opacity-50 transition-colors"
                >
                  {deleting ? "Deleting..." : "Delete"}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Delete Section Confirmation Modal */}
      {deleteSectionConfirm && (
        <div className="fixed inset-0 z-50 overflow-y-auto">
          <div className="flex min-h-full items-center justify-center p-4">
            <div
              className="fixed inset-0 bg-black/30"
              onClick={() => setDeleteSectionConfirm(null)}
            />
            <div className="relative bg-white rounded-xl shadow-xl w-full max-w-md p-6">
              <div className="flex items-center gap-3 mb-4">
                <div className="w-10 h-10 bg-red-100 rounded-full flex items-center justify-center flex-shrink-0">
                  <svg
                    className="w-5 h-5 text-red-600"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"
                    />
                  </svg>
                </div>
                <div>
                  <h3 className="text-lg font-semibold text-gray-900">
                    Delete Section
                  </h3>
                  <p className="text-sm text-gray-500">
                    This action cannot be undone
                  </p>
                </div>
              </div>
              <p className="text-gray-700 mb-6">
                Are you sure you want to delete{" "}
                <strong>{deleteSectionConfirm.name}</strong>? All needs in this
                section will be permanently removed.
              </p>
              <div className="flex justify-end gap-3">
                <button
                  onClick={() => setDeleteSectionConfirm(null)}
                  className="px-4 py-2 text-sm font-medium text-gray-700 bg-gray-100 rounded-lg hover:bg-gray-200 transition-colors"
                >
                  Cancel
                </button>
                <button
                  onClick={confirmDeleteSection}
                  disabled={deletingSection}
                  className="px-4 py-2 text-sm font-medium text-white bg-red-600 rounded-lg hover:bg-red-700 disabled:opacity-50 transition-colors"
                >
                  {deletingSection ? "Deleting..." : "Delete"}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Edit Section Confirmation Modal */}
      {editSectionConfirm && (
        <div className="fixed inset-0 z-50 overflow-y-auto">
          <div className="flex min-h-full items-center justify-center p-4">
            <div
              className="fixed inset-0 bg-black/30"
              onClick={() => setEditSectionConfirm(null)}
            />
            <div className="relative bg-white rounded-xl shadow-xl w-full max-w-md p-6">
              <div className="flex items-center gap-3 mb-4">
                <div className="w-10 h-10 bg-blue-100 rounded-full flex items-center justify-center flex-shrink-0">
                  <svg
                    className="w-5 h-5 text-blue-600"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"
                    />
                  </svg>
                </div>
                <div>
                  <h3 className="text-lg font-semibold text-gray-900">
                    Edit Section
                  </h3>
                  <p className="text-sm text-gray-500">
                    Modify section details
                  </p>
                </div>
              </div>
              <p className="text-gray-700 mb-6">
                Edit the section <strong>{editSectionConfirm.name}</strong>? You
                will be able to update the section name and other details.
              </p>
              <div className="flex justify-end gap-3">
                <button
                  onClick={() => setEditSectionConfirm(null)}
                  className="px-4 py-2 text-sm font-medium text-gray-700 bg-gray-100 rounded-lg hover:bg-gray-200 transition-colors"
                >
                  Cancel
                </button>
                <button
                  onClick={confirmEditSection}
                  className="px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded-lg hover:bg-blue-700 transition-colors"
                >
                  Edit
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useSearchParams } from "next/navigation";
import Link from "next/link";
import { search, SearchResult, Organization, NeedItem } from "@/lib/api";
import NeedCard from "@/components/NeedCard";
import OrganizationCard from "@/components/OrganizationCard";
import LoadingSpinner from "@/components/LoadingSpinner";
import { Search, ChevronRight } from "lucide-react";

export default function SearchContent() {
  const searchParams = useSearchParams();
  const initialQuery = searchParams.get("q") || "";
  const initialType = (searchParams.get("type") as any) || "all";

  const [query, setQuery] = useState(initialQuery);
  const [searchType, setSearchType] = useState(initialType);
  const [priority, setPriority] = useState("");
  const [results, setResults] = useState<SearchResult | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const performSearch = async () => {
    if (!query.trim() || query.length < 2) {
      setError("Search query must be at least 2 characters");
      return;
    }

    setLoading(true);
    setError("");

    try {
      const data = await search(query, searchType, {
        priority: priority || undefined,
        limit: 50,
        excludeFulfilled: true,
      });
      setResults(data);
    } catch (err: any) {
      setError(err.message || "Search failed");
    } finally {
      setLoading(false);
    }
  };

  // Auto-search when query changes from URL params
  useEffect(() => {
    if (initialQuery) {
      performSearch();
    }
  }, []);

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    performSearch();
  };

  const handleKeyPress = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Enter") {
      performSearch();
    }
  };

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Search Header */}
      <div className="bg-white border-b border-gray-200">
        <div className="max-w-5xl mx-auto px-4 py-8">
          <h1 className="text-3xl font-bold text-gray-900 mb-6">Search</h1>

          {/* Search Form */}
          <form onSubmit={handleSearch} className="space-y-4">
            {/* Search Input */}
            <div className="relative">
              <Search
                className="absolute left-3 top-3 text-gray-400"
                size={20}
              />
              <input
                type="text"
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                onKeyPress={handleKeyPress}
                placeholder="Search organizations, hospitals, needs..."
                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              />
            </div>

            {/* Filters Row */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              {/* Search Type */}
              <div>
                <label
                  htmlFor="search-type"
                  className="block text-sm font-medium text-gray-700 mb-1"
                >
                  Search In
                </label>
                <select
                  id="search-type"
                  value={searchType}
                  onChange={(e) => setSearchType(e.target.value as any)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                >
                  <option value="all">All</option>
                  <option value="organization">Organizations Only</option>
                  <option value="need">Needs Only</option>
                </select>
              </div>

              {/* Priority Filter (for needs) */}
              {searchType !== "organization" && (
                <div>
                  <label
                    htmlFor="priority"
                    className="block text-sm font-medium text-gray-700 mb-1"
                  >
                    Priority
                  </label>
                  <select
                    id="priority"
                    value={priority}
                    onChange={(e) => setPriority(e.target.value)}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                  >
                    <option value="">All Priorities</option>
                    <option value="CRITICAL">Critical</option>
                    <option value="ESSENTIAL">Essential</option>
                    <option value="NICE">Nice to Have</option>
                  </select>
                </div>
              )}

              {/* Search Button */}
              <div className="flex items-end">
                <button
                  type="submit"
                  disabled={loading}
                  className="w-full px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:bg-gray-400 font-medium"
                >
                  {loading ? "Searching..." : "Search"}
                </button>
              </div>
            </div>
          </form>
        </div>
      </div>

      {/* Results Section */}
      <div className="max-w-5xl mx-auto px-4 py-8">
        {error && (
          <div className="bg-red-50 border border-red-200 text-red-800 px-4 py-3 rounded-lg mb-6">
            {error}
          </div>
        )}

        {loading && (
          <div className="flex justify-center py-12">
            <LoadingSpinner />
          </div>
        )}

        {results && !loading && (
          <>
            {/* Summary */}
            <div className="mb-8">
              <p className="text-gray-600">
                Found{" "}
                <span className="font-semibold text-gray-900">
                  {results.total}
                </span>{" "}
                result
                {results.total !== 1 ? "s" : ""} for "
                <span className="font-semibold">{query}</span>"
              </p>
            </div>

            {/* Organizations Results */}
            {results.organizations.length > 0 && (
              <div className="mb-12">
                <h2 className="text-2xl font-bold text-gray-900 mb-6 flex items-center">
                  Organizations
                  <span className="ml-2 px-3 py-1 bg-blue-100 text-blue-800 text-sm font-semibold rounded-full">
                    {results.organizations.length}
                  </span>
                </h2>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  {results.organizations.map((org) => (
                    <OrganizationCard key={org.id} organization={org} />
                  ))}
                </div>
              </div>
            )}

            {/* Needs Results */}
            {results.needs.length > 0 && (
              <div>
                <h2 className="text-2xl font-bold text-gray-900 mb-6 flex items-center">
                  Needs
                  <span className="ml-2 px-3 py-1 bg-green-100 text-green-800 text-sm font-semibold rounded-full">
                    {results.needs.length}
                  </span>
                </h2>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {results.needs.map((need) => (
                    <NeedCard
                      key={need.id}
                      need={need}
                      organizationName={
                        need.section_detail?.organization_name || "Unknown"
                      }
                    />
                  ))}
                </div>
              </div>
            )}

            {/* No Results */}
            {results.organizations.length === 0 &&
              results.needs.length === 0 && (
                <div className="text-center py-12">
                  <Search className="mx-auto text-gray-400 mb-4" size={48} />
                  <p className="text-gray-600 text-lg">
                    No results found for "
                    <span className="font-semibold">{query}</span>"
                  </p>
                  <p className="text-gray-500 mt-2">
                    Try searching with different keywords
                  </p>
                </div>
              )}
          </>
        )}

        {/* Initial State */}
        {!results && !loading && (
          <div className="text-center py-12">
            <Search className="mx-auto text-gray-400 mb-4" size={48} />
            <p className="text-gray-600 text-lg">
              Enter a search query to get started
            </p>
            <p className="text-gray-500 mt-2">
              Search for organizations, hospitals, equipment, and more
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { Organization } from "@/lib/api";
import "leaflet/dist/leaflet.css";

let L: any = null;

const initLeaflet = async () => {
  if (!L) {
    L = await import("leaflet");
  }
  return L;
};

interface AdvancedSriLankaMapProps {
  organizations?: Organization[];
}

const districtCoordinates: Record<string, [number, number]> = {
  colombo: [6.9271, 79.8612],
  gampaha: [7.0917, 79.9999],
  kalutara: [6.5854, 79.9607],
  kandy: [7.2906, 80.6337],
  matale: [7.4675, 80.6234],
  nuwaraeliya: [6.9497, 80.7891],
  nuwaraeliyaalt: [6.9497, 80.7891],
  galle: [6.0535, 80.221],
  matara: [5.9549, 80.555],
  hambantota: [6.1241, 81.1185],
  jaffna: [9.6615, 80.0255],
  kilinochchi: [9.3803, 80.377],
  mannar: [8.977, 79.904],
  mullaitivu: [9.2673, 80.8135],
  vavuniya: [8.7514, 80.4971],
  batticaloa: [7.717, 81.7001],
  ampara: [7.2917, 81.6747],
  trincomalee: [8.5874, 81.2152],
  kurunegala: [7.4863, 80.3647],
  puttalam: [8.033, 79.8262],
  anuradhapura: [8.3114, 80.4037],
  polonnaruwa: [7.94, 81.0188],
  badulla: [6.9934, 81.055],
  monaragala: [6.8721, 81.3507],
  ratnapura: [6.6828, 80.3992],
  kegalle: [7.2513, 80.3464],
};

const normalizeDistrictKey = (district: string): string =>
  district.toLowerCase().replace(/[^a-z]/g, "");

export default function AdvancedSriLankaMap({ organizations = [] }: AdvancedSriLankaMapProps) {
  const mapContainer = useRef<HTMLDivElement>(null);
  const map = useRef<any>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [mapError, setMapError] = useState<string | null>(null);
  const [mappedOrganizations, setMappedOrganizations] = useState(0);

  useEffect(() => {
    let isCancelled = false;

    const initMap = async () => {
      if (!mapContainer.current || map.current) {
        return;
      }

      const container = mapContainer.current;

      try {
        const LeafletLib = await initLeaflet();

        if (isCancelled || map.current) {
          return;
        }

        // In React Strict Mode, effects can run twice in development.
        // Reset previous Leaflet binding on the same DOM node before creating a new map.
        if ((container as any)._leaflet_id) {
          (container as any)._leaflet_id = undefined;
          container.innerHTML = "";
        }

        // Initialize map
        map.current = LeafletLib.map(container, {
          preferCanvas: true,
          attributionControl: true,
          zoomControl: true,
        }).setView([7.8731, 80.7718], 8);

        // Add OpenStreetMap tile layer (faster and more reliable)
        LeafletLib.tileLayer(
          "https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",
          {
            attribution: "&copy; OpenStreetMap contributors",
            maxZoom: 19,
            minZoom: 6,
          }
        ).addTo(map.current);

        // Fix Leaflet marker icons
        LeafletLib.Icon.Default.mergeOptions({
          iconRetinaUrl: "https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-icon-2x.png",
          iconUrl: "https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-icon.png",
          shadowUrl: "https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-shadow.png",
        });

        const organizationsWithCoordinates = organizations
          .map((organization) => {
            const districtKey = normalizeDistrictKey(organization.district || "");
            const location = districtCoordinates[districtKey];
            if (!location) {
              return null;
            }

            return {
              organization,
              lat: location[0],
              lng: location[1],
            };
          })
          .filter((entry): entry is { organization: Organization; lat: number; lng: number } => entry !== null);

        // Add markers only for registered organizations
        organizationsWithCoordinates.forEach((entry) => {
          const marker = LeafletLib.marker([entry.lat, entry.lng], {
            title: entry.organization.name,
          }).addTo(map.current);

          const popupContent = `
            <div style="padding: 10px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; width: 200px;">
              <h3 style="margin: 0 0 8px 0; font-weight: bold; color: #1e40af; font-size: 13px;">${entry.organization.name}</h3>
              <hr style="margin: 8px 0; border: none; border-top: 1px solid #e5e7eb;">
              <div style="font-size: 12px; color: #374151; line-height: 1.6;">
                <p style="margin: 4px 0;"><strong>District:</strong> ${entry.organization.district}</p>
                <p style="margin: 4px 0;"><strong>Type:</strong> ${entry.organization.org_type || "OTHER"}</p>
                <p style="margin: 4px 0;"><strong>Status:</strong> <span style="color: #16a34a; font-weight: 600;">Registered</span></p>
              </div>
            </div>
          `;

          marker.bindPopup(popupContent, { maxWidth: 250, maxHeight: 200 });
          marker.on('click', () => marker.openPopup());
        });

        if (organizationsWithCoordinates.length > 0) {
          const bounds = LeafletLib.latLngBounds(
            organizationsWithCoordinates.map((entry) => [entry.lat, entry.lng]),
          );
          map.current.fitBounds(bounds, { padding: [30, 30], maxZoom: 9 });
        }

        setMappedOrganizations(organizationsWithCoordinates.length);

        setMapError(null);
      } catch (error) {
        console.error("Map initialization error:", error);
        setMapError("Map failed to load. Please refresh the page.");
      } finally {
        if (!isCancelled) {
          setIsLoading(false);
        }
      }
    };

    initMap();

    return () => {
      isCancelled = true;
      if (map.current) {
        map.current.off();
        map.current.remove();
        map.current = null;
      }
    };
  }, []);

  return (
    <div className="w-full h-full rounded-xl overflow-hidden shadow-2xl relative">
      <div ref={mapContainer} style={{ height: "100%", width: "100%" }} />

      {isLoading && (
        <div className="absolute inset-0 bg-gradient-to-br from-blue-500 to-indigo-700 flex items-center justify-center z-50">
          <div className="text-white text-center">
            <div className="animate-spin rounded-full h-10 w-10 border-4 border-blue-200 border-t-white mx-auto mb-3"></div>
            <p className="text-sm font-medium">Loading Sri Lanka Map...</p>
            <p className="text-xs text-blue-100 mt-1">Initializing 9 hospital locations</p>
          </div>
        </div>
      )}

      {mapError && !isLoading && (
        <div className="absolute inset-0 bg-red-50/95 flex items-center justify-center z-50">
          <div className="text-center px-4">
            <p className="text-sm font-semibold text-red-700">{mapError}</p>
            <p className="text-xs text-red-600 mt-1">Check network access to OpenStreetMap tiles.</p>
          </div>
        </div>
      )}

      {/* Map Legend Overlay */}
      <div className="absolute top-4 right-4 bg-white rounded-lg shadow-lg p-4 z-40 max-w-xs pointer-events-auto hover:shadow-xl transition-shadow cursor-default">
        <div className="flex items-center gap-2 mb-3">
          <span className="w-3 h-3 bg-gradient-to-r from-green-400 to-emerald-500 rounded-full animate-pulse"></span>
          <span className="text-sm font-bold text-gray-900">ORGANIZATION MAP</span>
        </div>
        <div className="space-y-2 text-xs text-gray-700 font-medium">
          <p>{mappedOrganizations} registered organizations</p>
          <p>Click markers for details</p>
          <p>Drag to pan, scroll to zoom</p>
        </div>
      </div>

      {mappedOrganizations === 0 && !isLoading && !mapError && (
        <div className="absolute bottom-4 left-4 bg-white/95 rounded-lg shadow-lg px-4 py-2 z-40 backdrop-blur-sm">
          <span className="text-xs font-semibold text-gray-900">
            No registered organizations yet. Markers will appear after registration.
          </span>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useRef } from "react";
import Link from "next/link";
import { NeedItem, Donation } from "@/lib/api";
import { Loader2, X } from "lucide-react";

export interface DonationFormData {
  quantity: number;
  message: string;
  estimatedDeliveryDate: string;
  donorType: "private" | "government";
  donorName: string;
  donorEmail: string;
  donorPhone: string;
  donorOrganization: string;
  donorAddress: string;
  donorContact: string;
  governmentDepartment: string;
  governmentProgram: string;
  governmentOfficerName: string;
  governmentOfficerDesignation: string;
  governmentOfficerContact: string;
}

interface DonateModalProps {
  needItem: NeedItem;
  isOpen: boolean;
  onClose: () => void;
  onSuccess: () => void;
}

export default function DonateModal({
  needItem,
  isOpen,
  onClose,
  onSuccess,
}: DonateModalProps) {
  const [quantity, setQuantity] = useState<number>(1);
  const [message, setMessage] = useState("");
  const [estimatedDeliveryDate, setEstimatedDeliveryDate] = useState("");
  const [donorType, setDonorType] = useState<"private" | "government">(
    "private",
  );

  // Private donor fields
  const [donorName, setDonorName] = useState("");
  const [donorEmail, setDonorEmail] = useState("");
  const [donorPhone, setDonorPhone] = useState("");
  const [donorOrganization, setDonorOrganization] = useState("");
  const [donorAddress, setDonorAddress] = useState("");
  const [donorContact, setDonorContact] = useState("");

  // Government donor fields
  const [governmentDepartment, setGovernmentDepartment] = useState("");
  const [governmentProgram, setGovernmentProgram] = useState("");
  const [governmentOfficerName, setGovernmentOfficerName] = useState("");
  const [governmentOfficerDesignation, setGovernmentOfficerDesignation] =
    useState("");
  const [governmentOfficerContact, setGovernmentOfficerContact] = useState("");

  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  if (!isOpen) return null;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError("");

    // Check if user is authenticated
    const token = localStorage.getItem("accessToken");
    if (!token) {
      setError(
        "Please sign in to make a donation. Redirecting to login page...",
      );
      setTimeout(() => {
        window.location.href = "/login";
      }, 2000);
      setIsLoading(false);
      return;
    }

    try {
      const { createDonation } = await import("@/lib/api");

      const donationData: any = {
        need_item: needItem.id,
        quantity: quantity,
        status: "PENDING",
        message: message,
        estimated_delivery_date: estimatedDeliveryDate || null,
        donor_type: donorType,
      };

      if (donorType === "private") {
        donationData.donor_name = donorName;
        donationData.donor_email = donorEmail;
        donationData.donor_phone = donorPhone;
        donationData.donor_organization = donorOrganization;
        donationData.donor_address = donorAddress;
        donationData.donor_contact = donorContact;
      } else {
        donationData.government_department = governmentDepartment;
        donationData.government_program = governmentProgram;
        donationData.government_officer_name = governmentOfficerName;
        donationData.government_officer_designation =
          governmentOfficerDesignation;
        donationData.government_officer_contact = governmentOfficerContact;
      }

      await createDonation(donationData);

      // Show success message for 3 seconds
      setSuccess(true);
      setIsLoading(false);

      // Close modal after 3 seconds
      setTimeout(() => {
        // Reset form
        setQuantity(1);
        setMessage("");
        setEstimatedDeliveryDate("");
        setDonorType("private");
        setDonorName("");
        setDonorEmail("");
        setDonorPhone("");
        setDonorOrganization("");
        setDonorAddress("");
        setDonorContact("");
        setSuccess(false);
        onSuccess();
        onClose();
      }, 3000);
    } catch (err: any) {
      setIsLoading(false);
      if (err.message && err.message.includes("401")) {
        setError("Your session has expired. Please sign in again.");
      } else if (err.message && err.message.includes("credentials")) {
        setError("Authentication failed. Please sign in again.");
      } else {
        setError(err.message || "Failed to create donation");
      }
    }
  };

  return (
    <div className="fixed inset-0 z-50 bg-transparent flex items-center justify-center p-4">
      <div className="bg-white rounded-lg shadow-lg max-w-2xl w-full max-h-[90vh] overflow-y-auto">
        {/* Header */}
        <div className="sticky top-0 bg-white border-b border-gray-200 p-6 flex items-center justify-between">
          <div>
            <h2 className="text-2xl font-bold text-gray-900">
              Make a Donation
            </h2>
            <p className="text-gray-600 mt-1">{needItem.name}</p>
          </div>
          <button
            onClick={onClose}
            aria-label="Close donation modal"
            className="text-gray-400 hover:text-gray-600"
          >
            <X size={24} />
          </button>
        </div>

        {/* Content */}
        <form onSubmit={handleSubmit} className="p-6 space-y-6">
          {success ? (
            <div className="flex flex-col items-center justify-center py-12 text-center">
              <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mb-4">
                <div className="text-4xl text-green-600">✓</div>
              </div>
              <h3 className="text-2xl font-bold text-gray-900 mb-2">
                Donation Submitted Successfully!
              </h3>
              <p className="text-gray-600 mb-6">
                Thank you for your generous donation. The organization will
                review and confirm your donation shortly. This modal will close
                automatically in a moment.
              </p>
              <div className="w-full bg-gray-100 rounded-full h-1">
                <div className="w-full bg-green-600 h-1 rounded-full animate-pulse"></div>
              </div>
            </div>
          ) : (
            <>
              {error && (
                <div className="bg-red-50 border border-red-200 text-red-800 px-4 py-3 rounded">
                  <p>{error}</p>
                  {error.includes("sign in") && (
                    <Link href="/login">
                      <button
                        type="button"
                        className="mt-2 text-blue-600 hover:text-blue-800 font-semibold underline"
                      >
                        Go to Sign In →
                      </button>
                    </Link>
                  )}
                </div>
              )}

              {/* Quantity Section */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Quantity to Donate ({needItem.unit})
                </label>
                <div className="flex items-center gap-4">
                  <input
                    type="number"
                    min="1"
                    max={needItem.quantity_required}
                    value={quantity}
                    onChange={(e) =>
                      setQuantity(Math.max(1, parseInt(e.target.value) || 1))
                    }
                    aria-label="Quantity to donate"
                    className="flex-1 px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />
                  <span className="text-sm text-gray-600">
                    Max:{" "}
                    {needItem.quantity_required - needItem.quantity_received}
                  </span>
                </div>
              </div>

              {/* Message */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Message
                </label>
                <textarea
                  value={message}
                  onChange={(e) => setMessage(e.target.value)}
                  placeholder="Add a message with your donation..."
                  aria-label="Donation message"
                  rows={3}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>

              {/* Delivery Date */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Estimated Delivery Date
                </label>
                <input
                  type="date"
                  value={estimatedDeliveryDate}
                  onChange={(e) => setEstimatedDeliveryDate(e.target.value)}
                  aria-label="Estimated delivery date"
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>

              {/* Donor Type */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-3">
                  Donor Type
                </label>
                <div className="flex gap-4">
                  <label className="flex items-center">
                    <input
                      type="radio"
                      value="private"
                      checked={donorType === "private"}
                      onChange={(e) =>
                        setDonorType(e.target.value as "private" | "government")
                      }
                      className="mr-2"
                    />
                    <span>Private Donor</span>
                  </label>
                  <label className="flex items-center">
                    <input
                      type="radio"
                      value="government"
                      checked={donorType === "government"}
                      onChange={(e) =>
                        setDonorType(e.target.value as "private" | "government")
                      }
                      className="mr-2"
                    />
                    <span>Government</span>
                  </label>
                </div>
              </div>

              {/* Conditional Donor Fields */}
              {donorType === "private" ? (
                <div className="space-y-4 bg-blue-50 p-4 rounded-lg">
                  <h3 className="font-semibold text-gray-900">
                    Donor Information
                  </h3>
                  <div className="grid grid-cols-2 gap-4">
                    <input
                      type="text"
                      placeholder="Full Name"
                      value={donorName}
                      onChange={(e) => setDonorName(e.target.value)}
                      className="px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                    <input
                      type="email"
                      placeholder="Email"
                      value={donorEmail}
                      onChange={(e) => setDonorEmail(e.target.value)}
                      className="px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                    <input
                      type="tel"
                      placeholder="Phone"
                      value={donorPhone}
                      onChange={(e) => setDonorPhone(e.target.value)}
                      className="px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                    <input
                      type="text"
                      placeholder="Contact Person"
                      value={donorContact}
                      onChange={(e) => setDonorContact(e.target.value)}
                      className="px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                  </div>
                  <div className="space-y-4">
                    <input
                      type="text"
                      placeholder="Organization"
                      value={donorOrganization}
                      onChange={(e) => setDonorOrganization(e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                    <textarea
                      placeholder="Address"
                      value={donorAddress}
                      onChange={(e) => setDonorAddress(e.target.value)}
                      rows={2}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                  </div>
                </div>
              ) : (
                <div className="space-y-4 bg-green-50 p-4 rounded-lg">
                  <h3 className="font-semibold text-gray-900">
                    Government Information
                  </h3>
                  <div className="grid grid-cols-2 gap-4">
                    <input
                      type="text"
                      placeholder="Department"
                      value={governmentDepartment}
                      onChange={(e) => setGovernmentDepartment(e.target.value)}
                      className="px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                    <input
                      type="text"
                      placeholder="Program"
                      value={governmentProgram}
                      onChange={(e) => setGovernmentProgram(e.target.value)}
                      className="px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                    <input
                      type="text"
                      placeholder="Officer Name"
                      value={governmentOfficerName}
                      onChange={(e) => setGovernmentOfficerName(e.target.value)}
                      className="px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                    <input
                      type="text"
                      placeholder="Officer Designation"
                      value={governmentOfficerDesignation}
                      onChange={(e) =>
                        setGovernmentOfficerDesignation(e.target.value)
                      }
                      className="px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                    <input
                      type="tel"
                      placeholder="Officer Contact"
                      value={governmentOfficerContact}
                      onChange={(e) =>
                        setGovernmentOfficerContact(e.target.value)
                      }
                      className="px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                  </div>
                </div>
              )}

              {/* Footer buttons */}
              <div className="flex gap-3 pt-4 border-t border-gray-200">
                <button
                  type="button"
                  onClick={onClose}
                  className="flex-1 px-4 py-2 border border-gray-300 rounded-lg hover:bg-gray-50 transition"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={isLoading}
                  className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 transition flex items-center justify-center gap-2"
                >
                  {isLoading && <Loader2 size={18} className="animate-spin" />}
                  {isLoading ? "Creating..." : "Donate"}
                </button>
              </div>
            </>
          )}
        </form>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { NeedItem, updateNeed, unitLabels } from "@/lib/api";

interface EditNeedModalProps {
  need: NeedItem;
  onClose: () => void;
  onSuccess: () => void;
}

const priorityConfig = {
  CRITICAL: {
    dot: "bg-red-500",
    ring: "ring-red-300",
    label: "Critical",
    desc: "Urgent — must be addressed immediately",
  },
  ESSENTIAL: {
    dot: "bg-yellow-500",
    ring: "ring-yellow-300",
    label: "Essential",
    desc: "Important but not life-threatening",
  },
  NICE: {
    dot: "bg-green-500",
    ring: "ring-green-300",
    label: "Nice to Have",
    desc: "Helpful but not urgent",
  },
};

export default function EditNeedModal({
  need,
  onClose,
  onSuccess,
}: EditNeedModalProps) {
  const [form, setForm] = useState({
    name: need.name,
    priority: need.priority,
    quantity_required: need.quantity_required,
    quantity_received: need.quantity_received,
    unit: need.unit,
    description: need.description ?? "",
  });
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!form.name.trim()) {
      setError("Need name is required.");
      return;
    }
    if (form.quantity_required < 1) {
      setError("Quantity must be at least 1.");
      return;
    }
    setSubmitting(true);
    setError(null);
    try {
      await updateNeed(need.id, {
        name: form.name.trim(),
        priority: form.priority,
        quantity_required: form.quantity_required,
        quantity_received: form.quantity_received,
        unit: form.unit,
        description: form.description.trim(),
      });
      setSuccess(true);
      setTimeout(() => {
        onSuccess();
        onClose();
      }, 900);
    } catch (err: any) {
      console.error("Error updating need:", err);
      const errorMessage =
        err?.message || "Failed to update. Please try again.";
      setError(errorMessage);
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-end bg-black/40"
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div className="h-full w-full max-w-lg bg-white shadow-2xl flex flex-col overflow-hidden">
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-5 border-b border-gray-100 bg-gradient-to-r from-indigo-600 to-indigo-700">
          <div>
            <h2 className="text-lg font-semibold text-white">Edit Need</h2>
            <p className="text-indigo-200 text-sm mt-0.5">
              Update the details for this need item
            </p>
          </div>
          <button
            type="button"
            onClick={onClose}
            aria-label="Close dialog"
            className="w-8 h-8 flex items-center justify-center rounded-full bg-white/20 hover:bg-white/30 text-white transition-colors"
          >
            <svg
              className="w-4 h-4"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M6 18L18 6M6 6l12 12"
              />
            </svg>
          </button>
        </div>

        {/* Body */}
        <div className="flex-1 overflow-y-auto px-6 py-6">
          {success ? (
            <div className="flex flex-col items-center justify-center h-full gap-4 text-center">
              <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center">
                <svg
                  className="w-8 h-8 text-green-600"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M5 13l4 4L19 7"
                  />
                </svg>
              </div>
              <h3 className="text-xl font-semibold text-gray-900">Updated!</h3>
              <p className="text-gray-500 text-sm">
                Changes saved successfully.
              </p>
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="space-y-5">
              {/* Need Name */}
              <div>
                <label
                  htmlFor="need-name"
                  className="block text-sm font-medium text-gray-700 mb-1.5"
                >
                  Need Item Name <span className="text-red-500">*</span>
                </label>
                <input
                  id="need-name"
                  type="text"
                  value={form.name}
                  onChange={(e) =>
                    setForm((f) => ({ ...f, name: e.target.value }))
                  }
                  required
                  placeholder="Enter need item name"
                  className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 text-gray-900"
                />
              </div>

              {/* Priority */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Priority Level <span className="text-red-500">*</span>
                </label>
                <div className="grid grid-cols-3 gap-2">
                  {(["CRITICAL", "ESSENTIAL", "NICE"] as const).map((p) => {
                    const cfg = priorityConfig[p];
                    const selected = form.priority === p;
                    return (
                      <button
                        key={p}
                        type="button"
                        onClick={() => setForm((f) => ({ ...f, priority: p }))}
                        className={`flex flex-col items-center gap-1.5 p-3 rounded-lg border-2 text-center transition-all ${selected ? `border-current ring-2 ${cfg.ring} bg-gray-50` : "border-gray-200 hover:border-gray-300 bg-white"}`}
                      >
                        <span className={`w-3 h-3 rounded-full ${cfg.dot}`} />
                        <span
                          className={`text-xs font-semibold ${selected ? "text-gray-900" : "text-gray-600"}`}
                        >
                          {cfg.label}
                        </span>
                      </button>
                    );
                  })}
                </div>
                <p className="text-xs text-gray-500 mt-1.5">
                  {priorityConfig[form.priority].desc}
                </p>
              </div>

              {/* Quantity Required + Received */}
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label
                    htmlFor="quantity-required"
                    className="block text-sm font-medium text-gray-700 mb-1.5"
                  >
                    Quantity Required <span className="text-red-500">*</span>
                  </label>
                  <input
                    id="quantity-required"
                    type="number"
                    min={1}
                    value={form.quantity_required}
                    onChange={(e) =>
                      setForm((f) => ({
                        ...f,
                        quantity_required: parseInt(e.target.value) || 1,
                      }))
                    }
                    required
                    placeholder="e.g. 10"
                    className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 text-gray-900"
                  />
                </div>
                <div>
                  <label
                    htmlFor="quantity-received"
                    className="block text-sm font-medium text-gray-700 mb-1.5"
                  >
                    Quantity Received
                  </label>
                  <input
                    id="quantity-received"
                    type="number"
                    min={0}
                    value={form.quantity_received}
                    onChange={(e) =>
                      setForm((f) => ({
                        ...f,
                        quantity_received: parseInt(e.target.value) || 0,
                      }))
                    }
                    placeholder="e.g. 0"
                    className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 text-gray-900"
                  />
                </div>
              </div>

              {/* Unit */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">
                  Unit
                </label>
                <select
                  value={form.unit}
                  onChange={(e) =>
                    setForm((f) => ({
                      ...f,
                      unit: e.target.value as typeof form.unit,
                    }))
                  }
                  aria-label="Unit"
                  className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 bg-white text-gray-900"
                >
                  {Object.entries(unitLabels).map(([k, v]) => (
                    <option key={k} value={k}>
                      {v}
                    </option>
                  ))}
                </select>
              </div>

              {/* Description */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">
                  Description
                </label>
                <textarea
                  rows={3}
                  value={form.description}
                  onChange={(e) =>
                    setForm((f) => ({ ...f, description: e.target.value }))
                  }
                  placeholder="Optional details, specifications, context…"
                  className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 text-gray-900 placeholder:text-gray-400 resize-none"
                />
              </div>

              {error && (
                <div className="flex items-start gap-2 p-3 bg-red-50 border border-red-200 rounded-lg">
                  <svg
                    className="w-4 h-4 text-red-500 mt-0.5 flex-shrink-0"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M12 9v2m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"
                    />
                  </svg>
                  <p className="text-sm text-red-700">{error}</p>
                </div>
              )}
            </form>
          )}
        </div>

        {/* Footer */}
        {!success && (
          <div className="px-6 py-4 border-t border-gray-100 bg-gray-50 flex gap-3">
            <button
              type="button"
              onClick={onClose}
              className="flex-1 px-4 py-2.5 border border-gray-200 rounded-lg text-sm font-medium text-gray-700 hover:bg-gray-100 transition-colors"
            >
              Cancel
            </button>
            <button
              onClick={handleSubmit}
              disabled={submitting}
              className="flex-1 px-4 py-2.5 bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed text-white rounded-lg text-sm font-medium transition-colors flex items-center justify-center gap-2"
            >
              {submitting ? (
                <>
                  <svg
                    className="w-4 h-4 animate-spin"
                    fill="none"
                    viewBox="0 0 24 24"
                  >
                    <circle
                      className="opacity-25"
                      cx="12"
                      cy="12"
                      r="10"
                      stroke="currentColor"
                      strokeWidth="4"
                    />
                    <path
                      className="opacity-75"
                      fill="currentColor"
                      d="M4 12a8 8 0 018-8v8H4z"
                    />
                  </svg>
                  Saving…
                </>
              ) : (
                <>
                  <svg
                    className="w-4 h-4"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M5 13l4 4L19 7"
                    />
                  </svg>
                  Save Changes
                </>
              )}
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { 
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  BarChart, Bar, Legend, AreaChart, Area 
} from 'recharts';

interface DonationAnalytics {
  name: string; // Month/Year
  donations: number;
  fulfillment: number;
}

