            <h3 className="font-bold text-slate-900">Yearly Fulfillment Analysis</h3>
            <span className="px-2 py-1 bg-emerald-50 text-emerald-600 text-[10px] font-bold uppercase rounded">Yearly Growth</span>
          </div>
          <div className="h-[300px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={yearlyData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis 
                  dataKey="name" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fill: '#94a3b8', fontSize: 12 }}
                  dy={10}
                />
                <YAxis 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fill: '#94a3b8', fontSize: 12 }}
                />
                <Tooltip 
                  cursor={{ fill: '#f8fafc' }}
                  contentStyle={{ backgroundColor: '#fff', borderRadius: '12px', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                />
                <Legend verticalAlign="top" align="right" iconType="circle" />
                <Bar dataKey="donations" name="Donations" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={20} />
                <Bar dataKey="fulfillment" name="Fulfillment" fill="#10b981" radius={[4, 4, 0, 0]} barSize={20} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import {
  getOrganizations,
  createNeed,
  Organization,
  unitLabels,
} from "@/lib/api";

interface ManualNeedEntryFormProps {
  onClose: () => void;
  onSuccess: () => void;
  initialOrgId?: number;
  initialSectionId?: number;
}

const defaultForm = {
  name: "",
  priority: "ESSENTIAL" as "CRITICAL" | "ESSENTIAL" | "NICE",
  quantity_required: 1,
  unit: "UNIT" as "UNIT" | "BOX" | "KG" | "LITER",
  description: "",
  organization_id: "",
  section_id: "",
};

export default function ManualNeedEntryForm({
  onClose,
  onSuccess,
  initialOrgId,
  initialSectionId,
}: ManualNeedEntryFormProps) {
  const [form, setForm] = useState({
    ...defaultForm,
    organization_id: initialOrgId ? String(initialOrgId) : "",
    section_id: initialSectionId ? String(initialSectionId) : "",
  });
  const [organizations, setOrganizations] = useState<Organization[]>([]);
  const [loadingOrgs, setLoadingOrgs] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  useEffect(() => {
    getOrganizations()
      .then(setOrganizations)
      .catch(() =>
        setError(
          "Could not load organizations. Make sure the backend is running.",
        ),
      )
      .finally(() => setLoadingOrgs(false));
  }, []);

  const selectedOrg = Array.isArray(organizations)
    ? organizations.find((o) => o.id.toString() === form.organization_id)
    : undefined;
  const sections = selectedOrg?.sections ?? [];

  function handleOrgChange(orgId: string) {
    setForm((f) => ({ ...f, organization_id: orgId, section_id: "" }));
  }

  async function submitForm() {
    setError(null);

    if (!form.section_id) {
      setError("Please select an organization and section.");
      return;
    }
    if (!form.name.trim()) {
      setError("Need name is required.");
      return;
    }
    if (form.quantity_required < 1) {
      setError("Quantity must be at least 1.");
      return;
    }

    setSubmitting(true);
    try {
      await createNeed({
        name: form.name.trim(),
        priority: form.priority,
        quantity_required: form.quantity_required,
        unit: form.unit,
        description: form.description.trim(),
        section: parseInt(form.section_id),
      });

      setSuccess(true);
      setTimeout(() => {
        onSuccess();
        onClose();
      }, 1200);
    } catch (err: any) {
      console.error("Error saving need:", err);
      const errorMessage =
        err?.message ||
        "Failed to save the need. Please check your inputs and try again.";
      setError(errorMessage);
    } finally {
      setSubmitting(false);
    }
  }

  const priorityConfig = {
    CRITICAL: {
      dot: "bg-red-500",
      ring: "ring-red-300",
      label: "Critical",
      desc: "Urgent — must be addressed immediately",
    },
    ESSENTIAL: {
      dot: "bg-yellow-500",
      ring: "ring-yellow-300",
      label: "Essential",
      desc: "Important but not life-threatening",
    },
    NICE: {
      dot: "bg-green-500",
      ring: "ring-green-300",
      label: "Nice to Have",
      desc: "Helpful but not urgent",
    },
  };

  return (
    /* Backdrop */
    <div
      className="fixed inset-0 z-50 flex items-center justify-end bg-black/40"
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      {/* Slide-in panel from the right */}
      <div className="h-full w-full max-w-lg bg-white shadow-2xl flex flex-col overflow-hidden animate-slide-in-right">
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-5 border-b border-gray-100 bg-gradient-to-r from-blue-600 to-blue-700">
          <div>
            <h2 className="text-lg font-semibold text-white">
              Add Need Manually
            </h2>
            <p className="text-blue-200 text-sm mt-0.5">
              Enter a new need directly into the system
            </p>
          </div>
          <button
            type="button"
            onClick={onClose}
            aria-label="Close dialog"
            className="w-8 h-8 flex items-center justify-center rounded-full bg-white/20 hover:bg-white/30 text-white transition-colors"
          >
            <svg
              className="w-4 h-4"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M6 18L18 6M6 6l12 12"
              />
            </svg>
          </button>
        </div>

        {/* Form body */}
        <div className="flex-1 overflow-y-auto px-6 py-6">
          {success ? (
            <div className="flex flex-col items-center justify-center h-full gap-4 text-center">
              <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center">
                <svg
                  className="w-8 h-8 text-green-600"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M5 13l4 4L19 7"
                  />
                </svg>
              </div>
              <h3 className="text-xl font-semibold text-gray-900">
                Need Added!
              </h3>
              <p className="text-gray-500 text-sm">
                Redirecting you to All Needs…
              </p>
            </div>
          ) : (
            <form
              onSubmit={(e) => {
                e.preventDefault();
                submitForm();
              }}
              className="space-y-5"
            >
              {/* Organization */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">
                  Organization <span className="text-red-500">*</span>
                </label>
                {loadingOrgs ? (
                  <div className="h-10 bg-gray-100 rounded-lg animate-pulse" />
                ) : organizations.length === 0 ? (
                  <div className="p-3 bg-amber-50 border border-amber-200 rounded-lg text-sm text-amber-800">
                    No organizations found. Please create an organization first.
                  </div>
                ) : (
                  <select
                    value={form.organization_id}
                    onChange={(e) => handleOrgChange(e.target.value)}
                    required
                    title="Organization"
                    aria-label="Organization"
                    className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white text-gray-900"
                  >
                    <option value="">Select organization…</option>
                    {Array.isArray(organizations)
                      ? organizations.map((org) => (
                          <option key={org.id} value={org.id}>
                            {org.name} — {org.district}
                          </option>
                        ))
                      : null}
                  </select>
                )}
              </div>

              {/* Section */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">
                  Section / Department <span className="text-red-500">*</span>
                </label>
                <select
                  value={form.section_id}
                  onChange={(e) =>
                    setForm((f) => ({ ...f, section_id: e.target.value }))
                  }
                  required
                  disabled={!form.organization_id || sections.length === 0}
                  aria-label="Section / Department"
                  title="Section / Department"
                  className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white text-gray-900 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  <option value="">
                    {!form.organization_id
                      ? "Select an organization first"
                      : sections.length === 0
                        ? "No sections in this organization"
                        : "Select section…"}
                  </option>
                  {sections.map((sec) => (
                    <option key={sec.id} value={sec.id}>
                      {sec.name}
                      {sec.head_of_section ? ` — ${sec.head_of_section}` : ""}
                    </option>
                  ))}
                </select>
              </div>

              <hr className="border-gray-100" />

              {/* Need Name */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">
                  Need Item Name <span className="text-red-500">*</span>
                </label>
                <input
                  type="text"
                  value={form.name}
                  onChange={(e) =>
                    setForm((f) => ({ ...f, name: e.target.value }))
                  }
                  placeholder="e.g., Saline Bottles, Surgical Gloves, Rice Bags…"
                  required
                  className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 text-gray-900 placeholder:text-gray-400"
                />
              </div>

              {/* Priority */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Priority Level <span className="text-red-500">*</span>
                </label>
                <div className="grid grid-cols-3 gap-2">
                  {(["CRITICAL", "ESSENTIAL", "NICE"] as const).map((p) => {
                    const cfg = priorityConfig[p];
                    const selected = form.priority === p;
                    return (
                      <button
                        key={p}
                        type="button"
                        onClick={() => setForm((f) => ({ ...f, priority: p }))}
                        className={`flex flex-col items-center gap-1.5 p-3 rounded-lg border-2 text-center transition-all ${
                          selected
                            ? `border-current ring-2 ${cfg.ring} bg-gray-50`
                            : "border-gray-200 hover:border-gray-300 bg-white"
                        }`}
                      >
                        <span className={`w-3 h-3 rounded-full ${cfg.dot}`} />
                        <span
                          className={`text-xs font-semibold ${selected ? "text-gray-900" : "text-gray-600"}`}
                        >
                          {cfg.label}
                        </span>
                      </button>
                    );
                  })}
                </div>
                <p className="text-xs text-gray-500 mt-1.5">
                  {priorityConfig[form.priority].desc}
                </p>
              </div>

              {/* Quantity + Unit */}
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1.5">
                    Quantity Required <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="number"
                    min={1}
                    value={form.quantity_required}
                    onChange={(e) =>
                      setForm((f) => ({
                        ...f,
                        quantity_required: parseInt(e.target.value) || 1,
                      }))
                    }
                    required
                    title="Quantity Required"
                    className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 text-gray-900"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1.5">
                    Unit
                  </label>
                  <select
                    value={form.unit}
                    onChange={(e) =>
                      setForm((f) => ({
                        ...f,
                        unit: e.target.value as typeof form.unit,
                      }))
                    }
                    aria-label="Unit"
                    className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white text-gray-900"
                  >
                    {Object.entries(unitLabels).map(([k, v]) => (
                      <option key={k} value={k}>
                        {v}
                      </option>
                    ))}
                  </select>
                </div>
              </div>

              {/* Description */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">
                  Description
                </label>
                <textarea
                  rows={3}
                  value={form.description}
                  onChange={(e) =>
                    setForm((f) => ({ ...f, description: e.target.value }))
                  }
                  placeholder="Optional details, specifications, context…"
                  className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 text-gray-900 placeholder:text-gray-400 resize-none"
                />
              </div>

              {/* Error */}
              {error && (
                <div className="flex items-start gap-2 p-3 bg-red-50 border border-red-200 rounded-lg">
                  <svg
                    className="w-4 h-4 text-red-500 mt-0.5 flex-shrink-0"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M12 9v2m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"
                    />
                  </svg>
                  <p className="text-sm text-red-700">{error}</p>
                </div>
              )}
            </form>
          )}
        </div>

        {/* Footer actions */}
        {!success && (
          <div className="px-6 py-4 border-t border-gray-100 bg-gray-50 flex gap-3">
            <button
              type="button"
              onClick={onClose}
              className="flex-1 px-4 py-2.5 border border-gray-200 rounded-lg text-sm font-medium text-gray-700 hover:bg-gray-100 transition-colors"
            >
              Cancel
            </button>
            <button
              onClick={() => submitForm()}
              disabled={submitting || loadingOrgs}
              className="flex-1 px-4 py-2.5 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed text-white rounded-lg text-sm font-medium transition-colors flex items-center justify-center gap-2"
            >
              {submitting ? (
                <>
                  <svg
                    className="w-4 h-4 animate-spin"
                    fill="none"
                    viewBox="0 0 24 24"
                  >
                    <circle
                      className="opacity-25"
                      cx="12"
                      cy="12"
                      r="10"
                      stroke="currentColor"
                      strokeWidth="4"
                    />
                    <path
                      className="opacity-75"
                      fill="currentColor"
                      d="M4 12a8 8 0 018-8v8H4z"
                    />
                  </svg>
                  Saving…
                </>
              ) : (
                <>
                  <svg
                    className="w-4 h-4"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M12 4v16m8-8H4"
                    />
                  </svg>
                  Add Need
                </>
              )}
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { useEffect, useRef, useState } from "react";
import { useAuth } from "@/lib/AuthContext";
import { updateCurrentUser } from "@/lib/api";
import { Search, UserCircle } from "lucide-react";

export default function Navbar() {
  const pathname = usePathname();
  const router = useRouter();
  const { user, logout, setUser } = useAuth();
  const [showProfile, setShowProfile] = useState(false);
  const [activeTab, setActiveTab] = useState<"info" | "password">("info");
  const [searchQuery, setSearchQuery] = useState("");
  const panelRef = useRef<HTMLDivElement>(null);

  const navRef = useRef<HTMLElement>(null);

  // Close panel on outside click
  useEffect(() => {
    function handleClick(e: MouseEvent) {
      if (panelRef.current && !panelRef.current.contains(e.target as Node)) {
        setShowProfile(false);
      }
    }
    if (showProfile) document.addEventListener("mousedown", handleClick);
    return () => document.removeEventListener("mousedown", handleClick);
  }, [showProfile]);

  const [saving, setSaving] = useState(false);
  const [profileError, setProfileError] = useState<string | null>(null);
  const [profileSuccess, setProfileSuccess] = useState<string | null>(null);
  const [profileForm, setProfileForm] = useState({
    first_name: user?.first_name || "",
    last_name: user?.last_name || "",
    email: user?.email || "",
  });

  const handleProfileSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    setProfileError(null);
    setProfileSuccess(null);
    try {
      const updated = await updateCurrentUser(profileForm);
      setUser(updated);
      setProfileSuccess("Profile updated successfully.");
    } catch (err: unknown) {
      setProfileError(
        err instanceof Error ? err.message : "Failed to update profile.",
      );
    } finally {
      setSaving(false);
    }
  };

  const [passwordForm, setPasswordForm] = useState({
    current_password: "",
    new_password: "",
    new_password2: "",
  });

  const handlePasswordSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    setProfileError(null);
    setProfileSuccess(null);
    try {
      await updateCurrentUser(passwordForm);
      setPasswordForm({
        current_password: "",
        new_password: "",
        new_password2: "",
      });
      setProfileSuccess("Password changed successfully.");
    } catch (err: unknown) {
      setProfileError(
        err instanceof Error ? err.message : "Failed to change password.",
      );
    } finally {
      setSaving(false);
    }
  };

  const isAdmin = user?.role === "ADMIN" || user?.role === "ORG_ADMIN";

  const handleSearch = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (searchQuery.trim()) {
      router.push(`/search?q=${encodeURIComponent(searchQuery)}`);
      setSearchQuery("");
    }
  };

  const publicNavLinks = [
    { href: "/", label: "Home" },
    { href: "/needs", label: "Current Needs" },
  ];

  const navLinks = isAdmin
    ? [
        { href: "/", label: "Dashboard" },
        { href: "/organizations", label: "Organizations" },
        { href: "/needs", label: "All Needs" },
        ...(user?.role === "ADMIN"
          ? [{ href: "/admin/approvals", label: "Approvals" }]
          : []),
        ...(user?.role === "ORG_ADMIN"
          ? [
              { href: "/documents", label: "Documents" },
              { href: "/admin/donations", label: "Donations" },
            ]
          : []),
      ]
    : [
        { href: "/", label: "Dashboard" },
        { href: "/needs", label: "Current Needs" },
      ];

  const handleNavMouseMove = (e: React.MouseEvent<HTMLElement>) => {
    const navEl = navRef.current;
    if (!navEl) return;
    const rect = navEl.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    navEl.style.setProperty("--mx", `${x}px`);
    navEl.style.setProperty("--my", `${y}px`);
  };

  return (
    <nav
      ref={navRef}
      onMouseMove={handleNavMouseMove}
      className="bg-white/90 backdrop-blur-md border-b border-gray-100 sticky top-0 z-50"
    >
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-20">
          <div className="flex items-center w-full justify-between">
            <div className="flex items-center">
              {/* Logo */}
              <div className="flex-shrink-0 flex items-center mr-12">
                <Link href="/" className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center shadow-lg shadow-blue-500/20">
                    <svg
                      className="w-6 h-6 text-white"
                      fill="none"
                      stroke="currentColor"
                      viewBox="0 0 24 24"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z"
                      />
                    </svg>
                  </div>
                  <div className="flex flex-col">
                    <span className="font-bold text-xl text-slate-900 leading-tight tracking-tight">
                      NeedTracker
                    </span>
                    <span className="text-[10px] text-slate-500 font-medium uppercase tracking-wider">
                      Hospital Donation Platform
                    </span>
                  </div>
                </Link>
              </div>

              {/* Navigation Links */}
              <div className="hidden md:flex items-center space-x-8">
                {user?.role === "ADMIN" || user?.role === "ORG_ADMIN" ? (
                  <>
                    <Link
                      href={user.role === "ADMIN" ? "/admin" : "/org-admin"}
                      className={`text-sm font-semibold transition-colors ${pathname === "/admin" || pathname === "/org-admin" ? "text-blue-600" : "text-slate-600 hover:text-blue-600"}`}
                    >
                      Dashboard
                    </Link>
                    <Link
                      href="/organizations"
                      className={`text-sm font-semibold transition-colors ${pathname === "/organizations" ? "text-blue-600" : "text-slate-600 hover:text-blue-600"}`}
                    >
                      Organizations
                    </Link>
                    <Link
                      href="/needs"
                      className={`text-sm font-semibold transition-colors ${pathname === "/needs" ? "text-blue-600" : "text-slate-600 hover:text-blue-600"}`}
                    >
                      All Needs
                    </Link>
                    {user.role === "ORG_ADMIN" && (
                      <>
                        <Link
                          href="/documents"
                          className={`text-sm font-semibold transition-colors ${pathname === "/documents" ? "text-blue-600" : "text-slate-600 hover:text-blue-600"}`}
                        >
                          Documents
                        </Link>
                        <Link
                          href="/admin/donations"
                          className={`text-sm font-semibold transition-colors ${pathname === "/admin/donations" ? "text-blue-600" : "text-slate-600 hover:text-blue-600"}`}
                        >
                          Donations
                        </Link>
                      </>
                    )}
                    {user.role === "ADMIN" && (
                      <Link
                        href="/admin/approvals"
                        className={`text-sm font-semibold transition-colors ${pathname === "/admin/approvals" ? "text-blue-600" : "text-slate-600 hover:text-blue-600"}`}
                      >
                        Approvals
                      </Link>
                    )}
                  </>
                ) : (
                  <>
                    <Link
                      href="/#how-it-works"
                      className="text-sm font-medium text-slate-600 hover:text-blue-600 transition-colors"
                    >
                      How it works
                    </Link>
                    <Link
                      href="/needs"
                      className="text-sm font-medium text-slate-600 hover:text-blue-600 transition-colors"
                    >
                      Current Needs
                    </Link>
                    <Link
                      href="/#impact"
                      className="text-sm font-medium text-slate-600 hover:text-blue-600 transition-colors"
                    >
                      Impact
                    </Link>
                  </>
                )}
              </div>
            </div>

            {/* Right side */}
            <div className="flex items-center gap-6">
              {/* Search Bar */}
              <div className="hidden lg:block relative">
                <Search
                  className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"
                  size={16}
                />
                <input
                  type="text"
                  placeholder="Search.."
                  className="pl-9 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20 w-40 transition-all"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === "Enter" && searchQuery.trim()) {
                      router.push(
                        `/search?q=${encodeURIComponent(searchQuery)}`,
                      );
                      setSearchQuery("");
                    }
                  }}
                />
              </div>

              {!user ? (
                <div className="flex items-center gap-6">
                  <Link
                    href="/login"
                    className="text-sm font-semibold text-slate-700 hover:text-blue-600 transition-colors"
                  >
                    Sign In
                  </Link>
                  <Link
                    href="/login?tab=register"
                    className="text-sm font-bold text-white bg-blue-600 hover:bg-blue-700 px-6 py-3 rounded-lg shadow-lg shadow-blue-600/20 transition-all transform hover:-translate-y-0.5 active:translate-y-0"
                  >
                    Become a Donor
                  </Link>
                </div>
              ) : (
                <div
                  className="flex items-center gap-4 relative"
                  ref={panelRef}
                >
                  {(user.role === "ADMIN" || user.role === "ORG_ADMIN") && (
                    <div className="hidden sm:flex flex-col items-end mr-1">
                      <span className="text-[10px] font-bold text-blue-600 uppercase tracking-widest bg-blue-50 px-2 py-0.5 rounded border border-blue-100">
                        {user.role === "ADMIN" ? "Admin" : "Org Admin"}
                      </span>
                      <span className="text-[9px] text-slate-400 font-medium">
                        {user.role === "ADMIN" ? "System Access" : "Management"}
                      </span>
                    </div>
                  )}
                  <button
                    onClick={() => setShowProfile(!showProfile)}
                    className="w-10 h-10 bg-blue-50 rounded-full flex items-center justify-center text-blue-600 font-bold border border-blue-100 hover:bg-blue-100 transition-colors"
                  >
                    {user.username.charAt(0).toUpperCase()}
                  </button>

                  {/* Profile panel */}
                  {showProfile && (
                    <div className="absolute right-0 top-12 w-64 bg-white rounded-xl shadow-2xl border border-gray-100 z-50 overflow-hidden animate-scale-up">
                      {/* Header */}
                      <div className="bg-gradient-to-r from-blue-600 to-indigo-700 px-5 py-4">
                        <div className="flex items-center gap-3">
                          <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center text-white font-bold text-lg">
                            {user.username.charAt(0).toUpperCase()}
                          </div>
                          <div>
                            <p className="text-white font-semibold text-sm">
                              {user.username}
                            </p>
                            <p className="text-blue-100 text-[10px] uppercase tracking-wider font-bold">
                              {user.role}
                            </p>
                          </div>
                        </div>
                      </div>

                      <div className="p-2">
                        <Link
                          href="/profile"
                          onClick={() => setShowProfile(false)}
                          className="flex items-center gap-3 px-4 py-2.5 text-sm font-medium text-slate-700 hover:bg-blue-50 hover:text-blue-600 rounded-lg transition-colors group"
                        >
                          <UserCircle
                            size={18}
                            className="text-slate-400 group-hover:text-blue-600"
                          />
                          My Profile
                        </Link>

                        <button
                          onClick={() => {
                            setShowProfile(false);
                            logout();
                          }}
                          className="w-full flex items-center gap-3 px-4 py-2.5 text-sm font-medium text-slate-700 hover:bg-rose-50 hover:text-rose-600 rounded-lg transition-colors group border-t border-slate-50 mt-1 pt-3"
                        >
                          <svg
                            className="w-[18px] h-[18px] text-slate-400 group-hover:text-rose-600"
                            fill="none"
                            stroke="currentColor"
                            viewBox="0 0 24 24"
                          >
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={2}
                              d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1"
                            />
                          </svg>
                          Sign out
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </nav>
  );
}

"use client";

import { useState } from "react";
import { useAuth } from "@/lib/AuthContext";
import {
  NeedItem,
  priorityColors,
  priorityLabels,
  unitLabels,
} from "@/lib/api";
import DonateModal from "./DonateModal";
import { Heart, LogIn } from "lucide-react";
import Link from "next/link";
import "./NeedCard.css";

interface NeedCardProps {
  need: NeedItem;
  showSection?: boolean;
  sectionName?: string;
  organizationName?: string;
  onDonationSuccess?: () => void;
  onEdit?: () => void;
  onDelete?: () => void;
}

export default function NeedCard({
  need,
  showSection,
  sectionName,
  organizationName,
  onDonationSuccess,
  onEdit,
  onDelete,
}: NeedCardProps) {
  const { user } = useAuth();
  const [isDonateModalOpen, setIsDonateModalOpen] = useState(false);

  const progress =
    need.quantity_required > 0
      ? Math.min((need.quantity_received / need.quantity_required) * 100, 100)
      : 0;

  const remaining = need.quantity_required - need.quantity_received;
  const isFulfilled = remaining <= 0;

  const handleDonationSuccess = () => {
    setIsDonateModalOpen(false);
    onDonationSuccess?.();
  };

  return (
    <>
      <div className="bg-white rounded-lg shadow-sm border border-gray-100 p-4 hover:shadow-md transition-shadow">
        <div className="flex items-start justify-between mb-3">
          <div className="flex-1">
            <h3 className="font-semibold text-gray-900">{need.name}</h3>
            {organizationName && (
              <p className="text-xs text-gray-700 font-medium">
                {organizationName}
              </p>
            )}
            {showSection && sectionName && (
              <p className="text-sm text-gray-500">{sectionName}</p>
            )}
          </div>
          <div className="flex items-center gap-2">
            <span
              className={`px-2.5 py-1 text-xs font-medium rounded-full border ${priorityColors[need.priority]}`}
            >
              {priorityLabels[need.priority]}
            </span>
            {onEdit && (
              <button
                onClick={onEdit}
                className="p-1 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded transition-colors"
                title="Edit"
              >
                <svg
                  className="w-4 h-4"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"
                  />
                </svg>
              </button>
            )}
            {onDelete && (
              <button
                onClick={onDelete}
                className="p-1 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded transition-colors"
                title="Delete"
              >
                <svg
                  className="w-4 h-4"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"
                  />
                </svg>
              </button>
            )}
          </div>
        </div>

        {need.description && (
          <p className="text-sm text-gray-600 mb-3 line-clamp-2">
            {need.description}
          </p>
        )}

        {/* Progress Bar */}
        <div className="mb-3">
          <div className="flex justify-between text-sm mb-1">
            <span className="text-gray-600">Progress</span>
            <span className="font-medium text-gray-900">
              {progress.toFixed(0)}%
            </span>
          </div>
          <div className="h-2 bg-gray-100 rounded-full overflow-hidden">
            <div
              className={`need-card__progress-fill ${
                progress >= 100
                  ? "need-card__progress-fill--complete"
                  : progress >= 75
                    ? "need-card__progress-fill--75to100"
                    : progress >= 50
                      ? "need-card__progress-fill--50to75"
                      : progress >= 25
                        ? "need-card__progress-fill--25to50"
                        : "need-card__progress-fill--0to25"
              }`}
              data-progress={Math.round(progress)}
            />
          </div>
        </div>

        {/* Quantities */}
        <div className="flex justify-between text-sm mb-4">
          <div>
            <span className="text-gray-500">Received: </span>
            <span className="font-medium text-green-600">
              {need.quantity_received} {unitLabels[need.unit]}
            </span>
          </div>
          <div>
            <span className="text-gray-500">Needed: </span>
            <span
              className={`font-medium ${remaining > 0 ? "text-red-600" : "text-green-600"}`}
            >
              {remaining > 0 ? remaining : 0} {unitLabels[need.unit]}
            </span>
          </div>
        </div>

        {/* Donate Button - Hide for ADMIN and ORG_ADMIN users */}
        {remaining > 0 &&
          user?.role !== "ADMIN" &&
          user?.role !== "ORG_ADMIN" && (
            <>
              {user ? (
                <button
                  onClick={() => setIsDonateModalOpen(true)}
                  className="w-full px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors font-medium text-sm flex items-center justify-center gap-2"
                >
                  <Heart size={18} />
                  Donate
                </button>
              ) : (
                <Link href="/login">
                  <button className="w-full px-4 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700 transition-colors font-medium text-sm flex items-center justify-center gap-2">
                    <LogIn size={18} />
                    Sign in to Donate
                  </button>
                </Link>
              )}
            </>
          )}
        {remaining <= 0 && (
          <div className="w-full px-4 py-2 bg-green-100 text-green-800 rounded-lg text-center font-medium text-sm">
            ✓ Requirement Fulfilled
          </div>
        )}
      </div>

      {/* Donate Modal */}
      <DonateModal
        needItem={need}
        isOpen={isDonateModalOpen}
        onClose={() => setIsDonateModalOpen(false)}
        onSuccess={handleDonationSuccess}
      />
    </>
  );
}

import Link from "next/link";
import { Organization } from "@/lib/api";

const orgTypeConfig: Record<
  string,
  { label: string; gradient: string; badge: string }
> = {
  HOSPITAL: {
    label: "Hospital",
    gradient: "from-blue-600 to-blue-800",
    badge: "bg-blue-100 text-blue-800",
  },
  CLINIC: {
    label: "Clinic",
    gradient: "from-cyan-600 to-cyan-800",
    badge: "bg-cyan-100 text-cyan-800",
  },
  SCHOOL: {
    label: "School",
    gradient: "from-violet-600 to-violet-800",
    badge: "bg-violet-100 text-violet-800",
  },
  NGO: {
    label: "NGO",
    gradient: "from-emerald-600 to-emerald-800",
    badge: "bg-emerald-100 text-emerald-800",
  },
  CHARITY: {
    label: "Charity",
    gradient: "from-rose-600 to-rose-800",
    badge: "bg-rose-100 text-rose-800",
  },
  GOVERNMENT: {
    label: "Government",
    gradient: "from-slate-600 to-slate-800",
    badge: "bg-slate-100 text-slate-800",
  },
  OTHER: {
    label: "Organization",
    gradient: "from-gray-600 to-gray-800",
    badge: "bg-gray-100 text-gray-800",
  },
};

interface OrganizationCardProps {
  organization: Organization;
}

export default function OrganizationCard({
  organization,
}: OrganizationCardProps) {
  const type = orgTypeConfig[organization.org_type || "OTHER"];

  const allNeeds =
    organization.sections?.reduce(
      (acc, section) => acc + (section.needs?.length || 0),
      0,
    ) || 0;

  const unfulfilledNeeds =
    organization.sections?.reduce(
      (acc, section) =>
        acc +
        (section.needs?.filter((n) => n.quantity_received < n.quantity_required)
          .length || 0),
      0,
    ) || 0;

  const criticalUnfulfilledNeeds =
    organization.sections?.reduce(
      (acc, section) =>
        acc +
        (section.needs?.filter(
          (n) =>
            n.priority === "CRITICAL" &&
            n.quantity_received < n.quantity_required,
        ).length || 0),
      0,
    ) || 0;

  const fulfilledNeeds =
    organization.sections?.reduce(
      (acc, section) =>
        acc +
        (section.needs?.filter(
          (n) => n.quantity_received >= n.quantity_required,
        ).length || 0),
      0,
    ) || 0;

  // Calculate average progress of unfulfilled needs
  let avgProgress = 0;
  if (unfulfilledNeeds > 0) {
    const totalProgress =
      organization.sections?.reduce(
        (acc, section) =>
          acc +
          (section.needs?.reduce((sAcc, need) => {
            if (need.quantity_received < need.quantity_required) {
              return (
                sAcc + (need.quantity_received / need.quantity_required) * 100
              );
            }
            return sAcc;
          }, 0) || 0),
        0,
      ) || 0;
    avgProgress = Math.round(totalProgress / unfulfilledNeeds);
  }

  // For display purposes, show unfulfilled as "totalNeeds"
  const displayTotalNeeds = unfulfilledNeeds;

  return (
    <Link href={`/organizations/${organization.id}`}>
      <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden hover:shadow-xl hover:-translate-y-1 transition-all duration-200 cursor-pointer group h-full flex flex-col">
        {/* Coloured gradient header */}
        <div
          className={`bg-gradient-to-br ${type.gradient} px-5 py-5 text-white`}
        >
          <div className="flex items-start justify-between mb-3">
            <span
              className={`inline-block px-2.5 py-1 rounded-full text-xs font-semibold ${type.badge}`}
            >
              {type.label}
            </span>
            {criticalUnfulfilledNeeds > 0 && (
              <span className="flex items-center gap-1 bg-red-500 text-white text-xs font-bold px-2.5 py-1 rounded-full">
                <svg
                  className="w-3 h-3"
                  fill="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path d="M12 9v4m0 4h.01M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z" />
                </svg>
                {criticalUnfulfilledNeeds} critical
              </span>
            )}
          </div>
          <h3 className="font-bold text-white text-lg leading-tight group-hover:underline decoration-white/50">
            {organization.name}
          </h3>
          <p className="text-white/70 text-xs mt-1 flex items-center gap-1">
            <svg
              className="w-3.5 h-3.5"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z"
              />
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M15 11a3 3 0 11-6 0 3 3 0 016 0z"
              />
            </svg>
            {organization.district}
          </p>
        </div>

        {/* Body */}
        <div className="px-5 py-4 flex-1 flex flex-col">
          {/* Description */}
          <p className="text-sm text-gray-600 line-clamp-2 mb-4 flex-1">
            {organization.description || (
              <span className="italic text-gray-400">No description yet.</span>
            )}
          </p>

          {/* Stats row */}
          <div className="flex items-center gap-4 text-sm text-gray-500 mb-3">
            <span className="flex items-center gap-1">
              <svg
                className="w-4 h-4 text-blue-400"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10"
                />
              </svg>
              {organization.sections?.length || 0} sections
            </span>
            <span className="text-gray-300">·</span>
            <span>{displayTotalNeeds} needs</span>
            {organization.established_year && (
              <>
                <span className="text-gray-300">·</span>
                <span>Est. {organization.established_year}</span>
              </>
            )}
          </div>

          {/* Fulfillment bar */}
          {unfulfilledNeeds > 0 && (
            <div>
              <div className="flex justify-between text-xs text-gray-400 mb-1">
                <span>Needs progress</span>
                <span className="font-medium text-gray-600">
                  {avgProgress}%
                </span>
              </div>
              <progress
                value={avgProgress}
                max={100}
                className="w-full h-1.5 rounded-full overflow-hidden [appearance:none] [&::-webkit-progress-bar]:bg-gray-100 [&::-webkit-progress-value]:bg-green-400 [&::-moz-progress-bar]:bg-green-400"
                aria-label="Needs progress"
              />
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="px-5 py-3 border-t border-gray-100 bg-gray-50 flex items-center justify-between">
          <span className="text-xs text-gray-400">
            Reg: {organization.registration_number}
          </span>
          <span className="text-xs font-medium text-blue-600 group-hover:text-blue-700 flex items-center gap-1">
            View details
            <svg
              className="w-3.5 h-3.5"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M9 5l7 7-7 7"
              />
            </svg>
          </span>
        </div>
      </div>
    </Link>
  );
}

