'use client';

import { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { loginUser, registerUser, registerOrgAdmin, getCurrentUser, User } from '@/lib/api';
import { useRouter } from 'next/navigation';

interface AuthContextType {
  user: User | null;
  isAuthenticated: boolean;
  loading: boolean;
  error: string | null;
  login: (username: string, password: string) => Promise<void>;
  register: (data: {
    username: string;
    email: string;
    password: string;
    password2: string;
    phone_number: string;
  }) => Promise<void>;
  registerOrgAdmin: (data: {
    username: string;
    password: string;
    password2: string;
    email: string;
    phone_number: string;
    first_name: string;
    last_name: string;
    organization_name: string;
  }) => Promise<void>;
  logout: () => void;
  clearError: () => void;
  setUser: (user: User | null) => void;
}

export const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within AuthProvider');
  }
  return context;
}

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const router = useRouter();

  // Load user on mount if token exists
  useEffect(() => {
    const loadUser = async () => {
      try {
        const token = localStorage.getItem('accessToken');
        if (token) {
          const currentUser = await getCurrentUser();
          setUser(currentUser);
        }
      } catch (err) {
        // Token might be invalid
        localStorage.removeItem('accessToken');
        localStorage.removeItem('refreshToken');
      } finally {
        setLoading(false);
      }
    };

    loadUser();
  }, []);

  const login = async (username: string, password: string) => {
    setError(null);
    setLoading(true);
    try {
      const response = await loginUser(username, password);
      
      // Store tokens
      if (response.access) {
        localStorage.setItem('accessToken', response.access);
      }
      if (response.refresh) {
        localStorage.setItem('refreshToken', response.refresh);
      }

      // Fetch and set user
      const currentUser = await getCurrentUser();
      setUser(currentUser);

      // Redirect based on role
      if (currentUser.role === 'ADMIN') {
        router.push('/admin');
      } else if (currentUser.role === 'ORG_ADMIN') {
        router.push('/org-admin');
      } else {
        router.push('/needs');
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Login failed';
      setError(message);
      throw err;
    } finally {
      setLoading(false);
    }
  };

  const register = async (data: {
    username: string;
    email: string;
    password: string;
    password2: string;
    phone_number: string;
  }) => {
    setError(null);
    setLoading(true);
    try {
      const response = await registerUser(data);

      // Store tokens if provided
      if (response.access) {
        localStorage.setItem('accessToken', response.access);
      }
      if (response.refresh) {
        localStorage.setItem('refreshToken', response.refresh);
      }

      // Fetch and set user
      const currentUser = await getCurrentUser();
      setUser(currentUser);

      // Redirect
      router.push('/needs');
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Registration failed';
      setError(message);
      throw err;
    } finally {
      setLoading(false);
    }
  };

  const registerOrgAdminFunc = async (data: {
    username: string;
    password: string;
    password2: string;
    email: string;
    phone_number: string;
    first_name: string;
    last_name: string;
    organization_name: string;
  }) => {
    setError(null);
    setLoading(true);
    try {
      const response = await registerOrgAdmin(data);

      // Store tokens if provided
      if (response.access) {
        localStorage.setItem('accessToken', response.access);
      }
      if (response.refresh) {
        localStorage.setItem('refreshToken', response.refresh);
      }

      // Fetch and set user
      const currentUser = await getCurrentUser();
      setUser(currentUser);

      // Redirect
      router.push('/organizations');
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Organization Admin registration failed';
      setError(message);
      throw err;
    } finally {
      setLoading(false);
    }
  };

  const logout = () => {
    localStorage.removeItem('accessToken');
    localStorage.removeItem('refreshToken');
    setUser(null);
    setError(null);
    router.push('/login');
  };

  const clearError = () => {
    setError(null);
  };

  const updateUser = (updatedUser: User | null) => {
    setUser(updatedUser);
  };

  return (
    <AuthContext.Provider
      value={{
        user,
        isAuthenticated: !!user,
        loading,
        error,
        login,
        register,
        registerOrgAdmin: registerOrgAdminFunc,
        logout,
        clearError,
        setUser: updateUser,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

// API Configuration and Helper Functions

const API_BASE_URL =
  process.env.NEXT_PUBLIC_API_URL || "http://localhost:8000/api";

// Types based on Django models
export interface User {
  id: number;
  username: string;
  email: string;
  role: "ADMIN" | "ORG_ADMIN" | "DONOR";
  phone_number: string;
  first_name?: string;
  last_name?: string;
}

export interface AuthResponse {
  access: string;
  refresh: string;
  user?: User; // Optional because standard JWT response might only have tokens, but we'll try to include user or fetch it separately
}

export interface NeedItem {
  id: number;
  section: number;
  name: string;
  priority: "CRITICAL" | "ESSENTIAL" | "NICE";
  quantity_required: number;
  quantity_received: number;
  unit: "UNIT" | "BOX" | "KG" | "LITER";
  description: string;
  created_at: string;
  section_detail?: {
    id: number;
    name: string;
    organization: number;
    organization_name: string;
    created_by?: number;
    created_by_username?: string;
    created_by_role?: "ADMIN" | "ORG_ADMIN" | "DONOR";
  };
}

export interface Section {
  id: number;
  organization: number;
  name: string;
  head_of_section: string;
  needs: NeedItem[];
  created_by?: number;
  created_by_username?: string;
  created_by_role?: "ADMIN" | "ORG_ADMIN" | "DONOR";
}

export interface Organization {
  id: number;
  name: string;
  registration_number: string;
  address?: string;
  district: string;
  org_type?:
    | "HOSPITAL"
    | "CLINIC"
    | "SCHOOL"
    | "NGO"
    | "CHARITY"
    | "GOVERNMENT"
    | "OTHER";
  description?: string;
  phone?: string;
  email_contact?: string;
  website?: string;
  established_year?: number;
  sections: Section[];
}

export interface DocumentUpload {
  id: number;
  uploaded_by: number;
  organization: number;
  file: string;
  uploaded_at: string;
