// Search interface and function
export interface SearchResult {
  organizations: Organization[];
  needs: NeedItem[];
  total: number;
}

export async function search(
  query: string,
  type: "organization" | "need" | "all" = "all",
  options?: {
    priority?: string;
    org_type?: string;
    limit?: number;
    offset?: number;
    excludeFulfilled?: boolean;
  },
): Promise<SearchResult> {
  const params = new URLSearchParams({
    q: query,
    type,
    ...(options?.priority && { priority: options.priority }),
    ...(options?.org_type && { org_type: options.org_type }),
    ...(options?.excludeFulfilled && { exclude_fulfilled: "true" }),
    limit: String(options?.limit || 50),
    offset: String(options?.offset || 0),
  });

  const response = await fetch(`${API_BASE_URL}/search/?${params.toString()}`, {
    method: "GET",
    headers: {
      "Content-Type": "application/json",
    },
  });

  if (!response.ok) {
    throw new Error("Search failed");
  }

  return response.json();
}

"use client";

import { useEffect, useState } from "react";
import { useRouter, usePathname } from "next/navigation";
import { useAuth } from "./AuthContext";

export function useAuthGuard() {
  const { user, loading: isLoading } = useAuth();
  const router = useRouter();
  const pathname = usePathname();

  const authorized = !isLoading && (!!user || pathname === "/login");

  useEffect(() => {
    if (!isLoading) {
      if (!user && pathname !== "/login") {
        router.push("/login");
      }
    }
  }, [user, isLoading, router, pathname]);

  return { authorized, isLoading };
}

/**
 * Guard that requires ADMIN or ORG_ADMIN role.
 * Donors are redirected to the dashboard.
 */
export function useAdminGuard() {
  const { user, loading: isLoading } = useAuth();
  const router = useRouter();
  const pathname = usePathname();

  const authorized = !isLoading && (
    (user && user.role !== "DONOR") || 
    (!user && pathname === "/login")
  );

  useEffect(() => {
    if (!isLoading) {
      if (!user && pathname !== "/login") {
        router.push("/login");
      } else if (user && user.role === "DONOR") {
        router.push("/");
      }
    }
  }, [user, isLoading, router, pathname]);

  return { authorized: !!authorized, isLoading };
}
